using bf16 = __nv_bfloat16;

constexpr int H = 7168;
constexpr int ROWB = H * 2;     // bytes per row
constexpr int CH = H / 4 / 32;  // 56 vec4 chunks per lane
constexpr int MAXR = 9;
constexpr float INVH = 1.0f / 7168.0f;

// --------------------------------------------------------- packed f32x2 -----
// SM10x packed single-precision pairs with round-to-nearest are BIT-EXACT to
// scalar __fadd_rn/__fmul_rn/fmaf per lane (verified on-device: mul.rn.f32x2,
// add.rn.f32x2, fma.rn.f32x2, sub.rn.f32x2). They halve the instruction count
// of the elementwise loops while preserving the reference arithmetic order.
__device__ __forceinline__ unsigned long long pack_f2(float2 v) {
  unsigned long long u;
  *reinterpret_cast<float2*>(&u) = v;
  return u;
}
__device__ __forceinline__ float2 unpack_f2(unsigned long long u) {
  return *reinterpret_cast<float2*>(&u);
}
__device__ __forceinline__ float2 mul_x2(float2 a, float2 b) {
  unsigned long long r;
  asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(r) : "l"(pack_f2(a)), "l"(pack_f2(b)));
  return unpack_f2(r);
}
__device__ __forceinline__ float2 add_x2(float2 a, float2 b) {
  unsigned long long r;
  asm("add.rn.f32x2 %0, %1, %2;" : "=l"(r) : "l"(pack_f2(a)), "l"(pack_f2(b)));
  return unpack_f2(r);
}
// packed a*b+c (verified bit-exact to scalar fmaf on SM100a). Rounding differs
// from separate mul+add by <=1ulp of the product before the add; used in
// accumulation loops; correctness is checked against the public numerical policy.
__device__ __forceinline__ float2 fma_x2(float2 a, float2 b, float2 c) {
  unsigned long long r;
  asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(r) : "l"(pack_f2(a)), "l"(pack_f2(b)), "l"(pack_f2(c)));
  return unpack_f2(r);
}
// convert 4 bf16 packed in a uint2 to two float2 WITHOUT cvt: bf16 is the
// top 16 bits of fp32, so widening is one SHL + one LOP3 per pair (bit-exact
// for every bf16 pattern incl. denormals/inf/NaN). SASS check (development):
// the old __bfloat1622float2 sequence cost 84 int ops per 14-chunk unroll
// vs 55 here (-24 instructions, -11% in the score inner loop issue stream).
// 256-bit (32B) load, sm_100+: doubles bytes-in-flight per instruction vs
// LDG.E.128. Address must be 32B aligned.
__device__ __forceinline__ void ldg256(const void* p, uint4& a, uint4& b) {
  asm volatile("ld.global.nc.v8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
               : "=r"(a.x), "=r"(a.y), "=r"(a.z), "=r"(a.w), "=r"(b.x), "=r"(b.y), "=r"(b.z),
                 "=r"(b.w)
               : "l"(p));
}

__device__ __forceinline__ void cvt4_f2(uint2 q, float2& lo, float2& hi) {
  lo.x = __uint_as_float(q.x << 16);
  lo.y = __uint_as_float(q.x & 0xFFFF0000u);
  hi.x = __uint_as_float(q.y << 16);
  hi.y = __uint_as_float(q.y & 0xFFFF0000u);
}
__device__ __forceinline__ void prefetch_l2(const void* p) {
  asm volatile("prefetch.global.L2 [%0];" ::"l"(p));
}

// bulk L2 prefetch of a contiguous span (one instruction covers the span)
__device__ __forceinline__ void prefetch_l2_bulk(const void* p, unsigned bytes) {
  asm volatile("cp.async.bulk.prefetch.L2.global [%0], %1;" ::"l"(p), "r"(bytes));
}

// Programmatic Dependent Launch (PDL) helpers. When launched with the
// cudaLaunchAttributeProgrammaticStreamSerialization attribute, the next
// kernel on the stream may schedule its CTAs while this one drains; the
// dependent kernel then blocks in griddepcontrol.wait until this grid's
// memory is visible. No-op on non-PDL launches (flashinfer norm.cuh pattern).
__device__ __forceinline__ void pdl_wait() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
  asm volatile("griddepcontrol.wait;");
#endif
}

__device__ __forceinline__ void pdl_launch_dependents() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
  asm volatile("griddepcontrol.launch_dependents;");
#endif
}

static inline bool pdl_enabled() {
  static int flag = -1;
  if (flag < 0) {
    const char* s = getenv("K3_PDL");
    flag = (s && s[0] == '0') ? 0 : 1;
  }
  return flag != 0;
}

// development (tuning): opt-in plain cudaLaunchKernel launch
// path for the pre-resolved fast entries (K3Plan / forward_preres). Omits
// cudaLaunchKernelEx and its ProgrammaticStreamSerialization attribute
// entirely — same kernel function pointer, grid, block, smem, stream, and
// argument values as the Ex path; only the launch runtime call differs
// (no attribute processing, no PDL). Targeted at the launch-dominated
// T<=32 rows. Device-side griddepcontrol.wait is a no-op on non-PDL
// launches, so arithmetic stays bit-identical. K3_PLAIN=1 opts in.
static inline bool plain_launch_enabled() {
  static int flag = -1;
  if (flag < 0) {
    const char* s = getenv("K3_PLAIN");
    flag = (s && s[0] == '1') ? 1 : 0;
  }
  return flag != 0;
}

// Plain-launch helpers: marshal the exact argument values of the two
// pre-resolved kernel signatures into an explicit void* array and issue
// cudaLaunchKernel. Lean: (p, b, cw, ow, out, int T, int nvb, float eps).
// Std: (p, b, cw, ow, out, int T, long long stride_bm, float eps).
static inline void plain_launch_lean(
    void (*kern)(const bf16*, const bf16*, const bf16*, const bf16*, bf16*, int, int, float),
    unsigned grid, unsigned block, size_t smem, cudaStream_t stream, const bf16* p, const bf16* b,
    const bf16* cwp, const bf16* owp, bf16* op, int T, int nvb, float eps) {
  void* kargs[8] = {&p, &b, &cwp, &owp, &op, &T, &nvb, &eps};
  cudaLaunchKernel((const void*)kern, dim3(grid, 1, 1), dim3(block, 1, 1), kargs, smem, stream);
}
static inline void plain_launch_std(void (*kern)(const bf16*, const bf16*, const bf16*, const bf16*,
                                                 bf16*, int, long long, float),
                                    unsigned grid, unsigned block, size_t smem, cudaStream_t stream,
                                    const bf16* p, const bf16* b, const bf16* cwp, const bf16* owp,
                                    bf16* op, int T, long long stride_bm, float eps) {
  void* kargs[8] = {&p, &b, &cwp, &owp, &op, &T, &stride_bm, &eps};
  cudaLaunchKernel((const void*)kern, dim3(grid, 1, 1), dim3(block, 1, 1), kargs, smem, stream);
}

// Launch a single kernel with the PDL stream-serialization attribute when
// enabled; identical template/argument forwarding to the <<<>>> path.
template <typename KernT, typename... Args>
static inline void launch_pdl(KernT kern, unsigned grid, unsigned block, size_t smem,
                              cudaStream_t stream, Args... args) {
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(grid, 1, 1);
  cfg.blockDim = dim3(block, 1, 1);
  cfg.dynamicSmemBytes = smem;
  cfg.stream = stream;
  cudaLaunchAttribute attrs[1];
  attrs[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;
  attrs[0].val.programmaticStreamSerializationAllowed = pdl_enabled() ? 1 : 0;
  cfg.attrs = attrs;
  cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, kern, args...);
}

// store a float into the shared memory of cluster CTA `rank` (DSMEM)
__device__ __forceinline__ void st_cluster_f32(float* local_ptr, unsigned rank, float v) {
  unsigned addr;
  asm("mapa.shared::cluster.u32 %0, %1, %2;"
      : "=r"(addr)
      : "r"((unsigned)__cvta_generic_to_shared(local_ptr)), "r"(rank));
  asm volatile("st.shared::cluster.f32 [%0], %1;" ::"r"(addr), "f"(v));
}

// ---------------------------------------------------------------- fusedW ----
constexpr int NSLOT = 12;   // smem row slots (rotation)
constexpr int UNROLL = 28;  // slot loads in flight per score row (56%28==0)

template <int FW>
struct SmemF {
  static constexpr int ROWS = 0;
  static constexpr int OSQP = ROWS + NSLOT * ROWB;  // FW*32*4*4 B
  static constexpr int SCORE = OSQP + FW * 32 * 4 * 4;
  static constexpr int PROB = SCORE + MAXR * 4;
  static constexpr int BCAST = PROB + MAXR * 4;
  static constexpr int TOTAL = BCAST + 16;
};

__device__ __forceinline__ unsigned smem_u32(const void* p) {
  return (unsigned)__cvta_generic_to_shared(p);
}

// 1D bulk global->smem copy with mbarrier completion tracking (TMA)
