// cp.async.bulk.prefetch.L2.global: warm `bytes` of gmem into L2 with no
// destination and no completion tracking (sm_90+). Pure performance hint —
// no data hazard, output is bit-identical with or without it.
__device__ __forceinline__ void cp_bulk_prefetch_l2(const void* g, unsigned bytes) {
#if __CUDA_ARCH__ >= 900
  asm volatile("cp.async.bulk.prefetch.L2.global [%0], %1;\n" ::"l"(g), "r"(bytes) : "memory");
#else
  (void)g;
  (void)bytes;
#endif
}

__device__ __forceinline__ void cp16(void* dst, const void* src) {
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(smem_u32(dst)), "l"(src)
               : "memory");
}
__device__ __forceinline__ void cp_commit() {
  asm volatile("cp.async.commit_group;\n" ::: "memory");
}
template <int N>
__device__ __forceinline__ void cp_wait() {
  asm volatile("cp.async.wait_group %0;\n" ::"n"(N) : "memory");
}

// mbarrier producer/consumer handoff helpers (CTA scope). arrive carries
// .release at cta scope by default; try_wait carries .acquire.cta.
__device__ __forceinline__ void mbar_init(unsigned long long* b, unsigned count) {
  asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(smem_u32(b)), "r"(count));
}
__device__ __forceinline__ void mbar_arrive(unsigned long long* b) {
  asm volatile("mbarrier.arrive.shared::cta.b64 _, [%0];" ::"r"(smem_u32(b)) : "memory");
}
__device__ __forceinline__ void mbar_wait(unsigned long long* b, unsigned parity) {
  asm volatile(
      "{\n"
      ".reg .pred p;\n"
      "WAIT_%=:\n"
      "mbarrier.try_wait.parity.shared::cta.b64 p, [%0], %1;\n"
      "@!p bra WAIT_%=;\n"
      "}\n" ::"r"(smem_u32(b)),
      "r"(parity)
      : "memory");
}

// ---------------------------------------------------- CLC (SM100) ---------
// Cluster Launch Control work steal: asynchronously cancel a pending CTA of
// this grid and steal its blockIdx as the next work id. 2-deep ring of
// (result, mbarrier) so a fresh try_cancel never races consumer reads of the
// previous response (every thread waits each iteration; reuse distance 2).
__device__ __forceinline__ void clc_try_cancel(void* res, unsigned long long* bar) {
  asm volatile(
      "clusterlaunchcontrol.try_cancel.async.shared::cta"
      ".mbarrier::complete_tx::bytes.b128 [%0], [%1];" ::"r"(smem_u32(res)),
      "r"(smem_u32(bar))
      : "memory");
}
__device__ __forceinline__ void fence_proxy_async_cta() {
  asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
}
// decode a 16B response already held in registers: is_canceled + first ctaid.x
__device__ __forceinline__ bool clc_decode_x(ulonglong2 r, int& x) {
  unsigned ok;
  asm("{\n"
      ".reg .b128 resp;\n"
      "mov.b128 resp, {%1, %2};\n"
      ".reg .pred p;\n"
      "clusterlaunchcontrol.query_cancel.is_canceled.pred.b128 p, resp;\n"
      "selp.b32 %0, 1, 0, p;\n"
      "}"
      : "=r"(ok)
      : "l"(r.x), "l"(r.y));
  unsigned bx = 0;
  if (ok) {
    asm("{\n"
        ".reg .b128 resp;\n"
        "mov.b128 resp, {%1, %2};\n"
        "clusterlaunchcontrol.query_cancel.get_first_ctaid::x.b32.b128 %0, resp;\n"
        "}"
        : "=r"(bx)
        : "l"(r.x), "l"(r.y));
  }
  x = (int)bx;
  return ok != 0;
}

__device__ __forceinline__ float lane_tree_sum(float v) {
#pragma unroll
  for (int off = 16; off > 0; off >>= 1) v = __fadd_rn(v, __shfl_down_sync(0xffffffffu, v, off));
  return v;
}

// impl93 (tuning): two independent 16-lane partial subtrees folded in
// parallel (4 shfl rounds each, mutually independent) then combined; same
// total as lane_tree_sum but a shorter serial dependency chain.
__device__ __forceinline__ float lane_tree_sum2(float v) {
  float lo = v;
  float hi = __shfl_down_sync(0xffffffffu, v, 16);
#pragma unroll
  for (int off = 8; off > 0; off >>= 1) {
    lo = __fadd_rn(lo, __shfl_down_sync(0xffffffffu, lo, off));
    hi = __fadd_rn(hi, __shfl_down_sync(0xffffffffu, hi, off));
  }
  return __fadd_rn(lo, hi);
}

// one row (896 x 16B) issued by a full block
template <int FTHREADS>
__device__ __forceinline__ void issue_row_block(bf16* s_slot, const bf16* g_row, int tid) {
  const uint4* s4 = reinterpret_cast<const uint4*>(g_row);
  uint4* d4 = reinterpret_cast<uint4*>(s_slot);
#pragma unroll
  for (int u = 0; u < 2; ++u) {
    int idx = tid + u * FTHREADS;
    if (idx < ROWB / 16) cp16(d4 + idx, s4 + idx);
  }
}

// one row issued by a single warp (28 x 16B per lane)
__device__ __forceinline__ void issue_row_warp(bf16* s_slot, const bf16* g_row, int lane) {
  const uint4* s4 = reinterpret_cast<const uint4*>(g_row);
  uint4* d4 = reinterpret_cast<uint4*>(s_slot);
#pragma unroll
  for (int u = 0; u < ROWB / 16 / 32; ++u) cp16(d4 + lane + u * 32, s4 + lane + u * 32);
}

// per-row score reduction (bitwise reference order) straight from smem; all
// lanes exit with d and s (full values)
__device__ __forceinline__ void row_score(const bf16* rowp, const bf16* cw, int lane, float& d_out,
                                          float& s_out) {
  float acc_d[4], acc_s[4];
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    acc_d[i] = 0.f;
    acc_s[i] = 0.f;
  }
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += UNROLL) {
    uint2 rq[UNROLL];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) rq[u] = rp[32 * (k0 + u)];
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      const bf16* bb = reinterpret_cast<const bf16*>(&rq[u]);
      uint2 cq = reinterpret_cast<const uint2*>(cw + 4 * lane)[32 * (k0 + u)];
      const bf16* cb = reinterpret_cast<const bf16*>(&cq);
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float v = __bfloat162float(bb[i]);
        acc_d[i] = __fadd_rn(acc_d[i], __fmul_rn(v, __bfloat162float(cb[i])));
        acc_s[i] = __fadd_rn(acc_s[i], __fmul_rn(v, v));
      }
    }
  }
  float d = __fadd_rn(__fadd_rn(__fadd_rn(acc_d[0], acc_d[1]), acc_d[2]), acc_d[3]);
  float s = __fadd_rn(__fadd_rn(__fadd_rn(acc_s[0], acc_s[1]), acc_s[2]), acc_s[3]);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
}

// warp-lane softmax over R scores read from s (lanes >= R get -inf); writes
// probs to p. All 32 lanes participate in the butterflies.
__device__ __forceinline__ void softmax_warp(const float* s, float* p, int R, int lane) {
  float sc = (lane < R) ? s[lane] : -INFINITY;
  float m = sc;
#pragma unroll
  for (int off = 16; off > 0; off >>= 1) m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, off));
  float e = __expf(__fadd_rn(sc, -m));
  float sm = __fadd_rn(e, __shfl_xor_sync(0xffffffffu, e, 16));
  sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 8));
  sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 4));
  sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 2));
  sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 1));
  if (lane < R) p[lane] = __fdiv_rn(e, sm);
}

// score reduction with the reference chain/tree order, packed rn pairs
// (defined with the lean kernel below)
__device__ __forceinline__ void row_score_packed(const bf16* rowp, const bf16* cw, int lane,
                                                 float& d_out, float& s_out);

template <int FW>
__global__ __launch_bounds__(FW * 32, 1) void fusedW_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, int nvb, float eps) {
  constexpr int FTHREADS = FW * 32;
  constexpr int MK = (CH + FW - 1) / FW;
  extern __shared__ char smem_raw[];
  bf16* s_rows = reinterpret_cast<bf16*>(smem_raw + SmemF<FW>::ROWS);
  float* s_osqp = reinterpret_cast<float*>(smem_raw + SmemF<FW>::OSQP);
  float* s_score = reinterpret_cast<float*>(smem_raw + SmemF<FW>::SCORE);

  const int tid = threadIdx.x;
  const int warp = tid >> 5;
  const int lane = tid & 31;
  const int R = nvb + 1;
  const int F = min(R, NSLOT - R);  // next rows prefetchable during score

  pdl_wait();

  int seq = 0;
  for (int t = blockIdx.x; t < T; t += gridDim.x, ++seq) {
    const int t_next = t + gridDim.x;

    if (seq == 0) {
      for (int j = 0; j < R; ++j) {
        const bf16* src = (j < nvb) ? bank + ((long)t * nvb + j) * H : prefix + (long)t * H;
        issue_row_block<FTHREADS>(s_rows + (long)((R * seq + j) % NSLOT) * H, src, tid);
        cp_commit();
      }
      cp_wait<0>();
    } else {
      cp_wait<0>();
    }
    __syncthreads();

    // ---- score: warps 0..R-1 one row each; free warps prefetch next ----
    if (warp < R) {
      const bf16* rowp = s_rows + (long)((R * seq + warp) % NSLOT) * H;
      float d, s;
      row_score_packed(rowp, cw, lane, d, s);
      if (lane == 0) {
        float mean = __fmul_rn(s, INVH);
        float rrms = rsqrtf(__fadd_rn(mean, eps));
        s_score[warp] = __fmul_rn(d, rrms);
      }
    } else if (t_next < T) {
      const int f = warp - R;
      if (f < F) {
        const bf16* src =
            (f < nvb) ? bank + ((long)t_next * nvb + f) * H : prefix + (long)t_next * H;
        issue_row_warp(s_rows + (long)((R * (seq + 1) + f) % NSLOT) * H, src, lane);
        cp_commit();
      }
    }
    __syncthreads();

    // ---- softmax over R scores: every warp computes it redundantly with
    // the identical deterministic op order -> bitwise identical probs; no
    // extra barrier and no warp0 serial phase. pr lives in lane j < R.
    float pr;
    {
      float sc = (lane < R) ? s_score[lane] : -INFINITY;
      float m = sc;
#pragma unroll
      for (int off = 16; off > 0; off >>= 1) m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, off));
      float e = __expf(__fadd_rn(sc, -m));
      float sm = __fadd_rn(e, __shfl_xor_sync(0xffffffffu, e, 16));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 8));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 4));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 2));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 1));
      pr = (lane < R) ? __fdiv_rn(e, sm) : 0.f;
    }

    // ---- mixture (+squared partials) into registers, chunk-per-warp ----
    // torch per-element order: a[j%4] += prob[j]*v, ((a0+a1)+a2)+a3; pairs
    // folded into packed rn ops (bit-exact with the scalar order).
    float2 prob2[MAXR];
#pragma unroll
    for (int j = 0; j < MAXR; ++j) {
      float p = (j < R) ? __shfl_sync(0xffffffffu, pr, j) : 0.f;
      prob2[j] = make_float2(p, p);
    }
    const uint2* rows_ptr[MAXR];
#pragma unroll
    for (int j = 0; j < MAXR; ++j)
      rows_ptr[j] = reinterpret_cast<const uint2*>(
          s_rows + (long)((R * seq + (j < R ? j : 0)) % NSLOT) * H + 4 * lane);

    const int k0 = (CH * warp) / FW;
    const int k1 = (CH * (warp + 1)) / FW;
    float2 sq2[2] = {make_float2(0.f, 0.f), make_float2(0.f, 0.f)};
    float2 mixreg[MK][2];
#pragma unroll
    for (int kk = 0; kk < MK; ++kk) {
      int k = k0 + kk;
      if (k >= k1) break;
      float2 acc01[4], acc23[4];
#pragma unroll
      for (int c = 0; c < 4; ++c) {
        acc01[c] = make_float2(0.f, 0.f);
        acc23[c] = make_float2(0.f, 0.f);
      }
#pragma unroll
      for (int j = 0; j < MAXR; ++j) {
        if (j < R) {
          float2 v01, v23;
          cvt4_f2(rows_ptr[j][32 * k], v01, v23);
          acc01[j & 3] = fma_x2(prob2[j], v01, acc01[j & 3]);
          acc23[j & 3] = fma_x2(prob2[j], v23, acc23[j & 3]);
        }
      }
      float2 m01 = add_x2(acc01[0], acc01[1]);
      m01 = add_x2(m01, acc01[2]);
      m01 = add_x2(m01, acc01[3]);
      float2 m23 = add_x2(acc23[0], acc23[1]);
      m23 = add_x2(m23, acc23[2]);
      m23 = add_x2(m23, acc23[3]);
      mixreg[kk][0] = m01;
      mixreg[kk][1] = m23;
      sq2[0] = add_x2(sq2[0], mul_x2(mixreg[kk][0], mixreg[kk][0]));
      sq2[1] = add_x2(sq2[1], mul_x2(mixreg[kk][1], mixreg[kk][1]));
    }
    float* dst = s_osqp + (warp * 32 + lane) * 4;
    dst[0] = sq2[0].x;
    dst[1] = sq2[0].y;
    dst[2] = sq2[1].x;
    dst[3] = sq2[1].y;
    __syncthreads();  // rows are dead past this barrier

    // ---- issue the rest of next token's rows into freed slots ----
    if (t_next < T && warp < R - F) {
      const int j = F + warp;
      const bf16* src = (j < nvb) ? bank + ((long)t_next * nvb + j) * H : prefix + (long)t_next * H;
      issue_row_warp(s_rows + (long)((R * (seq + 1) + j) % NSLOT) * H, src, lane);
      cp_commit();
    }

    // ---- orr: every warp reduces the partials redundantly in the fixed
    // deterministic order -> bitwise identical orr without another barrier
    float orr;
    {
      float acc[4];
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        float v = s_osqp[lane * 4 + i];
#pragma unroll
        for (int w = 1; w < FW; ++w) v = __fadd_rn(v, s_osqp[(w * 32 + lane) * 4 + i]);
        acc[i] = v;
      }
      float s = __fadd_rn(__fadd_rn(__fadd_rn(acc[0], acc[1]), acc[2]), acc[3]);
      s = __shfl_sync(0xffffffffu, lane_tree_sum(s), 0);
      float mean = __fmul_rn(s, INVH);
      orr = rsqrtf(__fadd_rn(mean, eps));
    }

    // ---- epilogue straight from registers ----
    const float2 orr2 = make_float2(orr, orr);
#pragma unroll
    for (int kk = 0; kk < MK; ++kk) {
      int k = k0 + kk;
      if (k >= k1) break;
      int slot = lane + 32 * k;
      uint2 oq = reinterpret_cast<const uint2*>(ow + 4 * lane)[32 * k];
      float2 o01, o23;
      cvt4_f2(oq, o01, o23);
      float2 r01 = mul_x2(mul_x2(mixreg[kk][0], orr2), o01);
      float2 r23 = mul_x2(mul_x2(mixreg[kk][1], orr2), o23);
      __nv_bfloat162 b01 = __float22bfloat162_rn(r01);
      __nv_bfloat162 b23 = __float22bfloat162_rn(r23);
      uint2 o2;
      o2.x = *reinterpret_cast<unsigned*>(&b01);
      o2.y = *reinterpret_cast<unsigned*>(&b23);
      *reinterpret_cast<uint2*>(out + (long)t * H + 4 * slot) = o2;
    }
  }
  pdl_launch_dependents();
}

// ----------------------------------------------------------------- staged ---
constexpr int SW = 8;  // warps per staged block
constexpr int STHREADS = SW * 32;
constexpr int SMK = (CH + SW - 1) / SW;

// uint4 rolling-pipeline per-row score: 14 outstanding LDG.128 per lane in
// two half-batches (issue k+1 half while consuming k), elements 8*lane+256u.
// 4 fp32 accumulator chains (i&3) folded ((c0+c1)+c2)+c3, then the 32-lane tree.
__device__ __forceinline__ void row_score4(const bf16* rowp, const bf16* cw, int lane, float& d_out,
                                           float& s_out) {
  float2 ad[4], as[4];
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    ad[i] = make_float2(0.f, 0.f);
    as[i] = make_float2(0.f, 0.f);
  }
  const uint4* rp = reinterpret_cast<const uint4*>(rowp + 8 * lane);
  const uint4* cpw = reinterpret_cast<const uint4*>(cw + 8 * lane);
#pragma unroll 1
  for (int u0 = 0; u0 < 28; u0 += 14) {
    uint4 rq[14], cq[14];
#pragma unroll
    for (int u = 0; u < 14; ++u) {
      rq[u] = rp[32 * (u0 + u)];
      cq[u] = cpw[32 * (u0 + u)];
    }
#pragma unroll
    for (int u = 0; u < 14; ++u) {
      float2 v01, v23, v45, v67, k01, k23, k45, k67;
      cvt4_f2(make_uint2(rq[u].x, rq[u].y), v01, v23);
      cvt4_f2(make_uint2(rq[u].z, rq[u].w), v45, v67);
      cvt4_f2(make_uint2(cq[u].x, cq[u].y), k01, k23);
      cvt4_f2(make_uint2(cq[u].z, cq[u].w), k45, k67);
      ad[0] = fma_x2(v01, k01, ad[0]);
      ad[1] = fma_x2(v23, k23, ad[1]);
      ad[2] = fma_x2(v45, k45, ad[2]);
      ad[3] = fma_x2(v67, k67, ad[3]);
      as[0] = fma_x2(v01, v01, as[0]);
      as[1] = fma_x2(v23, v23, as[1]);
      as[2] = fma_x2(v45, v45, as[2]);
      as[3] = fma_x2(v67, v67, as[3]);
    }
  }
  float d = __fadd_rn(ad[0].x, ad[0].y);
  d = __fadd_rn(d, ad[1].x);
  d = __fadd_rn(d, ad[1].y);
  d = __fadd_rn(d, ad[2].x);
  d = __fadd_rn(d, ad[2].y);
  d = __fadd_rn(d, ad[3].x);
  d = __fadd_rn(d, ad[3].y);
  float s = __fadd_rn(as[0].x, as[0].y);
  s = __fadd_rn(s, as[1].x);
  s = __fadd_rn(s, as[1].y);
  s = __fadd_rn(s, as[2].x);
  s = __fadd_rn(s, as[2].y);
  s = __fadd_rn(s, as[3].x);
  s = __fadd_rn(s, as[3].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// row_score4 with cw pre-widened to fp32 in smem (LDS.128x2 per chunk)
__device__ __forceinline__ void row_score4_f32cw(const bf16* rowp, const float* cwf, int lane,
                                                 float& d_out, float& s_out) {
  float2 ad[4], as[4];
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    ad[i] = make_float2(0.f, 0.f);
    as[i] = make_float2(0.f, 0.f);
  }
  const uint4* rp = reinterpret_cast<const uint4*>(rowp + 8 * lane);
  const float4* cpf = reinterpret_cast<const float4*>(cwf + 8 * lane);
#pragma unroll 1
  for (int u0 = 0; u0 < 28; u0 += 14) {
    uint4 rq[14];
    float4 cq[14][2];
#pragma unroll
    for (int u = 0; u < 14; ++u) {
      rq[u] = rp[32 * (u0 + u)];
      cq[u][0] = cpf[64 * (u0 + u)];
      cq[u][1] = cpf[64 * (u0 + u) + 1];
    }
#pragma unroll
    for (int u = 0; u < 14; ++u) {
      float2 v01, v23, v45, v67;
      cvt4_f2(make_uint2(rq[u].x, rq[u].y), v01, v23);
      cvt4_f2(make_uint2(rq[u].z, rq[u].w), v45, v67);
      float2 k01 = make_float2(cq[u][0].x, cq[u][0].y);
      float2 k23 = make_float2(cq[u][0].z, cq[u][0].w);
      float2 k45 = make_float2(cq[u][1].x, cq[u][1].y);
      float2 k67 = make_float2(cq[u][1].z, cq[u][1].w);
      ad[0] = fma_x2(v01, k01, ad[0]);
      ad[1] = fma_x2(v23, k23, ad[1]);
      ad[2] = fma_x2(v45, k45, ad[2]);
      ad[3] = fma_x2(v67, k67, ad[3]);
      as[0] = fma_x2(v01, v01, as[0]);
      as[1] = fma_x2(v23, v23, as[1]);
      as[2] = fma_x2(v45, v45, as[2]);
      as[3] = fma_x2(v67, v67, as[3]);
    }
  }
  float d = __fadd_rn(ad[0].x, ad[0].y);
  d = __fadd_rn(d, ad[1].x);
  d = __fadd_rn(d, ad[1].y);
  d = __fadd_rn(d, ad[2].x);
  d = __fadd_rn(d, ad[2].y);
  d = __fadd_rn(d, ad[3].x);
  d = __fadd_rn(d, ad[3].y);
  float s = __fadd_rn(as[0].x, as[0].y);
  s = __fadd_rn(s, as[1].x);
  s = __fadd_rn(s, as[1].y);
  s = __fadd_rn(s, as[2].x);
  s = __fadd_rn(s, as[2].y);
  s = __fadd_rn(s, as[3].x);
  s = __fadd_rn(s, as[3].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// one warp per (token,row): full per-row score reduction from gmem

// one 256-thread block per token; rows re-read from gmem (L2-hot at small T)

// ---------------------------------------------------- warp-per-token (wt) ---
// Barrier-free: every warp owns one token end-to-end (score all R rows,
// in-warp softmax, mixture, output norm, epilogue). No per-token
// __syncthreads at all; the only block barrier is the one-time conversion of
// cw to fp32 smem. Rows are re-read for the mixture and epilogue passes --
// they sit in L2/L1 from the score pass moments earlier, so DRAM sees ~1x
// input traffic. Score arithmetic matches row_score_packed bit-for-bit
// (chains (0,1),(2,3) folded into packed rn pairs over uint4 slots); the
// mixture keeps the lean kernel's j%4 chain order per element pair.
constexpr int WW = 8;  // warps per wt CTA
constexpr int WTHREADS = WW * 32;
constexpr int WUNROLL = 7;  // uint4 chunks in flight per row (28%7==0)

// ------------------------------------------------------------------- cx4 ----
// 4-warp CTA, one barrier-free warp-group per CTA (syncthreads only once at
// init). Warp w owns columns [w*QH, (w+1)*QH): score partials per row are
// exchanged through smem spin flags (warp-paced, skew limited to 2 tokens via
// parity buffers + done gates); probs are folded online (running max, register
// rescale) so each row quarter is consumed from its cp.async smem slot exactly
// once: cp.async streams the only DRAM pass, smem slots rotate every 3
// quarters, and the fp32 mixture (56 regs/lane) never spills to memory until
// the bf16 epilogue.
constexpr int XW = 4;
constexpr int QH = H / XW;        // 1792
constexpr int U4P = QH / 8 / 32;  // 7 uint4 per lane per quarter
constexpr int XEPL = QH / 32;     // 56 elements per lane
constexpr int XNS = 3;            // ring slots per warp
constexpr int XSLOTB = QH * 2;    // 3584 bytes per slot

// ------------------------------------------------------------------ lean ----
// 256-thread CTA, 2 CTAs/SM, no smem row staging: scores read rows straight
// from gmem (DRAM), mixture re-reads the same rows (L1/L2-resident from the
// score pass <1 phase earlier). Two independent CTAs per SM keep DRAM busy
// through each other's barriers. Exactly two __syncthreads per token (after
// scores, after mixture partials); softmax and the output-norm reduction are
// computed redundantly (deterministic) in every warp. Arithmetic repeats the
// reference orders exactly, with pairs folded into packed rn ops.
constexpr int LW = 8;  // warps per lean CTA
constexpr int LTHREADS = LW * 32;
constexpr int LMK = (CH + LW - 1) / LW;  // max mixture uint2 chunks/warp = 7

// score reduction for one row straight from gmem; same per-element chain and
// tree order as the staged score kernel, with pairs folded into packed ops
__device__ __forceinline__ void row_score_packed(const bf16* rowp, const bf16* cw, int lane,
                                                 float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];  // [0] = torch chains (0,1), [1] = chains (2,3)
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += UNROLL) {
    uint2 rq[UNROLL];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) rq[u] = rp[32 * (k0 + u)];
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[u], v01, v23);
      uint2 cq = reinterpret_cast<const uint2*>(cw + 4 * lane)[32 * (k0 + u)];
      cvt4_f2(cq, c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// slice variant of row_score_packed: one warp reduces a contiguous uint2
// chunk range [k_lo, k_hi) of a row (k_hi - k_lo <= UNROLL). Same per-element
// fma chains and lane tree as row_score_packed; cross-slice combination is
// done by the caller over per-warp partials.
__device__ __forceinline__ void row_score_slice(const bf16* rowp, const bf16* cw, int lane,
                                                int k_lo, int k_hi, float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
  const uint2* cp = reinterpret_cast<const uint2*>(cw + 4 * lane);
  uint2 rq[UNROLL];
#pragma unroll
  for (int u = 0; u < UNROLL; ++u) {
    if (k_lo + u < k_hi) rq[u] = rp[32 * (k_lo + u)];
  }
#pragma unroll
  for (int u = 0; u < UNROLL; ++u) {
    if (k_lo + u < k_hi) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[u], v01, v23);
      cvt4_f2(cp[32 * (k_lo + u)], c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// rolled double-buffer variant of row_score_packed: two 14-chunk buffers,
// next buffer's loads issue before the current buffer's fma consumes, keeping
// DRAM requests continuously in flight per warp. Chunk consumption order and
// all accumulator/tree orders are bit-identical to row_score_packed.
__device__ __forceinline__ void row_score_rolled(const bf16* rowp, const bf16* cw, int lane,
                                                 float& d_out, float& s_out) {
  constexpr int RB = UNROLL / 2;  // 14
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  uint2 rq[2][RB];
  const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
  const uint2* cp = reinterpret_cast<const uint2*>(cw + 4 * lane);
#pragma unroll
  for (int u = 0; u < RB; ++u) rq[0][u] = rp[32 * u];
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += RB) {
    const int cur = (k0 / RB) & 1;
    if (k0 + RB < CH) {
      const int nxt = cur ^ 1;
#pragma unroll
      for (int u = 0; u < RB; ++u) rq[nxt][u] = rp[32 * (k0 + RB + u)];
    }
#pragma unroll
    for (int u = 0; u < RB; ++u) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[cur][u], v01, v23);
      uint2 cq = cp[32 * (k0 + u)];
      cvt4_f2(cq, c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// rolled fcw variant: cw float4 LDS instead of bf16 LDG
__device__ __forceinline__ void row_score_rolled_f32cw(const bf16* rowp, const float* cwf, int lane,
                                                       float& d_out, float& s_out) {
  constexpr int RB = UNROLL / 2;
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  uint2 rq[2][RB];
  const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
  const float4* cp = reinterpret_cast<const float4*>(cwf + 4 * lane);
#pragma unroll
  for (int u = 0; u < RB; ++u) rq[0][u] = rp[32 * u];
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += RB) {
    const int cur = (k0 / RB) & 1;
    if (k0 + RB < CH) {
      const int nxt = cur ^ 1;
#pragma unroll
      for (int u = 0; u < RB; ++u) rq[nxt][u] = rp[32 * (k0 + RB + u)];
    }
#pragma unroll
    for (int u = 0; u < RB; ++u) {
      float2 v01, v23;
      cvt4_f2(rq[cur][u], v01, v23);
      float4 c4 = cp[32 * (k0 + u)];
      acc_d[0] = fma_x2(v01, make_float2(c4.x, c4.y), acc_d[0]);
      acc_d[1] = fma_x2(v23, make_float2(c4.z, c4.w), acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// ------------------------------------------------------------ nsr/nsm -------
// development NSRC-specialized fused family: compile-time NVB folds all runtime
// row loops and bank/prefix address tests.
// nsm_kernel<NVB> (NVB <= 4, NSRC 2..5): single-pass smem-resident. The
// grouped score pass stages every row chunk it loads into dynamic smem, so
// the mixture phase never re-touches gmem (one DRAM pass per token).
// nsr_kernel<NVB> (NVB=8, NSRC 9): gmem re-read mixture like lean, with all
// branches/loops folded at compile time.

// uint4 (16B) rolled score variant: 7-uint4 double buffer (same per-lane
// bytes as row_score_rolled's 14-uint2 buffer), half the load instructions.
// Each uint4 covers uint2 chunks 2m and 2m+1; its two halves are consumed
// consecutively, so both accumulator tapes are bit-identical to
// row_score_rolled / row_score_packed.
__device__ __forceinline__ void row_score_uint4(const bf16* rowp, const bf16* cw, int lane,
                                                float& d_out, float& s_out) {
  constexpr int RB4 = 7;      // 7 uint4 = 14 uint2 chunks
  constexpr int CM = CH / 2;  // 28 uint4 chunks per lane
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  uint4 rq[2][RB4];
  const uint4* rp = reinterpret_cast<const uint4*>(rowp + 8 * lane);
  const uint4* cp = reinterpret_cast<const uint4*>(cw + 8 * lane);
#pragma unroll
  for (int u = 0; u < RB4; ++u) rq[0][u] = rp[32 * u];
#pragma unroll 1
  for (int k0 = 0; k0 < CM; k0 += RB4) {
    const int cur = (k0 / RB4) & 1;
    if (k0 + RB4 < CM) {
      const int nxt = cur ^ 1;
#pragma unroll
      for (int u = 0; u < RB4; ++u) rq[nxt][u] = rp[32 * (k0 + RB4 + u)];
    }
#pragma unroll
    for (int u = 0; u < RB4; ++u) {
      float2 v01, v23, v45, v67, c01, c23, c45, c67;
      cvt4_f2(make_uint2(rq[cur][u].x, rq[cur][u].y), v01, v23);
      cvt4_f2(make_uint2(rq[cur][u].z, rq[cur][u].w), v45, v67);
      uint4 cq = cp[32 * (k0 + u)];
      cvt4_f2(make_uint2(cq.x, cq.y), c01, c23);
      cvt4_f2(make_uint2(cq.z, cq.w), c45, c67);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
      acc_d[0] = fma_x2(v45, c45, acc_d[0]);
      acc_d[1] = fma_x2(v67, c67, acc_d[1]);
      acc_s[0] = fma_x2(v45, v45, acc_s[0]);
      acc_s[1] = fma_x2(v67, v67, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// staged slice variant of row_score_slice: identical fma chains and lane
// tree; every loaded uint2 chunk is also written to the row's smem slot.
__device__ __forceinline__ void row_score_slice_stage(const bf16* rowp, const bf16* cw, int lane,
                                                      int k_lo, int k_hi, bf16* srow, float& d_out,
                                                      float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
  const uint2* cp = reinterpret_cast<const uint2*>(cw + 4 * lane);
  uint2* sp = reinterpret_cast<uint2*>(srow + 4 * lane);
  uint2 rq[UNROLL];
#pragma unroll
  for (int u = 0; u < UNROLL; ++u) {
    if (k_lo + u < k_hi) {
      rq[u] = rp[32 * (k_lo + u)];
      sp[32 * (k_lo + u)] = rq[u];
    }
  }
#pragma unroll
  for (int u = 0; u < UNROLL; ++u) {
    if (k_lo + u < k_hi) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[u], v01, v23);
      cvt4_f2(cp[32 * (k_lo + u)], c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// staged full-row rolled variant (G == 1): identical chunk consumption order
// and accumulator/tree layout to row_score_packed, plus smem staging stores.
__device__ __forceinline__ void row_score_stage(const bf16* rowp, const bf16* cw, int lane,
                                                bf16* srow, float& d_out, float& s_out) {
  constexpr int RB = UNROLL / 2;  // 14
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  uint2 rq[2][RB];
  const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
  const uint2* cp = reinterpret_cast<const uint2*>(cw + 4 * lane);
  uint2* sp = reinterpret_cast<uint2*>(srow + 4 * lane);
#pragma unroll
  for (int u = 0; u < RB; ++u) {
    rq[0][u] = rp[32 * u];
    sp[32 * u] = rq[0][u];
  }
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += RB) {
    const int cur = (k0 / RB) & 1;
    if (k0 + RB < CH) {
      const int nxt = cur ^ 1;
#pragma unroll
      for (int u = 0; u < RB; ++u) {
        rq[nxt][u] = rp[32 * (k0 + RB + u)];
        sp[32 * (k0 + RB + u)] = rq[nxt][u];
      }
    }
#pragma unroll
    for (int u = 0; u < RB; ++u) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[cur][u], v01, v23);
      cvt4_f2(cp[32 * (k0 + u)], c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// nsr_kernel<NVB>: gmem re-read mixture variant (NSRC=9 shape family). Same
// phase structure as nsm but rows stream from gmem twice (second pass hits
// L1/L2); all row tests folded by the NVB template parameter.

// ------------------------------------------------------------------ lean4 ---
// 4-warp CTA, persistent tokens. Combines the numerically-proven orders of the
// lean kernel (score: full-row warp reduction, lean chunk pattern; softmax:
// lean butterfly; mixture: per-element j%4 / ((a0+a1)+a2)+a3 chains) with the
// cx4 occupancy model: small CTAs so 4+ tokens are in flight per SM and each
// warp owns one row quarter for the mixture/epilogue. No cp.async, no smem row
// staging: scores stream rows from gmem (DRAM), mixture re-reads quarters from
// L2 (resident from the score pass moments earlier).
constexpr int QW = 4;  // warps per lean4 CTA
constexpr int QTHREADS = QW * 32;
constexpr int QQH = H / QW;        // 1792 elements per quarter
constexpr int QU4 = QQH / 8 / 32;  // 7 uint4 chunks per lane per quarter

constexpr int NW9 = 9;
constexpr int NTHREADS9 = NW9 * 32;
constexpr int CHUNK9 = 256;                    // elements per 32-lane uint4 sweep
constexpr int NCH9 = H / CHUNK9;               // 28 chunks per row
constexpr int MAXU9 = (NCH9 + NW9 - 1) / NW9;  // 4 (warp 0 gets chunks 0,9,18,27)

// ------------------------------------------------------------------ leanpc --
// impl 20: producer/consumer split of lean9. 9 producer warps (warps 0..8)
// stream per-row scores token after token with NO phase barriers; 9 consumer
// warps (warps 9..17) take scores via a 4-deep smem slot ring (volatile flag
// handoff + named-bar rendezvous within each role) and run softmax -> mixture
// (rows L2-hot from the producer's own DRAM reads) -> orr -> epilogue. The
// producer keeps DRAM streaming continuously across tokens instead of the
// alternate burst/idle epochs of the __syncthreads-phased lean9.
constexpr int PCSLOT = 4;

// ------------------------------------------------------------------ lean9c --
// impl 24: column-split 2-CTA-per-token for SM-starved mid T (33..296).
// CTA 2t+h handles columns [h*3584,(h+1)*3584) of token t: each of the 9 warps
// scores its row's half with the SAME per-lane chain/tree order as lean9 (the
// lane element membership is unchanged; the fold adds exactly one extra
// cross-half add), the two half-sums are combined through a tiny scratch row
// (store + counter + spin, publish order h0+h1), softmax/ per-warp redundant,
// then the mixture runs over warp-strided 256-element chunks of the half row
// and the output normalize combines half sumsqs with the same store+spin
// protocol. Grid = 2T CTAs, group-adjacent launch, all-resident for T <= 296.
constexpr int HALFH = H / 2;                   // 3584
constexpr int NCHC = HALFH / CHUNK9;           // 14 chunks per half row
constexpr int MAXUC = (NCHC + NW9 - 1) / NW9;  // 2

// half-row score: identical chain/tree arithmetic to row_score_packed over
// the lane's 28 chunks that fall inside this half
__device__ __forceinline__ void row_score_half(const bf16* rowp, const bf16* cw, int lane,
                                               float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
#pragma unroll 1
  for (int k0 = 0; k0 < CH / 2; k0 += UNROLL / 2) {
    uint2 rq[UNROLL / 2];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL / 2; ++u) rq[u] = rp[32 * (k0 + u)];
#pragma unroll
    for (int u = 0; u < UNROLL / 2; ++u) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[u], v01, v23);
      uint2 cq = reinterpret_cast<const uint2*>(cw + 4 * lane)[32 * (k0 + u)];
      cvt4_f2(cq, c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// ------------------------------------------------------------------ lean9s --
// lean9 with score-stash: the score warp already holds its row's 28x uint2
// chunks in registers; it also STS them to smem (free bandwidth-wise: the
// score phase is DRAM-latency-bound). The mixture phase then LDS.128s its row
// shares from smem instead of re-reading L2, removing the dominant long
// scoreboard stalls of lean9. SMROWS=8 rows x 14KB = 112KB + bookkeeping fits
// two CTAs in the 227KB/SM smem budget; the 9th row (prefix) is still read
// from gmem/L2 in the mixture (softmax rarely weights it dominant and L2 is
// hot from the score pass).
constexpr int SMROWS = 8;

// row_score_packed + STS of every loaded chunk to sdst (identical linear
// layout to the gmem row)
__device__ __forceinline__ void row_score_sts(const bf16* rowp, const bf16* cw, bf16* sdst,
                                              int lane, float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  uint2* sp = reinterpret_cast<uint2*>(sdst + 4 * lane);
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += UNROLL) {
    uint2 rq[UNROLL];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      rq[u] = rp[32 * (k0 + u)];
      sp[32 * (k0 + u)] = rq[u];
    }
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[u], v01, v23);
      uint2 cq = reinterpret_cast<const uint2*>(cw + 4 * lane)[32 * (k0 + u)];
      cvt4_f2(cq, c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// ------------------------------------------------------------------ lean9 ---
// 9-warp CTA (nvb=8 -> R=9): score phase assigns exactly one full row per
// warp (removes lean4's warp0-does-3-rows imbalance); mixture/epilogue split
// the row into 28 256-element chunks strided across the 9 warps (warp w takes
// chunks w, w+9, w+18, w+27), so each lane holds at most 4 chunk registersets
// (32 regs) instead of lean4's 7 (56 regs). Same proven arithmetic: full-row
// row_score_packed per row, lean softmax butterflies, per-element j%4 chains
// combined ((a0+a1)+a2)+a3, sq accumulated into 4 chunk-pair accumulators in
// ascending chunk order per lane, then lane tree, then warp-partials in order.
// variant of row_score_packed that consumes cw pre-converted to fp32 (the
// bf16->f32 widening is lossless, so the dot/sq arithmetic is unchanged);
// one LDS.128 per chunk replaces the global cw load + two converts.
__device__ __forceinline__ void row_score_packed_f32cw(const bf16* rowp, const float* cwf, int lane,
                                                       float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  const float4* cp = reinterpret_cast<const float4*>(cwf + 4 * lane);
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += UNROLL) {
    uint2 rq[UNROLL];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) rq[u] = rp[32 * (k0 + u)];
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      float2 v01, v23;
      cvt4_f2(rq[u], v01, v23);
      float4 c4 = cp[32 * (k0 + u)];
      acc_d[0] = fma_x2(v01, make_float2(c4.x, c4.y), acc_d[0]);
      acc_d[1] = fma_x2(v23, make_float2(c4.z, c4.w), acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// L2 prefetch-size hint variants of the 4-bf16 row load. Identical data and
// register order to the plain ld; only the L2 fill granularity hint differs
// (current row bytes only - these are demand loads, not lookahead traffic).
template <int HINT>
__device__ __forceinline__ uint2 ld_row_chunk_hint(const uint2* p) {
  uint2 q;
  if (HINT == 1)
    asm("ld.global.L2::128B.v2.u32 {%0,%1}, [%2];" : "=r"(q.x), "=r"(q.y) : "l"(p));
  else
    asm("ld.global.L2::256B.v2.u32 {%0,%1}, [%2];" : "=r"(q.x), "=r"(q.y) : "l"(p));
  return q;
}

// bit-identical clone of row_score_packed_f32cw with cache-hint row loads.
template <int HINT>
__device__ __forceinline__ void row_score_packed_f32cw_hint(const bf16* rowp, const float* cwf,
                                                            int lane, float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
  const float4* cp = reinterpret_cast<const float4*>(cwf + 4 * lane);
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += UNROLL) {
    uint2 rq[UNROLL];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) rq[u] = ld_row_chunk_hint<HINT>(rp + 32 * (k0 + u));
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      float2 v01, v23;
      cvt4_f2(rq[u], v01, v23);
      float4 c4 = cp[32 * (k0 + u)];
      acc_d[0] = fma_x2(v01, make_float2(c4.x, c4.y), acc_d[0]);
      acc_d[1] = fma_x2(v23, make_float2(c4.z, c4.w), acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// bit-identical clone of row_score_packed with cache-hint row loads (bf16 cw).
template <int HINT>
__device__ __forceinline__ void row_score_packed_hint(const bf16* rowp, const bf16* cw, int lane,
                                                      float& d_out, float& s_out) {
  float2 acc_d[2], acc_s[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    acc_d[i] = make_float2(0.f, 0.f);
    acc_s[i] = make_float2(0.f, 0.f);
  }
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += UNROLL) {
    uint2 rq[UNROLL];
    const uint2* rp = reinterpret_cast<const uint2*>(rowp + 4 * lane);
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) rq[u] = ld_row_chunk_hint<HINT>(rp + 32 * (k0 + u));
#pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      float2 v01, v23, c01, c23;
      cvt4_f2(rq[u], v01, v23);
      uint2 cq = reinterpret_cast<const uint2*>(cw + 4 * lane)[32 * (k0 + u)];
      cvt4_f2(cq, c01, c23);
      acc_d[0] = fma_x2(v01, c01, acc_d[0]);
      acc_d[1] = fma_x2(v23, c23, acc_d[1]);
      acc_s[0] = fma_x2(v01, v01, acc_s[0]);
      acc_s[1] = fma_x2(v23, v23, acc_s[1]);
    }
  }
  float d = __fadd_rn(acc_d[0].x, acc_d[0].y);
  d = __fadd_rn(d, acc_d[1].x);
  d = __fadd_rn(d, acc_d[1].y);
  float s = __fadd_rn(acc_s[0].x, acc_s[0].y);
  s = __fadd_rn(s, acc_s[1].x);
  s = __fadd_rn(s, acc_s[1].y);
  d_out = lane_tree_sum(d);
  s_out = lane_tree_sum(s);
  d_out = __shfl_sync(0xffffffffu, d_out, 0);
  s_out = __shfl_sync(0xffffffffu, s_out, 0);
}

// ---------------------------------------------------------------- leanws ---
// impl 38 (development experiment): warp-specialized handoff variant
// of lean10 (impl 28 = lean9_kernel<FCW,2,10>). Score phase, per-element j%4
// mixture chains, chunk u=w mod 10 grouping, sq fold order and epilogue are
// bit-identical to lean10. The two full-CTA __syncthreads per token are
// replaced by mbarrier producer/consumer handoffs:
//   bar[0]: R score warps (lane0 arrives after s_score[w] store) -> warp NW-1
//   bar[1]: warp NW-1 computes softmax ONCE (lean's exact butterflies on
//           lanes 0..R-1), stores s_prob[j] = __fdiv_rn(e, sm), lane0 arrives
//   bar[2]: all NW warps arrive after their s_qp[w] partial store -> warp NW-1
//   bar[3]: warp NW-1 lane0 folds s_qp[0..NW-1] in ascending order, computes
//           rsqrtf, stores s_orr, arrives
// Score warps arrive bar[0] without stalling (hover at the bar[1] wait), so
// the softmax latency overlaps their arrival spread; the output-norm fold is
// computed once instead of redundantly in every warp.
// Additional template flag BP: bulk-prefetch the whole next token (bank's
// nvb rows are contiguous + the prefix row) into L2 at iteration start so the
// DRAM stream stays busy through this token's mixture/epilogue phases.
// Additional template param HINT: 0 = plain score loads; 1/2 = current-row
// score loads issued with ld.global.L2::128B / L2::256B prefetch-size hints
// (development experiment; arithmetic identical, demand traffic only).

// forward declaration: defined with the impl50/51 helpers below
template <bool FCW>
__device__ __forceinline__ void row_score_packed2(const bf16* row0, const bf16* row1,
                                                  const bf16* cw, const float* cwf, int lane,
                                                  float& d0_out, float& s0_out, float& d1_out,
                                                  float& s1_out);

// ------------------------------------------------------------- dualt -----
// impl82 (development experiment, opt-in): two-independent-token
// interleave built on impl43's 10-warp shape. Structurally distinct from the
// rejected impl50/51: those interleaved ONLY the score loads and then ran
// each token's mixture+epilogue sequentially (#pragma unroll 1). dualt fuses
// BOTH tokens through the mixture/epilogue loop, so every warp keeps row-w
// score chains AND mixture chains for tokens A and B in flight at once,
// doubling the independent long-scoreboard load chains per warp (the R38 NCU
// reports show long-scoreboard = 7.2 cycles/issue at 40% issue-active is the
// dominant stall, and TMA staging only made it worse). The epilogue reuses
// each ow vector for both tokens (halves ow traffic). Mixture uses j&1
// dual chains per token (8 chains closed in the stream) instead of j&3 to
// keep the register footprint inside the 1-CTA/SM 204-reg envelope; per-bit
// FP32 fold differs from impl43 but all accumulation stays FP32. NVB!=8
// falls through to the default dispatcher below (opt-in only, K3_IMPL=82).

// ------------------------------------------------------------- duals -----
// impl83 (development experiment, opt-in): two-token SCORE-chain
// interleave at impl43's exact resident shape (10 warps, 2 CTAs/SM, target
// <=102 regs/thread). Distinct from the rejected impl50/51 mapping: those
// dropped to 1 CTA/SM; duals keeps both CTAs resident. Per iteration a CTA
// takes a token pair: score phase interleaves the two tokens' independent
// row-load chains (row_score_packed2, doubling in-flight score loads per
// warp), softmax for the two tokens runs concurrently on warps NW-1/NW-2,
// then the mixture+epilogue phases run sequentially per token with impl43's
// exact j&3 chains (bit-identical math), re-reading s_prob from smem for
// token B to stay inside the register budget. NVB!=8 falls through to the
// default dispatcher.

// ------------------------------------------------------------- leansmt ---
// impl81 (development experiment, opt-in): leanws<false,false> with
// the mixture phase's global row loads replaced by a TMA-staged two-buffer
// smem pipeline. NVB=8 only (R=9). 10 warps, 2 CTAs/SM (same resident shape
// as impl43). Groups are row-parity sets so each group closes one j&3 mixin
// chain (keeping the fold bit-identical to leanws): G0={bank0,bank4,prefix},
// G1={bank1,bank5}, G2={bank2,bank6}, G3={bank3,bank7}. Per token, warp NW-1
// lane0 issues cp.async.bulk copies (tracked by mbarrier complete_tx):
//   at token start (during the score phase): G0 -> buf0 (3 rows, 43008B)
//     and G1 -> buf1 (2 rows, 28672B);
//   after every warp has consumed G0:        G2 -> buf0 (28672B);
//   after every warp has consumed G1:        G3 -> buf1 (28672B).
// Bounded per-token producer/consumer handshake on s_full/s_empty mbarriers;
// the earlier deadlocked cross-token TMA ring and the 20-warp barrier domain
// are both avoided. Consumption is group-outer: each group contributes a
// complete j&3 chain, folded progressively into mixreg (running adds are
// bit-identical to leanws' ((c0+c1)+c2)+c3). sq fold, orr handoff and
// epilogue are verbatim leanws<false,false>. Buffer parities derived from
// the per-CTA iteration counter: group g fills parity (g>>1) (b0/b1 each
// complete two fills per token), producer empty parities 0 (G2/G3) and 1
// (G0/G1 of iterations it>0).

// -------------------------------------------------------------- leanrp --- //
// impl80 (development experiment, opt-in): same-CTA row-pair score
// specialization for NVB=8 (R=9). 20 warps per CTA; score phase assigns TWO
// warps to each source row: warps 2j and 2j+1 reduce the k-chunk halves
// [0,28) and [28,56) of row j via row_score_slice (same 96-register-style 4
// fma chains and lane tree per warp, one extra FP32 add across halves),
// publishing per-half FP32 partials; the softmax warp combines
// d = d_lo + d_hi, s = s_lo + s_hi. The mixture and epilogue phases are
// impl43's direct-load structure verbatim (u = warp + iu*20 chunk mapping,
// same per-element j%4 float2 accumulator chains, same s_qp fold and orr
// epilogue). Softmax butterflies identical (max, exp, sum over lanes 0..R-1).
// No smem row staging and no global-memory intermediates. Opt-in only via
// K3_IMPL=80 with nvb==8; all other cases fall through to impl43.

// -------------------------------------------------------------- leanws2 ---
// impl50 (opt-in): T<=64-oriented two-tokens-per-CTA specialization of
// leanws/impl43. Each CTA processes a token pair per iteration: score warps
// reduce the same row index for BOTH tokens in one fused pass (cw chunk
// loaded once and shared, two independent row streams in flight -> doubles
// per-CTA memory-level parallelism), softmax for the two tokens runs
// concurrently on two dedicated warps, and mixture/epilogue run per token
// sequentially with register usage identical to impl43. Per-token FP32
// reduction and fold orders are bit-identical to impl43 (chunk consumption
// order preserved; only the staging block size changed from 28 to 14, 14|56).
// CTA setup (mbar inits + optional s_cwf staging) is amortized over the pair.

// dual-row score: row0/row1 reduced with independent FP32 accumulator chains;
// each token's math is bit-identical to row_score_packed(_f32cw).
template <bool FCW>
__device__ __forceinline__ void row_score_packed2(const bf16* row0, const bf16* row1,
                                                  const bf16* cw, const float* cwf, int lane,
                                                  float& d0_out, float& s0_out, float& d1_out,
                                                  float& s1_out) {
  constexpr int U2 = 14;  // 56 % 14 == 0; keeps register staging at 56 B
  float2 a_d0[2], a_s0[2], a_d1[2], a_s1[2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
    a_d0[i] = make_float2(0.f, 0.f);
    a_s0[i] = make_float2(0.f, 0.f);
    a_d1[i] = make_float2(0.f, 0.f);
    a_s1[i] = make_float2(0.f, 0.f);
  }
  const uint2* rp0 = reinterpret_cast<const uint2*>(row0 + 4 * lane);
  const uint2* rp1 = reinterpret_cast<const uint2*>(row1 + 4 * lane);
  const uint2* cp = reinterpret_cast<const uint2*>(cw + 4 * lane);
  const float4* fp = reinterpret_cast<const float4*>(cwf + 4 * lane);
#pragma unroll 1
  for (int k0 = 0; k0 < CH; k0 += U2) {
    uint2 rq0[U2], rq1[U2];
#pragma unroll
    for (int u = 0; u < U2; ++u) rq0[u] = rp0[32 * (k0 + u)];
#pragma unroll
    for (int u = 0; u < U2; ++u) rq1[u] = rp1[32 * (k0 + u)];
#pragma unroll
    for (int u = 0; u < U2; ++u) {
      float2 c01, c23;
      if (FCW) {
        float4 c4 = fp[32 * (k0 + u)];
        c01 = make_float2(c4.x, c4.y);
        c23 = make_float2(c4.z, c4.w);
      } else {
        cvt4_f2(cp[32 * (k0 + u)], c01, c23);
      }
      float2 v01, v23, w01, w23;
      cvt4_f2(rq0[u], v01, v23);
      a_d0[0] = fma_x2(v01, c01, a_d0[0]);
      a_d0[1] = fma_x2(v23, c23, a_d0[1]);
      a_s0[0] = fma_x2(v01, v01, a_s0[0]);
      a_s0[1] = fma_x2(v23, v23, a_s0[1]);
      cvt4_f2(rq1[u], w01, w23);
      a_d1[0] = fma_x2(w01, c01, a_d1[0]);
      a_d1[1] = fma_x2(w23, c23, a_d1[1]);
      a_s1[0] = fma_x2(w01, w01, a_s1[0]);
      a_s1[1] = fma_x2(w23, w23, a_s1[1]);
    }
  }
  float d0 = __fadd_rn(a_d0[0].x, a_d0[0].y);
  d0 = __fadd_rn(d0, a_d0[1].x);
  d0 = __fadd_rn(d0, a_d0[1].y);
  float s0 = __fadd_rn(a_s0[0].x, a_s0[0].y);
  s0 = __fadd_rn(s0, a_s0[1].x);
  s0 = __fadd_rn(s0, a_s0[1].y);
  float d1 = __fadd_rn(a_d1[0].x, a_d1[0].y);
  d1 = __fadd_rn(d1, a_d1[1].x);
  d1 = __fadd_rn(d1, a_d1[1].y);
  float s1 = __fadd_rn(a_s1[0].x, a_s1[0].y);
  s1 = __fadd_rn(s1, a_s1[1].x);
  s1 = __fadd_rn(s1, a_s1[1].y);
  d0_out = lane_tree_sum(d0);
  s0_out = lane_tree_sum(s0);
  d1_out = lane_tree_sum(d1);
  s1_out = lane_tree_sum(s1);
  d0_out = __shfl_sync(0xffffffffu, d0_out, 0);
  s0_out = __shfl_sync(0xffffffffu, s0_out, 0);
  d1_out = __shfl_sync(0xffffffffu, d1_out, 0);
  s1_out = __shfl_sync(0xffffffffu, s1_out, 0);
}

// -------------------------------------------------------------- leanws3 ---
// impl51 (opt-in): second two-tokens-per-CTA specialization. 20 warps per
// CTA: warps 0..9 run token tp, warps 10..19 run token tp+1 concurrently
// with identical per-warp roles as impl43 (same chunk mapping, same
// reductions). One CTA setup amortized over the pair; total in-flight warp
// count equals impl43 (32 CTAs x 20 vs 64 x 10 at T=64). Per-token FP32
// reduction orders are identical to impl43 (same helper calls per warp).
// Opt-in only via K3_IMPL=51; impl43 stays default.

// ---------------------------------------------------------------- pipeb ---
// impl46: TMA-staged streaming pipeline. One CTA per SM (large dynamic smem):
// each score warp owns a 14KB smem row slot; right after its score reduce the
// warp issues one cp.async.bulk TMA copy that stages the next token's row into
// its slot (completed via mbarrier tx bytes). Score reads are LDS-fast, the
// DRAM stream never stops (126KB per SM in flight), and the mixture pass
// re-reads rows from global memory where the TMA fill left them warm in L2.
// Arithmetic is identical to leanws (same bytes, same fold order).
// NW configurable: NW=20 doubles mixture-warps per SM for L2-latency hiding
// while score remains on warps 0..R-1 and softmax on warp NW-1.

// --------------------------------------------------------------- pipews ---
// impl47: role-specialized warp pipeline. 9 score warps run a free-running
// loop over tokens (continuous LDG stream -> rows stay warm in L1), one
// softmax warp trails publishing probs and orr, and 10 mixture warps trail
// one token behind (L1-warm reads). Two-slot slot rings with parity mbarriers
// keep the rings consistent with exactly leanws arithmetic per token.
// Roles: warps 0..8 score row w (=warp); warp 19 softmax; warps 9..18 mixture
// with chunk map u = (warp-9) + iu*10 (identical fold to leanws warps 0..9).

// ---------------------------------------------------------------- stream ---
// impl44: single-pass online-softmax-over-rows streaming kernel.
// Each row is read from DRAM exactly once into registers; the prob-weighted
// mixture is accumulated online (running max/lsum rescale) in per-lane
// registers, so there is no second mixture read pass. cw is widened to fp32
// in smem once per launch. Per-row score uses a block reduce with one-row
// lookahead on global loads to keep DRAM streaming through the barriers.
// Layout (same as leanws): chunk u covers elems [256u,256u+256); lane covers
// [256u+8*lane,+8); chunk id u = warp + iu*NW for iu<3 (NCH9=28 chunks).

// ---------------------------------------------------------------- lean3 ---
// impl 42 (development experiment): opt-in accumulator reassociation
// of impl38 (leanws) to cut live accumulator state and target 3 resident
// CTAs/SM at <=64 regs/thread (__launch_bounds__(320, 3)). Structure is
// identical to leanws (score phase, bar[0..3] handoffs, softmax warp, s_qp
// fold, orr publish, register epilogue); only the FP32 accumulation trees
// differ (assoc fold order is NOT bit-identical; FP32 rounding differs):
//   * mixture: accv[4][4] per-j%4 chains -> one serial chain per c (j asc),
//     dropping 24 live float2 regs in the hot loop
//   * rows_q[MAXR] pointer array -> per-j on-the-fly address math
//   * scalar probs; float2 splat at the fma site

// ------------------------------------------------------------- lean3s ---
// development experiment (impl 71): lean3 with *real* live-state
// reduction so 3 CTAs/SM fit at <=64 regs/thread with STACK:0 — unlike lean3,
// which kept leanws's accv[c][j&3] chains (32 live float2) and
// reg-capped to 64, forcing 16-24B stack spills. Here:
//   * mixture: one serial float2 chain per c, j ascending — 8 live floats
//     instead of 32 (fold order changes fp rounding only; FP32 rounding differs)
//   * probs: scalar s_prob[j] LDS per iteration, no 9-register probs[] array
//   * mixture result stashed in s_mix smem across the orr wait and reloaded
//     in the epilogue (as lean3) so no mv[3][4] register residency is needed
// Everything else (score phase, bar[0..3] handoffs, softmax warp, s_qp fold,
// orr publish, next-token L2 prefetch) is lean3/leanws-identical.
// Opt-in only via K3_IMPL=71; impl43 stays default.

// -------------------------------------------------------------- leanring ---
// impl 39 (development experiment): bounded smem producer/consumer
// cp.async ring inside the leanws warp-specialized structure. Warps 0..9 are
// the leanws consumers verbatim (same score phase, bar[0..3] handoffs,
// softmax warp, j%4 mixture chains, s_qp fold, orr publish, register
// epilogue), except the mixture's per-row uint4 loads come from a 2-buffer
// smem ring instead of direct global loads. An 11th warp (PW=10) streams raw
// row data as 512-column tiles (TC=512, NT=H/TC=14 tiles per token): each
// tile = R rows x 1KB staged with 2 cp.async.cg 16B ops per lane per row,
// published via cp.async.mbarrier.arrive on s_full[tile] (count 32).
// Consumers wait s_full[tile] parity it&1, consume their chunk half of the
// tile, and lane0 arrives s_empty[tile] (count 2: the two warps owning
// chunks 2k,2k+1). The producer waits s_empty[k-2] (same token) or
// s_empty[12+k] (previous token, k<2) before reusing a ring slot: one
// mbarrier pair per tile index, one phase per token, so every barrier uses
// the leanws it&1 parity discipline (sharing phase-cycled barriers across
// warps requesting disjoint future tiles breaks the try_wait.parity +/-1
// window and deadlocks). Ring bytes = 2*9*1KB = 18KB; total smem
// (with s_cwf) stays under 48KB and launch_bounds(352,2) keeps 2 CTAs/SM.
// Arithmetic order is bit-identical to leanws (same values, same chains);
// only the data path (async-proxy staged smem vs long-scoreboard global
// loads) changes, converting mixture long-scoreboard stalls into
// short-scoreboard smem reads overlapped with the producer's DRAM stream.
constexpr int TC = 512;       // ring tile width (columns)
constexpr int NT = H / TC;    // 14 tiles per token
constexpr int RBUF = TC * 2;  // bytes per staged row (1KB)

#ifdef K3RING_DEBUG
__device__ int s_k3dbg[8];
__device__ __noinline__ void mbar_wait_dbg(unsigned long long* b, unsigned parity, int who) {
  for (int i = 0; i < (1 << 22); ++i) {
    unsigned done;
    asm volatile(
        "{\n.reg .pred p;\n"
        "mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2;\n"
        "selp.b32 %0, 1, 0, p;\n}\n"
        : "=r"(done)
        : "r"(smem_u32(b)), "r"(parity)
        : "memory");
    if (done) return;
  }
  if (blockIdx.x == 0)
    printf("RING_STARVE b=%d w=%d lane=%d who=%d parity=%u cnt={%d,%d,%d,%d,%d,%d}\n",
           (int)blockIdx.x, (int)(threadIdx.x >> 5), (int)(threadIdx.x & 31), who, parity,
           s_k3dbg[0], s_k3dbg[1], s_k3dbg[2], s_k3dbg[3], s_k3dbg[4], s_k3dbg[5]);
}
#define mbar_wait(b, p) mbar_wait_dbg((b), (p), __LINE__)
#endif

// ---------------------------------------------------------------- splitb ----
// impl 35 (development experiment): lean10 cohort-split pipeline.
// Warps 0..4 (cohort A) score token t+stride into s_score[buf^1] while warps
// 5..9 (cohort B) softmax/mix/reduce/store token t from s_score[buf]. Every B
// warp emulates TWO lean9 logical warps (bw and bw+5), so the chunk->warp
// mapping u = lw + 10*iu, per-logical-warp sq partials, the 10-entry s_qp
// fold, and every per-lane fma order stay bit-identical to impl 28
// (lean9_kernel<FCW,2,10>). Mixed fp32 rows stage through s_mixed; the s_qp
// reduction of token t (named barrier 1 over cohort B) overlaps cohort A's
// DRAM score loads and B's own epilogue stores instead of serializing the
// whole CTA. s_score is the double-buffered cross-step token state.
__device__ __forceinline__ void bar_cohort(int id, int nthr) {
  asm volatile("bar.sync %0, %1;" ::"r"(id), "r"(nthr) : "memory");
}

// ------------------------------------------------------------------ ring2 ---
// impl 34: cp.async double-buffered full-residency single-pass for large T
// (the tuning development direction: TMA/async chunked ring). lean10-exact
// arithmetic (same score fold order, j%4 mixture chains, chunk u=w mod 10
// grouping, NW=10). The nvb bank rows of token t are staged into a ping-pong
// smem ring (2 x 8 x ROWB = 224KiB => 1 CTA/SM) via cp.async.cg; the score
// fold and the mixture both read rows from smem, so every DRAM row is read
// exactly once (lean10 reads them twice - score + mixture). The prefix row
// (j==nvb) stays direct-global (L2-resident after warp nvb's score fold +
// the one-token-ahead L2 prefetch). Staging of token t+stride is issued by
// warps 0..nvb-1 into the OTHER ring buffer right after the score barrier,
// overlapping softmax + mixture + epilogue of token t. Bit-identical to
// impl 28 by construction (same bytes, same fold orders, same grouping).
constexpr int R2ROWS = 8;  // staged bank rows per buffer

// ---------------------------------------------------------------- leanpf ---
// impl 40 (development experiment): consumer-owned prefetch inside the
// leanws structure (same score phase, bar[0..3] mbarrier handoffs, softmax
// warp, j%4 mixture chains, s_qp fold, orr publish, register epilogue; cw NOT
// fp32-cached - the 28KB s_cwf does not fit beside the prefetch buffers at
// 2 CTAs/SM, so the score phase reads L2-resident global cw). There is no
// central producer warp: each mixture consumer warp cp.asyncs its OWN next
// chunk into a private double-buffered smem slot while accumulating the
// current chunk. The per-warp chunk stream wraps across tokens (chunk iu of
// token t, then iu+1, ..., then chunk 0 of t + gridDim), with one chunk of
// lookahead, converting the mixture's long-scoreboard global-load stalls into
// async DRAM overlap.
// Barrier discipline (the development-proven pattern): one mbarrier per (warp,
// slot); expected count 32 is preset at init and every lane signals with
// cp.async.mbarrier.arrive.noinc (issue/completion counts cancel otherwise);
// slot = cnt & 1, wait parity = (cnt >> 1) & 1 where cnt is the warp's own
// chunk sequence number - each barrier's phases are used strictly in order
// (0,1,2,...), the same discipline as leanws's it&1, so no try_wait.parity
// aliasing. Arithmetic order (j%4 chains, sq fold, epilogue) is bit-identical
// to leanws; only the mixture data path changes (async-proxy staged smem vs
// direct global uint4 loads).
// Dynamic smem: 10 warps * 2 slots * 9 rows * 512B = 92160B + ~312B control
// = 92472B, keeps 2 CTAs/SM with 10 warps and launch_bounds(320, 2).
__device__ __forceinline__ void issue_pf_chunk(bf16* slot, const bf16* prefix, const bf16* bank,
                                               int t, int nvb, int R, int u, int lane,
                                               unsigned long long* mb) {
#pragma unroll
  for (int j = 0; j < MAXR; ++j) {
    if (j < R) {
      const bf16* rowp = (j < nvb) ? bank + ((long)t * nvb + j) * H : prefix + (long)t * H;
      cp16(slot + j * 256 + 8 * lane, rowp + 256 * u + 8 * lane);
    }
  }
  // arrive-on fires once all prior cp.async of this lane land; .noinc: the
  // count was preset to 32 at init (see leanring's development note).
  asm volatile("cp.async.mbarrier.arrive.noinc.shared::cta.b64 [%0];\n" ::"r"(smem_u32(mb))
               : "memory");
}

constexpr int PFW = 10;                   // warps
constexpr int PFSLOT_ELEMS = MAXR * 256;  // bf16 elems per chunk slot
constexpr size_t LEANPF_SMEM =
    (size_t)PFW * 2 * PFSLOT_ELEMS * 2 + (MAXR + MAXR + PFW) * 4 + 8 + 4 * 8 + PFW * 2 * 8;

// ---------------------------------------------------------------- leanrp ---
// impl 41 (development experiment): pure-register software pipeline
// of the leanws mixture loads. Score phase, mbarrier handoffs, accumulator
// structure, fold orders, and epilogue are bit-identical to leanws (impl 38);
// the mixture loop is the ONLY change. Chunk (iu, j)'s accumulator work is
// issued AFTER the guarded load of the next row (j+1 of the same chunk, or
// row 0 of chunk iu+1 at the boundary) so ~1-row-worth of fma work overlaps
// each in-flight load; lookahead registers are a single uint4, keeping the
// register budget inside the __launch_bounds__(320, 2) 102-reg envelope
// (no spills, 2 CTAs/SM retained). Loads are guarded by (j + 1 < R) so only
// rows that contribute to the mixture are fetched - arithmetic unchanged.

// ------------------------------------------------------------------ clu9 ----
// impl 33: single-launch thread-block-cluster path for small T (tuning
// development direction). One cluster of C CTAs per token; lean9's 9 virtual
// warps are distributed across the cluster (vw = crank*WPC + warp, WPC=9/C).
// Scores and output-norm partials are exchanged via DSMEM (st.shared::cluster
// to every CTA's mirror arrays + cluster.sync). Chunk ownership stays u%9 and
// every reduction order (row score warp tree, softmax butterflies, j%4
// mixture chains, s_qp[0..8] sequential fold) is identical to lean9, so the
// result is bit-identical to impl 11 while engaging Cx more SMs per token.

// ------------------------------------------------------------------ lean9p --// impl 16: pipelined
// lean9. Score(t+stride) is computed DURING mixture(t) - 14 lane-chunks between each mixture
// chunk-pair - so the next score phase's DRAM latency hides under mixture compute. s_score/s_qp are
// double buffered (race-free: see invariants in the loop body). Score chunk order and fold order
// are unchanged, so scores remain bit-identical to lean9.

// ------------------------------------------------------------------ leanS ---
// ----------------------------------------------------------------- lean11 --
// impl 30: lean9/lean10 with a cp.async smem staging ring. During the mixture
// phase of token t, warps 0..NSTG-1 (NSTG = min(R,8)) asynchronously stage
// rows(token t+stride) into s_stage (bf16, 8*14KB=112KB). The score phase of
// token t+stride then folds from smem instead of DRAM-in-flight loads, so the
// DRAM stream for scores runs continuously under the mixture compute instead
// of serializing at the per-token phase barrier. cp.async is register-free,
// keeping the lean10 register budget. Landing in smem passes the rows through
// L2, so the mixture phase's global re-reads hit L2. Score fold order is
// unchanged (same data, same per-lane order from the contiguous smem copy),
// so scores remain bit-identical to row_score_packed. The row R-1 (prefix,
// when R==9) keeps the direct-global score + prefetch_l2 path.

// impl 15: small-T staged lean4. One CTA per token (128 threads). ALL rows
// plus cw and ow are staged into shared memory with a single cooperative
// cp.async burst (one DRAM round trip, ow prefetch included), then the
// lean4-identical arithmetic runs entirely from smem: full-row warp score
// reduction (row_score_packed), redundant per-warp softmax butterflies,
// quarter-per-warp mixture with j%4 chains, quarter sq partials, epilogue
// straight from registers. Rows are touched exactly once in DRAM.
constexpr int SROWS = MAXR + 2;  // R rows + cw + ow
constexpr int SSMB = SROWS * ROWB + (MAXR + QW) * sizeof(float);

// RC = exact row count at compile time: the j-loops fully unroll with no
// runtime bounds checks, shrinking the fetched code path for tiny-R launches
// (icache misses dominate the T<=8 latency at cold L2).

// ======================= impl 97: leanF — load-and-score fused small-T path
// development tuning (opt-in via K3_IMPL=97): fuse the row staging
// and score phases. Each thread issues ONE synchronous uint4 row load per
// vector; the loaded registers (1) write into s_rows for the mixture and
// (2) immediately accumulate per-thread FP32 dot[j]/sumsq[j] partials against
// register-resident cw. The serial score phase that re-read rows from smem is
// deleted; scores become a 7-warp-partial smem reduction per row. Mixture,
// softmax, RMS and epilogue are byte-identical to leanT. Differs from the
// falsified leanG (paid both LDGSTS and LDG) and leanV (dropped staging; no
// smem copy for the mixture): single global read per element, both uses.
template <int RC>
__global__ __launch_bounds__(7 * 32, 1) void leanF_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, int nvb, float eps) {
  constexpr int QWT = 7;
  constexpr int NT = QWT * 32;         // 224 threads
  constexpr int NCH = H / 8;           // 896 uint4 chunks
  constexpr int CPT = NCH / NT;        // 4 chunks per thread
  constexpr int QQQH = H / QWT;        // elements per warp-slice
  constexpr int QQU4 = QQQH / 8 / 32;  // 4 uint4 per lane per slice
  extern __shared__ char smem_raw[];
  bf16* s_rows = reinterpret_cast<bf16*>(smem_raw);  // MAXR rows
  bf16* s_ow = s_rows + MAXR * H;
  float* s_score = reinterpret_cast<float*>(s_ow + H);
  float* s_qp = s_score + MAXR;
  float2* s_part = reinterpret_cast<float2*>(s_qp + 28 + 1);  // [RC][QWT], 8B-aligned

  const int warp = threadIdx.x >> 5;
  const int lane = threadIdx.x & 31;
  const int tid = threadIdx.x;
  const int R = RC;

  pdl_wait();
  for (int t = blockIdx.x; t < T; t += gridDim.x) {
    // ---- cw into registers; ow staged to smem (synchronous) ----------
    uint4 creg[CPT];
#pragma unroll
    for (int k = 0; k < CPT; ++k) {
      int i = tid + k * NT;
      creg[k] = __ldg(reinterpret_cast<const uint4*>(cw) + i);
      reinterpret_cast<uint4*>(s_ow)[i] = __ldg(reinterpret_cast<const uint4*>(ow) + i);
    }

    // ---- fused load+score: one LDG per vector feeds smem + partials --
#pragma unroll
    for (int j = 0; j < R; ++j) {
      const bf16* rp = (j < nvb) ? bank + ((long)t * nvb + j) * H : prefix + (long)t * H;
      const uint4* src = reinterpret_cast<const uint4*>(rp);
      uint4* dst = reinterpret_cast<uint4*>(s_rows + (size_t)j * H);
      float2 d2 = make_float2(0.f, 0.f);
      float2 s2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int k = 0; k < CPT; ++k) {
        int i = tid + k * NT;
        uint4 v = __ldg(src + i);
        dst[i] = v;
        float2 c01, c23, c45, c67;
        cvt4_f2(make_uint2(creg[k].x, creg[k].y), c01, c23);
        cvt4_f2(make_uint2(creg[k].z, creg[k].w), c45, c67);
        float2 v01, v23, v45, v67;
        cvt4_f2(make_uint2(v.x, v.y), v01, v23);
        cvt4_f2(make_uint2(v.z, v.w), v45, v67);
        d2 = fma_x2(v01, c01, d2);
        d2 = fma_x2(v23, c23, d2);
        d2 = fma_x2(v45, c45, d2);
        d2 = fma_x2(v67, c67, d2);
        s2 = fma_x2(v01, v01, s2);
        s2 = fma_x2(v23, v23, s2);
        s2 = fma_x2(v45, v45, s2);
        s2 = fma_x2(v67, v67, s2);
      }
      s_part[j * NT + tid] = make_float2(__fadd_rn(d2.x, d2.y), __fadd_rn(s2.x, s2.y));
    }
    __syncthreads();

    // ---- score: warp w reduces rows w, w+QWT, ... over NT partials ---
#pragma unroll
    for (int j = warp; j < R; j += QWT) {
      float d = 0.f, s = 0.f;
#pragma unroll
      for (int k = 0; k < NT / 32; ++k) {
        float2 p = s_part[j * NT + lane + k * 32];
        d = __fadd_rn(d, p.x);
        s = __fadd_rn(s, p.y);
      }
      d = lane_tree_sum(d);
      s = lane_tree_sum(s);
      if (lane == 0) {
        float mean = __fmul_rn(s, INVH);
        float rrms = rsqrtf(__fadd_rn(mean, eps));
        s_score[j] = __fmul_rn(d, rrms);
      }
    }
    __syncthreads();

    // ---- softmax: every warp redundantly (identical to leanT) --------
    float pr;
    {
      float sc = (lane < R) ? s_score[lane] : -INFINITY;
      float m = sc;
#pragma unroll
      for (int off = 16; off > 0; off >>= 1) m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, off));
      float e = __expf(__fadd_rn(sc, -m));
      float sm = __fadd_rn(e, __shfl_xor_sync(0xffffffffu, e, 16));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 8));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 4));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 2));
      sm = __fadd_rn(sm, __shfl_xor_sync(0xffffffffu, sm, 1));
      pr = (lane < R) ? __fdiv_rn(e, sm) : 0.f;
    }
    float2 prob2[RC];
#pragma unroll
    for (int j = 0; j < RC; ++j) {
      float p = __shfl_sync(0xffffffffu, pr, j);
      prob2[j] = make_float2(p, p);
    }

    // ---- mixture over my slice from smem (identical to leanT) --------
    const uint4* rows_q[RC];
#pragma unroll
    for (int j = 0; j < RC; ++j) {
      rows_q[j] = reinterpret_cast<const uint4*>(s_rows + (size_t)j * H + warp * QQQH + 8 * lane);
    }
    float2 mixreg[QQU4][4];
    float2 sq2[4];
#pragma unroll
    for (int c = 0; c < 4; ++c) sq2[c] = make_float2(0.f, 0.f);
#pragma unroll
    for (int u = 0; u < QQU4; ++u) {
      float2 accv[4][4];
#pragma unroll
      for (int c = 0; c < 4; ++c)
#pragma unroll
        for (int cc = 0; cc < 4; ++cc) accv[c][cc] = make_float2(0.f, 0.f);
#pragma unroll
      for (int j = 0; j < RC; ++j) {
        uint4 q = rows_q[j][32 * u];
        float2 v[4];
        cvt4_f2(make_uint2(q.x, q.y), v[0], v[1]);
        cvt4_f2(make_uint2(q.z, q.w), v[2], v[3]);
#pragma unroll
        for (int c = 0; c < 4; ++c) accv[c][j & 3] = fma_x2(prob2[j], v[c], accv[c][j & 3]);
      }
#pragma unroll
      for (int c = 0; c < 4; ++c) {
        float2 mv = add_x2(accv[c][0], accv[c][1]);
        mv = add_x2(mv, accv[c][2]);
        mv = add_x2(mv, accv[c][3]);
        mixreg[u][c] = mv;
        sq2[c] = fma_x2(mv, mv, sq2[c]);
      }
    }
    float sq = __fadd_rn(sq2[0].x, sq2[0].y);
    sq = __fadd_rn(sq, sq2[1].x);
    sq = __fadd_rn(sq, sq2[1].y);
    sq = __fadd_rn(sq, sq2[2].x);
    sq = __fadd_rn(sq, sq2[2].y);
    sq = __fadd_rn(sq, sq2[3].x);
    sq = __fadd_rn(sq, sq2[3].y);
    sq = lane_tree_sum(sq);
    if (lane == 0) s_qp[warp] = sq;
    __syncthreads();
    float st = s_qp[0];
#pragma unroll
    for (int w = 1; w < QWT; ++w) st = __fadd_rn(st, s_qp[w]);
    float mean2 = __fmul_rn(st, INVH);
    const float orr = rsqrtf(__fadd_rn(mean2, eps));
    const float2 orr2 = make_float2(orr, orr);

    // ---- epilogue from registers (identical to leanT) ----------------
    const uint4* owp = reinterpret_cast<const uint4*>(s_ow + warp * QQQH + 8 * lane);
    uint4* outp = reinterpret_cast<uint4*>(out + (long)t * H + warp * QQQH + 8 * lane);
#pragma unroll
    for (int u = 0; u < QQU4; ++u) {
      uint4 oq = owp[32 * u];
      float2 o01, o23, o45, o67;
      cvt4_f2(make_uint2(oq.x, oq.y), o01, o23);
      cvt4_f2(make_uint2(oq.z, oq.w), o45, o67);
      float2 r01 = mul_x2(mul_x2(mixreg[u][0], orr2), o01);
      float2 r23 = mul_x2(mul_x2(mixreg[u][1], orr2), o23);
      float2 r45 = mul_x2(mul_x2(mixreg[u][2], orr2), o45);
      float2 r67 = mul_x2(mul_x2(mixreg[u][3], orr2), o67);
      __nv_bfloat162 b01 = __float22bfloat162_rn(r01);
      __nv_bfloat162 b23 = __float22bfloat162_rn(r23);
      __nv_bfloat162 b45 = __float22bfloat162_rn(r45);
      __nv_bfloat162 b67 = __float22bfloat162_rn(r67);
      uint4 o4;
      o4.x = *reinterpret_cast<unsigned*>(&b01);
      o4.y = *reinterpret_cast<unsigned*>(&b23);
      o4.z = *reinterpret_cast<unsigned*>(&b45);
      o4.w = *reinterpret_cast<unsigned*>(&b67);
      outp[32 * u] = o4;
    }
  }
  pdl_launch_dependents();
}

// ======================= impl 135: leanS3 — register-resident lean static NSRC
// development tuning candidate for the failing (T=8, NVB=2)
// gate row — R103 RESULT: FALSIFIED, opt-in only via K3_LEANS3_T (never
// dispatched by default; see the leans3_bound() verdict comment for the
// NCU/fixed-runner evidence). A qualitative break from the chp/chtm family
// (TMA ring, TMEM cw/ow, mbarrier producer, persistent grid-stride token
// loop) and from the two falsified lean ancestors:
//   * leanF (impl97): smem-stages every row during the fused load, then the
//     mixture re-reads rows from SMEM (STS+LDS round trip per element).
//   * nsrc (impl102, R59, lost -7.4..-23.4% at nvb=2 small-T): dropped the
//     staging but re-read every row from GLOBAL for the mixture and paid a
//     SPLIT=2 cross-warp fold stage in the score phase.
// leanS3 keeps the one physical minimum the falsified variants missed: each
// source-row element crosses the GMEM->register boundary EXACTLY ONCE.
// Structure (compile-time NSRC sources; dispatch NVB = NSRC-1):
//   * grid = T exactly, one static 7-warp (224-thread) CTA per token, NO
//     token loop, NO TMA/mbarrier/TMEM/setmaxnreg machinery.
//   * score: thread tid owns uint4 k of every row (i = tid + k*224,
//     k<4: 224 threads*4*16B = 14336B = H). cw lives in creg[4] registers
//     (one __ldg pass, reused all rows); each row's 4 uint4 loads stay
//     LIVE in rreg[NSRC][4] while FP32 (dot, sumsq) partials accumulate
//     with the packed f32x2 FMAs — the loaded registers feed the mixture
//     later, so no second global read exists anywhere.
//   * s_part[j][tid] float2 partials + leanF's per-warp fold (row j on
//     warp j: guard j<R skips warps 3..6), lane 0 emits
//     score[j] = dot * rsqrtf(mean(sumsq)+eps). FP32 fold order is
//     byte-identical to leanF (ascending k, lane_tree_sum).
//   * softmax: leanF's lane butterflies redundantly per warp (identical).
//   * mixture: REGISTER FMA only — for each owned uint4 k the three
//     prob2[j] scalars FMA into leanF's accv[c][j&3] tree (identical
//     rounding order); lane-local sq2 accumulation of the mixed vector.
//   * output RMS: lane_tree_sum + s_qp[7] ascending cross-warp fold
//     (identical to leanF), orr = rsqrtf(mean+eps).
//   * epilogue: ow via __ldg straight from global (no smem staging),
//     r = (mix * orr) * ow, single BF16 store. Only `out` touches global.
// Dynamic smem (no row/ow staging): s_part[NSRC][224] f32x2 + s_score +
// s_qp = NSRC*1792 + 48 B (~5.4 KB at NSRC=3). Tolerance class unchanged
// (leanF fold order everywhere); eps inside BOTH rsqrtf calls.
// Unit-wide explicit instantiation: preres route tables take the function
// address by name (R61 nvcc lazy-instantiation trap).

// ======================= impl 102: nsrc — NSRC-specialized warp-per-row path
// development tuning (opt-in via K3_IMPL=102): single launch, one
// CTA per token, aimed at the launch-limited small-T rows (T=4/NVB=2,
// T=16/NVB=4). Structure:
//   * score phase: each source row's reduction runs CONCURRENTLY on its own
//     warp (a warp PAIR halves the critical chain for NSRC<=3): the assigned
//     warp streams its row slice straight from global memory (28 or 14 x
//     uint4/lane), accumulating FP32 dot/sumsq partials against __ldg cw
//     (L1/L2-resident). Per-warp partials land in s_pair[MAXR][2]; after one
//     barrier every warp redundantly folds score[j] = dot*rsqrt(mean+eps) and
//     the lane butterfly softmax (identical arithmetic to leanF). No s_part
//     smem round trip, no separate score pass, no smem row staging.
//   * mixture: the same warp-slice layout as leanF re-reads the rows from
//     global (L2-resident at these T) into register accumulators; every
//     intermediate stays inside the CTA. FP32 output-RMS across the 7 warps,
//     ow from global via __ldg, one BF16 store. Nothing but the output is
//     materialized in global memory.
// Fold order follows impl97 (leanF); tolerance class unchanged.

// ======================= impl 101: c4w — compact 4-warp NVB=8 fused path
// development tuning (opt-in via K3_IMPL=101, NVB==8 only): one
// compact 128-thread CTA per token for the grid-starved T=64/128 regime.
// Deliberately removes everything the retired 288/384-thread occupancy-2 TMA
// variants carried: no producer warp, no TMA ring, no smem row staging and no
// smem mixture round trips. Structure:
//   * score phase: cooperative 16B row loads (tid + k*NT), per-thread FP32
//     dot/sumsq partials into s_part[RC][NT]; each warp then sequentially
//     reduces its 2-3 assigned rows (j = warp; j += 4) and lane 0 emits
//     score[j] = dot * rsqrt(mean(sumsq) + eps).
//   * softmax redundantly per warp (identical arithmetic to leanF).
//   * mixture: each thread accumulates its CPT=7 column chunks over all 9
//     rows directly from global memory (second read hits L2 at T<=128) into
//     registers; no smem staging of rows or mixed intermediates.
//   * output RMS: lane_tree_sum + 4-partial cross-warp smem broadcast;
//     epilogue multiplies by rsqrt(mean+eps) * ow and stores BF16 once.
// Nothing is materialized in global memory beyond the single output store.
// R57 result: FALSIFIED by the tuning's own retention rule — in
// ordering-reversed cold-L2 NCU A/B (gpu__time_duration, medians of 10,
// --clock-control none --cache-control all) c4w loses to chtm at both target
// shapes: T=64 8.86/9.06us vs chtm 7.49/7.52 and chp 7.55/7.46 (+18..20%);
// T=128 9.70/9.70 vs chtm 8.54/8.51 and chp 8.61/8.48 (+13..14%). Root cause:
// the score phase reads every row from DRAM and the mixture phase re-reads all
// 9 rows with no TMA ring to cover the latency; the single-pass producer/ring
// pipelines hide the memory chain better even at sub-wave grids. Kept opt-in
// only (K3_IMPL=101); NOT dispatched anywhere.
// R58 (directive completion pass): this NVB=8 branch's correctness re-verified
// against the double-precision ref at the directive's adjacent sizes
// T=63/64/65, 127/128/129, 256 and T=1 (r58_check101.py): zero abs-gate
// (3.125e-2, half the official 6.25e-2 atol) violations, zero NaNs; worst
// max_abs_err 3.125e-02 at T=128 = 1 bf16 ulp at reference scale. The "fails
// only when its NVB=8 branch executes" defect cited by the directive does not
// reproduce with the standard seed set — no code fix was required.
// R58 timing (same NCU protocol, T=64/128/256, orderings A=87,101,85 and
// B=85,101,87, medians of 12): T=64 c4w 8.77/8.70 vs chtm 7.55/7.46, chp
// 7.46/7.65 (+14..18%); T=128 c4w 9.66/9.63 vs chtm 8.54/8.61, chp 8.61/8.61
// (+12..13%); T=256 c4w 11.84/11.71 vs chtm 11.78/11.81 (tie) and chp
// 12.38/12.58 (-4.4/-6.9%). Retention needs wins at all three sizes in both
// orderings: FAILS at T=64/128. Not retained; no cutover installed. The
// T=256 win over chp (the R56 band incumbent for nvb=8 T=57..287) is noted
// for the tuning but is below the directive's bar and below gate-flap
// noise, so the R56 dispatcher stays byte-identical.

// ======================= impl 91/92: leanT — leanS with templated warp count
// Same structure, staging, arithmetic and numerics as leanS_kernel, but the
// block size is a template parameter (QWT warps; QWT must divide H/(8*32)=28,
// so 7 = 224 threads or 14 = 448 threads). At small T the whole kernel is one
// short latency chain; wider blocks cut staging iterations (7->4/2 per row),
// mixture iterations (QU4=7->4/2) and the score phase's serial row loop.
// (development tuning: lean NVB-specialized small-T variant.)

// ============================= impl 12: multi-CTA-per-token staged path =====
// Column parallelism where it is safe, bitwise-faithful scores where near-zero
// cancellation in the mixture demands reference-order fidelity:
//   s1: grid (T*R) x 1 warp — per-row score via the proven row_score order
//   s2: grid (T) x 1 warp — proven softmax_warp, in place over the scores
//   s3: grid (T*MC_NC) x 128 threads — prob-weighted mixed chunk in registers
//       (proven j%4 four-accumulator order per element), block sumsq -> atomic
//       accumulate; last CTA per token publishes via an atomic flag; all CTAs
//       then normalize with out_weight. Chunk CTAs of a token are adjacent in
//       launch order (1-D grid) so the publish/spin handoff is wave-safe.
constexpr int MC_NC = 7;             // 7 chunks x 1024 elems = 7168
constexpr int MC_CHUNK = H / MC_NC;  // 1024

// ============================= impl 13: single-launch staged small-T =========
// One launch; grid T*SC_NC blocks x 128 threads. Score phase: block c warp0
// scores row c (warp1 scores row c+SC_NC when R > SC_NC), writes the score in
// bitwise row_score order, publishes via a per-token counter. Every block
// spins for its token's R scores, computes the proven softmax_warp
// redundantly into smem, mixes its 1024-element chunk with the proven j%4
// accumulator order, atomic-accumulates the output sumsq, and uses the mc_mix
// publish/spin protocol for the final normalize. Same wave-safety argument as
// mc_mix: a token's SC_NC blocks are adjacent in the 1-D launch order.
constexpr int SC_NC = 7;             // 7 chunks x 1024 elems = 7168
constexpr int SC_CHUNK = H / SC_NC;  // 1024

// ---------------------------------------------------------------- leantp ---
// impl 68/69/70 (development experiment): dynamically register-
// partitioned producer/consumer streaming kernel. A TMA producer warpgroup
// (setmaxnreg.dec -> 40 regs) streams bank rows + the appended prefix row
// through an NS-stage smem ring of CH-row chunks; 8 direct-compute consumer
// warps (setmaxnreg.inc -> CREGS regs) do a single-pass online-softmax fold:
// per chunk they compute the FP32 rms/dot score partials from the smem rows,
// reduce across the 8 warps via smem partial arrays + a named barrier, fold
// the chunk logits into a running max/sum with exp2f correction, and rescale-
// accumulate the mixture in registers. DRAM traffic is one pass per row;
// latency hiding comes from the async TMA ring, not warp count.
//   impl68: ASYM (4 producer warps, 384 threads), NS=3 ring
//   impl69: symmetric control (1 producer warp, 288 threads, no setmaxnreg)
//   impl70: ASYM, NS=4 ring
// Opt-in only via K3_IMPL; impl43 stays default. Arithmetic: FP32 partials,
// ascending-warp folds, online softmax == max-subtracted softmax within FP
// rounding (verified against the same ref_math gate as every other impl).
template <int N>
__device__ __forceinline__ void setmaxnreg_dec_w() {
  static_assert(N >= 24 && N <= 256 && (N & 7) == 0);
  asm volatile("setmaxnreg.dec.sync.aligned.u32 %0;\n" ::"n"(N));
}
template <int N>
__device__ __forceinline__ void setmaxnreg_inc_w() {
  static_assert(N >= 24 && N <= 256 && (N & 7) == 0);
  asm volatile("setmaxnreg.inc.sync.aligned.u32 %0;\n" ::"n"(N));
}
// Distinct named barrier IDs per logical rendezvous: the per-chunk score
// reduction (ID 1) and the per-token out-norm (ID 2). Sharing one ID lets a
// fast warp arriving at next chunk's score-bar complete a 256-count barrier
// together with slow warps still parked at the previous token's out-norm
// bar — a mixed-participant completion that corrupts both rendezvous and
// deadlocks the ring on multi-token CTAs.
__device__ __forceinline__ void bar_cons_sync(int id) {
  asm volatile("bar.sync %0, 256;" ::"r"(id) : "memory");
}
// Dealloc-early handoff (impl131/chtgd, named barrier ID 9 — disjoint from
// the consumer score (1) / out-norm (2) rendezvous IDs and from every other
// named barrier in this file): the 256 consumer threads arrive non-blocking
// once their FINAL TMEM load has completed (tm05_wait_ld retires the ow
// slices into registers), and the single owner warp (warp 8, which owns the
// tcgen05.alloc) blocks on the same barrier, then performs the dealloc
// while the consumers execute the remaining FP32 epilogue + global stores.
// Count = 256 consumer arrivals + 32 owner-warp participants. The wait::ld
// in each consumer warp plus the barrier's cross-warp ordering establish the
// mandatory lifecycle order (all TMEM ld/st complete before dealloc).
__device__ __forceinline__ void bar_dealloc_arrive() {
  asm volatile("bar.arrive 9, 288;" ::: "memory");
}
__device__ __forceinline__ void bar_dealloc_wait() {
  asm volatile("bar.sync 9, 288;" ::: "memory");
}
// Publish mbarrier initialization from the generic proxy before the TMA
// async engine uses the barrier (mandatory per PTX; missing fence lets the
// TMA unit read pre-init barrier state and the ring deadlocks on chunk 0).
__device__ __forceinline__ void fence_mbar_init() {
  asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
}

// ---- tensor-memory (TMEM) helpers, SM100 tcgen05 ---------------------------
// Lifecycle order is mandatory: alloc (one warp, nCols power of 2 in [32,512],
// 32-bit TMEM address written to smem) -> __syncthreads + read taddr ->
// st/wait::st -> ld/wait::ld -> dealloc before CTA exit. Each warp touches
// only its own 32-lane TMEM band (warp id mod 4 selects the band), so lane
// ownership is symmetric between our store and load sites. The address' low
// 16 bits are the column; the lane band is implicit per warp.
__device__ __forceinline__ void tm05_alloc(unsigned smem_slot_u32, unsigned ncols) {
  asm volatile(
      "tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(smem_slot_u32),
      "r"(ncols));
}
__device__ __forceinline__ void tm05_relinq() {
  asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
}
__device__ __forceinline__ void tm05_dealloc(unsigned taddr, unsigned ncols) {
  asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(taddr), "r"(ncols));
}
__device__ __forceinline__ void tm05_st8(unsigned taddr, const unsigned* v) {
  asm volatile("tcgen05.st.sync.aligned.32x32b.x8.b32 [%8], {%0,%1,%2,%3,%4,%5,%6,%7};" ::"r"(v[0]),
               "r"(v[1]), "r"(v[2]), "r"(v[3]), "r"(v[4]), "r"(v[5]), "r"(v[6]), "r"(v[7]),
               "r"(taddr));
}
__device__ __forceinline__ void tm05_ld8(unsigned taddr, float2* v /*4 float2*/) {
  unsigned r0, r1, r2, r3, r4, r5, r6, r7;
  asm volatile(
      "tcgen05.ld.sync.aligned.32x32b.x8.b32 "
      "{%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
      : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3), "=r"(r4), "=r"(r5), "=r"(r6), "=r"(r7)
      : "r"(taddr));
  v[0] = make_float2(__uint_as_float(r0), __uint_as_float(r1));
  v[1] = make_float2(__uint_as_float(r2), __uint_as_float(r3));
  v[2] = make_float2(__uint_as_float(r4), __uint_as_float(r5));
  v[3] = make_float2(__uint_as_float(r6), __uint_as_float(r7));
}
// x4 (4-column) variants for the half-width tail slice (H=7168 tile 6 is
// split between the two consumer warpgroups at 4 elements per thread).
__device__ __forceinline__ void tm05_st4(unsigned taddr, const unsigned* v) {
  asm volatile("tcgen05.st.sync.aligned.32x32b.x4.b32 [%4], {%0,%1,%2,%3};" ::"r"(v[0]), "r"(v[1]),
               "r"(v[2]), "r"(v[3]), "r"(taddr));
}
__device__ __forceinline__ void tm05_ld4(unsigned taddr, float2* v /*2 float2*/) {
  unsigned r0, r1, r2, r3;
  asm volatile(
      "tcgen05.ld.sync.aligned.32x32b.x4.b32 "
      "{%0,%1,%2,%3}, [%4];"
      : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3)
      : "r"(taddr));
  v[0] = make_float2(__uint_as_float(r0), __uint_as_float(r1));
  v[1] = make_float2(__uint_as_float(r2), __uint_as_float(r3));
}
__device__ __forceinline__ void tm05_wait_st() {
  asm volatile("tcgen05.wait::st.sync.aligned;" ::: "memory");
}
__device__ __forceinline__ void tm05_wait_ld() {
  asm volatile("tcgen05.wait::ld.sync.aligned;" ::: "memory");
}

// ------------------------------------------------------------------ chp ----
// impl 85 (development experiment, opt-in): production-style chunked
// TMA pipeline mirroring the reference producer/consumer design. One
// low-register TMA producer warp (warpgroup, setmaxnreg.dec -> 40) streams
// CH-row chunks through an NS=2 smem ring guarded by bar_full/bar_free
// mbarrier pairs; two consumer warpgroups (8 warps, setmaxnreg.inc -> CREGS)
// do chunk-local online softmax/mixture with FP32 accumulators (packed
// f32x2), cross-warp smem partials + named-barrier rendezvous per chunk, and
// a register epilogue. NVB and CH are template parameters with the
// benchmarked per-NVB (chunk_rows, occupancy, consumer_regs) table:
//   nvb=1: (2, occ2, CREGS=0, 288 threads, no setmaxnreg)
//   nvb=2,3: (4, occ1, 200)    nvb=4,8: (5, occ1, 200)
//   nvb=5: (3, occ1, 200)      nvb=6,7: (4, occ1, 200)
// Differs from leantp (impl68-70, development DNF): (1) the consumer ring
// counter `gc` is declared OUTSIDE the token loop, mirroring the producer —
// leantp reset it per token, desyncing slot/phase from the producer for any
// multi-token CTA (the R32 hang); (2) NVB/CH compile-time so chunk counts
// fold into the unrolled loops; (3) NS frozen at 2; (4) per-NVB configs.
// FP32 partials, ascending-warp folds, online softmax == max-subtracted
// softmax within FP rounding.
// NVBC: chunk-row config, NOCC: min CTAs/SM, NCREGS: consumer reg budget
// (0 = symmetric 288-thread launch, no setmaxnreg).
// R61: extern template instantiation for impl104's pre-resolved launcher
// (forward_fast5 takes the function address by name below; without one
// explicit instantiation unit-wide nvcc lazy-instantiation emitted no
// device symbol for cudaFuncSetAttribute in this 13k-line TU).
template <int NVB, int NVBC, int NOCC, int NCREGS, int PFL = 0>
__global__ __launch_bounds__((NCREGS > 0) ? 384 : 288, NOCC) void chp_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int CH = NVBC;
  constexpr int NCH = (R + CH - 1) / CH;
  constexpr int NS = 2;
  constexpr bool ASYM = (NCREGS > 0);
  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  extern __shared__ char dyn[];
  bf16* buf = reinterpret_cast<bf16*>(dyn);  // [NS][CH][H]
  unsigned long long* bar_f = reinterpret_cast<unsigned long long*>(dyn + (size_t)NS * CH * ROWB);
  unsigned long long* bar_e = bar_f + NS;
  float* warp_rms = reinterpret_cast<float*>(bar_e + NS);  // [2][8][CH]
  float* warp_dot = warp_rms + 2 * 8 * CH;                 // [2][8][CH]
  float* warp_ssq = warp_dot + 2 * 8 * CH;                 // [2][8]

  pdl_wait();
  if (tx == 0) {
#pragma unroll
    for (int s = 0; s < NS; ++s) {
      mbar_init(&bar_f[s], 1);
      mbar_init(&bar_e[s], 256);
    }
  }
  fence_mbar_init();
  __syncthreads();

  if (warp >= 8) {
    // ---- producer: async TMA ring filler (warp 8, elected lane) -------
    if (ASYM) setmaxnreg_dec_w<40>();
    if (warp == 8 && lane == 0) {
      unsigned gc = 0;  // monotonic across tokens (ring state)
      for (int t = blockIdx.x; t < T; t += gridDim.x) {
#pragma unroll
        for (int ci = 0; ci < NCH; ++ci) {
          const int base = ci * CH;
          const int an = ((R - base) < CH) ? (R - base) : CH;
          const unsigned slot = gc % NS;
          const unsigned phase = (gc / NS) & 1;
          if (gc >= (unsigned)NS) mbar_wait(&bar_e[slot], phase ^ 1);
          mbar_arrive_expect_tx(&bar_f[slot], (unsigned)(an * ROWB));
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            if (r < an) {
              const int row = base + r;
              const bf16* src = (row < NVB) ? bank + (long long)t * stride_bm + (long long)row * H
                                            : prefix + (long long)t * H;
              cp_bulk_g2s(buf + ((size_t)slot * CH + r) * H, src, (unsigned)ROWB, &bar_f[slot]);
            }
          }
          if (PFL > 0) {
            // L2 lookahead (impl119): warm chunk gc+PFL's gmem
            // rows into L2 now — before the consumers finish
            // reducing the chunks already in the ring — so the
            // future TMA load drains from L2, not DRAM.
            const unsigned aha = gc + (unsigned)PFL;
            const int tok_d = (int)(aha / NCH) - (int)(gc / NCH);
            const long long t_l = (long long)t + (long long)tok_d * gridDim.x;
            if (t_l < T) {
              const int ci_l = (int)(aha % NCH);
              const int base_l = ci_l * CH;
              const int an_l = ((R - base_l) < CH) ? (R - base_l) : CH;
#pragma unroll
              for (int r = 0; r < CH; ++r) {
                if (r < an_l) {
                  const int row = base_l + r;
                  const bf16* src =
                      (row < NVB) ? bank + t_l * stride_bm + (long long)row * H : prefix + t_l * H;
                  cp_bulk_prefetch_l2(src, (unsigned)ROWB);
                }
              }
            }
          }
          ++gc;
        }
      }
    }
  } else {
    // ---- consumers: chunk-local online softmax/mixture -----------------
    if constexpr (ASYM) setmaxnreg_inc_w<NCREGS>();
    const int group = warp >> 2;  // 0/1: interleaved 1024-elem tiles
    const int tig = tx & 127;
    const float LOG2E = 1.4426950408889634f;
    // register-resident fp32 cw slices (constant across tokens); ow too
    // when the register budget allows (ASYM/NCREGS>0).
    float2 cw2[4][4], ow2[4][4];
#pragma unroll
    for (int si = 0; si < 4; ++si) {
      const int tile = si * 2 + group;
      if (tile < 7) {
        uint4 q = reinterpret_cast<const uint4*>(cw + (tile * 128 + tig) * 8)[0];
        cvt4_f2(make_uint2(q.x, q.y), cw2[si][0], cw2[si][1]);
        cvt4_f2(make_uint2(q.z, q.w), cw2[si][2], cw2[si][3]);
        if (ASYM) {
          q = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
          cvt4_f2(make_uint2(q.x, q.y), ow2[si][0], ow2[si][1]);
          cvt4_f2(make_uint2(q.z, q.w), ow2[si][2], ow2[si][3]);
        }
      }
    }
    unsigned gc = 0;  // FIX vs leantp: outside the token loop; mirrors
                      // the producer's monotonic ring counter. (The R32
                      // hang was this scoping bug.)
    for (int t = blockIdx.x; t < T; t += gridDim.x) {
      float2 acc2[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si)
#pragma unroll
        for (int c = 0; c < 4; ++c) acc2[si][c] = make_float2(0.f, 0.f);
      float run_max = -INFINITY;
      float run_sum = 0.f;
      int cpar = 0;
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci, cpar ^= 1) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = gc % NS;
        const unsigned phase = (gc / NS) & 1;
        ++gc;
        mbar_wait(&bar_f[slot], phase);
        uint4 qv[4][CH];
        float2 rms2[CH], dot2[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          rms2[r] = make_float2(0.f, 0.f);
          dot2[r] = make_float2(0.f, 0.f);
        }
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
            const int cidx = tile * 128 + tig;
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an)
                qv[si][r] = reinterpret_cast<const uint4*>(buf + ((size_t)slot * CH + r) * H)[cidx];
            }
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  rms2[r] = fma_x2(v[c], v[c], rms2[r]);
                  dot2[r] = fma_x2(v[c], cw2[si][c], dot2[r]);
                }
              }
            }
          }
        }
        mbar_arrive(&bar_e[slot]);
        // cross-warp score reduction (ascending-warp fold order)
        {
          float wr[CH], wd[CH];
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            float a = __fadd_rn(rms2[r].x, rms2[r].y);
            float b = __fadd_rn(dot2[r].x, dot2[r].y);
            a = lane_tree_sum(a);
            b = lane_tree_sum(b);
            if (lane == 0) {
              warp_rms[(cpar * 8 + warp) * CH + r] = a;
              warp_dot[(cpar * 8 + warp) * CH + r] = b;
            }
          }
          bar_cons_sync(1);
        }
        float logit_lane = 0.f;
        if (lane < an) {
          float tr = 0.f, td = 0.f;
#pragma unroll
          for (int w = 0; w < 8; ++w) {
            tr = __fadd_rn(tr, warp_rms[(cpar * 8 + w) * CH + lane]);
            td = __fadd_rn(td, warp_dot[(cpar * 8 + w) * CH + lane]);
          }
          logit_lane = __fmul_rn(td, rsqrtf(__fadd_rn(__fmul_rn(tr, INVH), eps)));
        }
        float lg[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) lg[r] = __shfl_sync(0xffffffffu, logit_lane, r);
        float chunk_max = -INFINITY;
#pragma unroll
        for (int r = 0; r < CH; ++r)
          if (r < an) chunk_max = fmaxf(chunk_max, lg[r]);
        const float new_max = fmaxf(run_max, chunk_max);
        const float corr = __expf(__fadd_rn(run_max, -new_max));
        float wgt[CH];
        float wsum = 0.f;
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          wgt[r] = (r < an) ? __expf(__fadd_rn(lg[r], -new_max)) : 0.f;
          wsum = __fadd_rn(wsum, wgt[r]);
        }
        run_sum = __fadd_rn(__fmul_rn(run_sum, corr), wsum);
        run_max = new_max;
        const float2 corr2 = make_float2(corr, corr);
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
                const float2 w2 = make_float2(wgt[r], wgt[r]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  acc2[si][c] = (r == 0) ? fma_x2(w2, v[c], mul_x2(acc2[si][c], corr2))
                                         : fma_x2(w2, v[c], acc2[si][c]);
                }
              }
            }
          }
        }
      }
      // ---- out-norm + epilogue (registers only) ---------------------
      const float invs = __frcp_rn(run_sum);
      const float2 inv2 = make_float2(invs, invs);
      float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            acc2[si][c] = mul_x2(acc2[si][c], inv2);
            sq2 = fma_x2(acc2[si][c], acc2[si][c], sq2);
          }
        }
      }
      float sq = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
      const int tpar = ((t - blockIdx.x) / gridDim.x) & 1;
      if (lane == 0) warp_ssq[tpar * 8 + warp] = sq;
      bar_cons_sync(2);
      float tot = 0.f;
#pragma unroll
      for (int w = 0; w < 8; ++w) tot = __fadd_rn(tot, warp_ssq[tpar * 8 + w]);
      const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
      const float2 orr2 = make_float2(orr, orr);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
          uint4 o4;
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            __nv_bfloat162 b;
            if (ASYM) {
              b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), ow2[si][c]));
            } else {
              // 288-thread variant: ow comes from gmem/L2.
              uint4 oq = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
              float2 o0, o1;
              cvt4_f2(make_uint2((c < 2) ? oq.x : oq.z, (c < 2) ? oq.y : oq.w), o0, o1);
              const float2 os = (c & 1) ? o1 : o0;
              b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), os));
            }
            reinterpret_cast<unsigned*>(&o4)[c] = *reinterpret_cast<unsigned*>(&b);
          }
          reinterpret_cast<uint4*>(out + (long long)t * H)[tile * 128 + tig] = o4;
        }
      }
    }
  }
  pdl_launch_dependents();
}
// R61/impl104: force device-side emission of the nvb=4 production
// instantiation so a host function pointer can be formed in forward_fast5.
template __global__ void chp_kernel<4, 5, 1, 200>(const bf16*, const bf16*, const bf16*,
                                                  const bf16*, bf16*, int, long long, float);

// ------------------------------------------------------------------- chpg ---
// development (tuning, level2 shape-adaptive dispatch): STATIC
// CTA-per-token clone of the chp production family (impl136) — the missing
// CTA-per-token half of the bounded NSRC specialization family for the
// currently-unspecialized NVB values 3/5/6/7 (NSRC 4/6/7/8), completing the
// NSRC=2..9 pair (static CTA-per-token small-T variant + persistent
// grid-stride large-T variant) required by the level-2 contract:
//   NSRC=2  leanF<2> static / chtm<1,2,2,0> persistent      (R46-56)
//   NSRC=3  leanS3<3> static (in-tree, falsified vs chp3) / chp3 persistent
//   NSRC=4  chpg<3,4,1,200> static (THIS ROUND) / chp<3,4,1,200> persistent
//   NSRC=5  chtgd<4,5,1,200> static / chtm<4,5,1,200> persistent (R95/100)
//   NSRC=6  chpg<5,3,1,200> static (THIS ROUND) / chp<5,3,1,200> persistent
//   NSRC=7  chpg<6,4,1,200> static (THIS ROUND) / chp<6,4,1,200> persistent
//   NSRC=8  chpg<7,4,1,200> static (THIS ROUND) / chp<7,4,1,200> persistent
//   NSRC=9  pdlr<8> static / chtm<8,..>/chtmd persistent    (R78/102)
// The body is chp_kernel with the persistent grid-stride token loop replaced
// by `token = blockIdx.x` (grid = T, one CTA per token) — the exact chtg
// transformation of R95 applied to the TMEM-free chp dataflow. FP32 fold
// order, chunk geometry (NCH <= 2 for every instantiation below, so each
// NS=2 ring slot is touched at most once and the producer never waits on
// bar_e), PDL hooks, cw/ow register staging, launch bounds and smem layout
// are unchanged: outputs are BIT-IDENTICAL to the persistent chp production
// route by construction (R104: 148/148 bitwise-identical cases, nvb 3/5/6/7
// x T 1..1024 incl. wave straddles). Dimension-only per-NVB bands were
// measured this round at the one-CTA-wave boundary (r104_ab.py; see the
// chpg_band() comment for the full evidence table); dispatch plumbs through
// the same three mirrors
// (C++ K3Plan band + forward_preres arm + python closure/generic ladders).
template <int NVB, int NVBC, int NOCC, int NCREGS>
__global__ __launch_bounds__((NCREGS > 0) ? 384 : 288, NOCC) void chpg_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int CH = NVBC;
  constexpr int NCH = (R + CH - 1) / CH;
  constexpr int NS = 2;
  constexpr bool ASYM = (NCREGS > 0);
  static_assert(NCH <= 2 * NS, "chpg static ring sizes assume NCH <= 2*NS chunks");
  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  const int t = blockIdx.x;  // static: one token per CTA, grid = T
  (void)T;
  extern __shared__ char dyn[];
  bf16* buf = reinterpret_cast<bf16*>(dyn);  // [NS][CH][H]
  unsigned long long* bar_f = reinterpret_cast<unsigned long long*>(dyn + (size_t)NS * CH * ROWB);
  unsigned long long* bar_e = bar_f + NS;
  float* warp_rms = reinterpret_cast<float*>(bar_e + NS);  // [2][8][CH]
  float* warp_dot = warp_rms + 2 * 8 * CH;                 // [2][8][CH]
  float* warp_ssq = warp_dot + 2 * 8 * CH;                 // [2][8]

  pdl_wait();
  if (tx == 0) {
#pragma unroll
    for (int s = 0; s < NS; ++s) {
      mbar_init(&bar_f[s], 1);
      mbar_init(&bar_e[s], 256);
    }
  }
  fence_mbar_init();
  __syncthreads();

  if (warp >= 8) {
    // ---- producer: one token's chunks, identical ring discipline ------
    if (ASYM) setmaxnreg_dec_w<40>();
    if (warp == 8 && lane == 0) {
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = (unsigned)ci % NS;
        const unsigned phase = ((unsigned)ci / NS) & 1;
        if (ci >= NS) mbar_wait(&bar_e[slot], phase ^ 1);
        mbar_arrive_expect_tx(&bar_f[slot], (unsigned)(an * ROWB));
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          if (r < an) {
            const int row = base + r;
            const bf16* src = (row < NVB) ? bank + (long long)t * stride_bm + (long long)row * H
                                          : prefix + (long long)t * H;
            cp_bulk_g2s(buf + ((size_t)slot * CH + r) * H, src, (unsigned)ROWB, &bar_f[slot]);
          }
        }
      }
    }
  } else {
    // ---- consumers: single-token chunk-local online softmax/mixture ---
    if constexpr (ASYM) setmaxnreg_inc_w<NCREGS>();
    const int group = warp >> 2;  // 0/1: interleaved 1024-elem tiles
    const int tig = tx & 127;
    const float LOG2E = 1.4426950408889634f;
    (void)LOG2E;
    // register-resident fp32 cw/ow slices (chp: constant across tokens;
    // here: constant for this token), identical tile/cvt order to chp.
    float2 cw2[4][4], ow2[4][4];
#pragma unroll
    for (int si = 0; si < 4; ++si) {
      const int tile = si * 2 + group;
      if (tile < 7) {
        uint4 q = reinterpret_cast<const uint4*>(cw + (tile * 128 + tig) * 8)[0];
        cvt4_f2(make_uint2(q.x, q.y), cw2[si][0], cw2[si][1]);
        cvt4_f2(make_uint2(q.z, q.w), cw2[si][2], cw2[si][3]);
        if (ASYM) {
          q = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
          cvt4_f2(make_uint2(q.x, q.y), ow2[si][0], ow2[si][1]);
          cvt4_f2(make_uint2(q.z, q.w), ow2[si][2], ow2[si][3]);
        }
      }
    }
    {
      float2 acc2[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si)
#pragma unroll
        for (int c = 0; c < 4; ++c) acc2[si][c] = make_float2(0.f, 0.f);
      float run_max = -INFINITY;
      float run_sum = 0.f;
      int cpar = 0;
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci, cpar ^= 1) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = (unsigned)ci % NS;
        const unsigned phase = ((unsigned)ci / NS) & 1;
        mbar_wait(&bar_f[slot], phase);
        uint4 qv[4][CH];
        float2 rms2[CH], dot2[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          rms2[r] = make_float2(0.f, 0.f);
          dot2[r] = make_float2(0.f, 0.f);
        }
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
            const int cidx = tile * 128 + tig;
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an)
                qv[si][r] = reinterpret_cast<const uint4*>(buf + ((size_t)slot * CH + r) * H)[cidx];
            }
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  rms2[r] = fma_x2(v[c], v[c], rms2[r]);
                  dot2[r] = fma_x2(v[c], cw2[si][c], dot2[r]);
                }
              }
            }
          }
        }
        mbar_arrive(&bar_e[slot]);
        // cross-warp score reduction (ascending-warp fold order)
        {
          float wr[CH], wd[CH];
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            float a = __fadd_rn(rms2[r].x, rms2[r].y);
            float b = __fadd_rn(dot2[r].x, dot2[r].y);
            a = lane_tree_sum(a);
            b = lane_tree_sum(b);
            if (lane == 0) {
              warp_rms[(cpar * 8 + warp) * CH + r] = a;
              warp_dot[(cpar * 8 + warp) * CH + r] = b;
            }
          }
          bar_cons_sync(1);
        }
        float logit_lane = 0.f;
        if (lane < an) {
          float tr = 0.f, td = 0.f;
#pragma unroll
          for (int w = 0; w < 8; ++w) {
            tr = __fadd_rn(tr, warp_rms[(cpar * 8 + w) * CH + lane]);
            td = __fadd_rn(td, warp_dot[(cpar * 8 + w) * CH + lane]);
          }
          logit_lane = __fmul_rn(td, rsqrtf(__fadd_rn(__fmul_rn(tr, INVH), eps)));
        }
        float lg[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) lg[r] = __shfl_sync(0xffffffffu, logit_lane, r);
        float chunk_max = -INFINITY;
#pragma unroll
        for (int r = 0; r < CH; ++r)
          if (r < an) chunk_max = fmaxf(chunk_max, lg[r]);
        const float new_max = fmaxf(run_max, chunk_max);
        const float corr = __expf(__fadd_rn(run_max, -new_max));
        float wgt[CH];
        float wsum = 0.f;
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          wgt[r] = (r < an) ? __expf(__fadd_rn(lg[r], -new_max)) : 0.f;
          wsum = __fadd_rn(wsum, wgt[r]);
        }
        run_sum = __fadd_rn(__fmul_rn(run_sum, corr), wsum);
        run_max = new_max;
        const float2 corr2 = make_float2(corr, corr);
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
                const float2 w2 = make_float2(wgt[r], wgt[r]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  acc2[si][c] = (r == 0) ? fma_x2(w2, v[c], mul_x2(acc2[si][c], corr2))
                                         : fma_x2(w2, v[c], acc2[si][c]);
                }
              }
            }
          }
        }
      }
      // ---- out-norm + epilogue (registers only) ---------------------
      const float invs = __frcp_rn(run_sum);
      const float2 inv2 = make_float2(invs, invs);
      float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            acc2[si][c] = mul_x2(acc2[si][c], inv2);
            sq2 = fma_x2(acc2[si][c], acc2[si][c], sq2);
          }
        }
      }
      float sq = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
      if (lane == 0) warp_ssq[0 * 8 + warp] = sq;  // tpar == 0
      bar_cons_sync(2);
      float tot = 0.f;
#pragma unroll
      for (int w = 0; w < 8; ++w) tot = __fadd_rn(tot, warp_ssq[0 * 8 + w]);
      const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
      const float2 orr2 = make_float2(orr, orr);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
          uint4 o4;
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            __nv_bfloat162 b;
            if (ASYM) {
              b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), ow2[si][c]));
            } else {
              uint4 oq = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
              float2 o0, o1;
              cvt4_f2(make_uint2((c < 2) ? oq.x : oq.z, (c < 2) ? oq.y : oq.w), o0, o1);
              const float2 os = (c & 1) ? o1 : o0;
              b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), os));
            }
            reinterpret_cast<unsigned*>(&o4)[c] = *reinterpret_cast<unsigned*>(&b);
          }
          reinterpret_cast<uint4*>(out + (long long)t * H)[tile * 128 + tig] = o4;
        }
      }
    }
  }
  pdl_launch_dependents();
}
// R104: bounded instantiation set — force device-side emission of the four
// chpg static specializations (nsrc 4/6/7/8) so host function pointers can
// be formed for the preres route table (R62 lazy-instantiation lesson).
template __global__ void chpg_kernel<3, 4, 1, 200>(const bf16*, const bf16*, const bf16*,
                                                   const bf16*, bf16*, int, long long, float);
template __global__ void chpg_kernel<5, 3, 1, 200>(const bf16*, const bf16*, const bf16*,
                                                   const bf16*, bf16*, int, long long, float);
template __global__ void chpg_kernel<6, 4, 1, 200>(const bf16*, const bf16*, const bf16*,
                                                   const bf16*, bf16*, int, long long, float);
template __global__ void chpg_kernel<7, 4, 1, 200>(const bf16*, const bf16*, const bf16*,
                                                   const bf16*, bf16*, int, long long, float);

// ------------------------------------------------------------------- lean5 ---
// development tuning (opt-in via K3_IMPL=117, NVB==4 only):
// lean5_kernel<NT> — a lean NSRC=5 CTA-per-token variant for the launch-
// limited NVB=4 small-T band (T<=32) and its straddles. Stripped of every
// piece of cross-thread choreography beyond the two reduction rounds the
// math requires: NO TMA producer warp, NO mbarrier ring, NO setmaxnreg,
// NO named barriers. A flat NT-thread block (all warps identical) does:
//   phase A: cooperative 16B-vectorized stage of all five rows into smem
//            while accumulating FP32 rms/dot partials (packed f32x2) with
//            the cw slice of each tile loaded once and reused across rows;
//   development: lane_tree_sum per row -> smem warp partials -> ONE
//            __syncthreads -> every thread redundantly folds the NW warp
//            partials (smem broadcast reads, deterministic identical
//            order) and computes the full softmax weights in registers;
//   phase B: mixture out of smem (replicated weights), FP32 output-RMS
//            partial from the register accumulators;
//   development: lane_tree_sum -> ONE __syncthreads -> replicated fold ->
//            orr -> bf16 epilogue with ow from gmem/L1.
// Exactly two block barriers per token, PDL pre/post hooks retained,
// grid = T (one CTA per token; the band underfills the GPU by design).
// NT in {256, 512, 1024} is the directed block-size sweep (K3_LT5_NT).
// STAGE=false (impl118): skip the phase-A STS entirely and let phase B
// re-read the rows straight from L1/L2 (at grid<=32 CTAs each SM holds
// its own 70KB token span hot in L1 after phase A) — removes 20 STS.128
// per thread from the phase-A critical path at the cost of re-issued
// LDGs that should all hit L1.

// R84: force device-side emission of the sweep instantiations.

// ------------------------------------------------------------------- chpw ---
// impl 107 (development tuning): NEW T=64/NVB=8-specialized
// CTA-per-token geometry, distinct from every falsified axis (not two-token,
// not cluster/DSMEM, not occupancy-2, not ring depth/width, not reduction-
// chain variants, not direct-gmem leanF — rows are still TMA-staged).
//
// R68 NCU on impl85 at T=64 NVB=8 ($VIBECUDA_LOCAL_SCRATCH_DIR/
// ncu_r68_t64_85.ncu-rep, 3-launch full set): 8.74us, 0.42 waves,
// DRAM ~8%, issue 27.7%; stalls per issued inst: long_scoreboard 2.04 +
// short_scoreboard 1.83 (=47%), wait 1.09, barrier only 0.48. The T=64
// single-token-per-CTA latency chain is memory-latency-exposed at 12
// warps/CTA; the per-chunk fold barriers draw only 6%. Attack surface:
// (1) double resident warps (16 consumer warps) and split the score phase
//     ROW-WISE across two independent 8-warp halves running in parallel —
//     halves the serial rms/dot chain and replaces 2 chunk-fold barriers
//     with 1 probs barrier (2 chunk online-softmax collapses to a single
//     max-subtracted softmax once all 9 logits are known);
// (2) single-shot TMA slab (one 129KB mbar transaction for all 9 rows) —
//     removes the chunk1 wait from the critical path;
// (3) mixture keeps the row split (each half accumulates its own rows,
//     18-20 slice loads vs 36 in chp, no qv register spill at 112-reg
//     budget) then exchanges the 32KB half-sums through smem once; group A
//     combines, does the out-RMS fold, and stores — the epilogue is chp's
//     exact 8-warp structure.
// Arithmetic class: everything FP32; per-row rrms = rsqrt(mean+eps);
// logit = dot*rrms (scalar per row, identical formula to chp); single
// max-subtracted softmax over the 9 rows; mixture sum order = rows 0..4
// ascending [+ rows 5..8 ascending as one term]; out = mixed*rsqrt(mean+eps)*ow.
// Not bit-identical to impl85 (different reduction order for the mixture
// and a single-phase softmax), same FP32 tolerance class.
//
// Named barriers (per token): 1 = GA(256) score fold, 2 = GB(256) score
// fold (parallel with 1), 3 = all-512 probs barrier, 6 = all-512 acc
// exchange, 4 = all-512 out-RMS fold. Producer warp 16 only touches
// mbarriers. mbar bar_fa/bar_fb (development split): 1 arrive + 5*ROWB /
// 4*ROWB expect_tx per token — GA/GB score as soon as THEIR rows land,
// overlapping the other half's TMA (kills the single-shot slab's exposed
// ~2.7us cold-L2 wait). bar_e: 512 arrivals per token, gates the
// producer's next-token slab overwrite (also orders the acc_x single
// buffer: no consumer can pass bar_f*(t+1) before bar_e(t) completes,
// i.e. after ALL post-exchange arrivals).
//
// development deadlock root cause (racecheck-confirmed at T=1, warp 9 wedged
// at bar.sync 2 / PC 0x33c0): the R68 launch used 576 threads = 18 warps,
// but the branch was `if (warp == 16) producer else consumer`, so warp 17
// fell into the CONSUMER path as an unintended 17th consumer warp. It
// arrived at the 256-count fold bars (9-warp completion), the 512-count
// bars (17-warp completion) and bar_e (544 arrivals/phase), corrupting
// every barrier's phase accounting; it also wrote part_rms[17*NA+jr]
// (alias of part_dot[1..]) and warp_ssq[17] (alias of acc_x). The fix is
// a 544-thread block (16 consumer warps + 1 producer warp) so no warp is
// left to stray into the wrong branch. The single-shot mbar/TMA handoff,
// the named-barrier IDs, and the single-buffered smem exchange were all
// sound as written in R68 — producer/consumer gating serializes every
// cross-token smem reuse, so no parity double-buffering is needed.

// ------------------------------------------------------------------ wpr8 ----
// impl 108 (development tuning, opt-in via K3_IMPL=108, NVB==8
// only): lean CTA-per-token candidate for the nvb=8 sub-wave band T=57..151.
// Retires the impl107 544-thread two-half geometry (64KB cross-half smem
// exchange + duplicate full-H epilogue): one 288-thread CTA per token, NINE
// warps == NINE rows in the score phase (row-per-warp; no smem row slab, no
// cross-half traffic, no producer warp, no TMA ring); cw staged once per CTA
// in smem so the 9 row-warps do not duplicate 9x cw L2 reads; ONE
// cross-thread softmax handoff (s_rms/s_dot) then every thread redundantly
// computes the same <=9-wide max-subtracted softmax; a column-parallel
// mixture re-reads the rows from L2 (the band is L2-resident after phase 1:
// 161KB/token, <=24MB at T=151 on a 126MB L2) keeping the mixed vector fully
// in registers; a register epilogue with disjoint per-thread 16B stores (no
// duplicate full-H work anywhere). 3 block barriers per token total (cw smem
// staging beats direct per-warp L2 cw reads — measured v2 loss 2-9%). FP32
// accumulation everywhere; packed f32x2 arithmetic is bit-exact to the
// scalar rn sequence chp uses; bf16 widening via bit ops. Row order matches
// the contract: rows 0..7 = bank[:, :8, :], row 8 = appended prefix row.
__global__ __launch_bounds__(288, 1) void wpr8_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = 9;       // nvb==8 bank rows + appended prefix
  constexpr int U4 = H / 8;  // 896 uint4 chunks per row
  constexpr int NT = 288;
  __shared__ alignas(16) bf16 s_cw[H];
  __shared__ float s_rms[R];
  __shared__ float s_dot[R];
  __shared__ float s_osq[R];

  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  const int t = blockIdx.x;

  pdl_wait();

  // ---- stage cw once per CTA (each element loaded exactly once; the 9
  // row-warps then read their cw slices from smem instead of duplicating
  // 9x L2 reads — v2 experiment without the stage lost 2-9% at 64..128) --
  {
    const uint4* c4 = reinterpret_cast<const uint4*>(cw);
    uint4* s4 = reinterpret_cast<uint4*>(s_cw);
#pragma unroll
    for (int i = 0; i < 4; ++i) {
      const int c = tx + i * NT;
      if (i < 3 || tx < 32) s4[c] = __ldg(c4 + c);
    }
  }
  __syncthreads();  // barrier #1: cw visible to all warps

  // ---- phase 1: warp w owns row w; per-row FP32 sq + dot ----------------
  // lane covers chunks 64k+2*lane and +1 via 32B loads (14 iters,
  // perfectly coalesced 1KB/warp/iter). Rows are read exactly once from
  // global here (DRAM-fill or L2), once more from L2 in the mixture.
  {
    const bf16* row = (warp < 8) ? bank + (long long)t * stride_bm + (long long)warp * H
                                 : prefix + (long long)t * H;
    const uint4* r4 = reinterpret_cast<const uint4*>(row);
    const uint4* c4 = reinterpret_cast<const uint4*>(s_cw);
    float2 sq[4], dt[4];
#pragma unroll
    for (int c = 0; c < 4; ++c) {
      sq[c] = make_float2(0.f, 0.f);
      dt[c] = make_float2(0.f, 0.f);
    }
#pragma unroll
    for (int k = 0; k < 14; ++k) {
      const int c = 64 * k + 2 * lane;
      uint4 qa, qb;
      ldg256(r4 + c, qa, qb);
      uint4 ca = c4[c];
      uint4 cb = c4[c + 1];
      float2 v[4], kv[4];
      cvt4_f2(make_uint2(qa.x, qa.y), v[0], v[1]);
      cvt4_f2(make_uint2(qa.z, qa.w), v[2], v[3]);
      cvt4_f2(make_uint2(ca.x, ca.y), kv[0], kv[1]);
      cvt4_f2(make_uint2(ca.z, ca.w), kv[2], kv[3]);
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        sq[c2] = fma_x2(v[c2], v[c2], sq[c2]);
        dt[c2] = fma_x2(v[c2], kv[c2], dt[c2]);
      }
      cvt4_f2(make_uint2(qb.x, qb.y), v[0], v[1]);
      cvt4_f2(make_uint2(qb.z, qb.w), v[2], v[3]);
      cvt4_f2(make_uint2(cb.x, cb.y), kv[0], kv[1]);
      cvt4_f2(make_uint2(cb.z, cb.w), kv[2], kv[3]);
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        sq[c2] = fma_x2(v[c2], v[c2], sq[c2]);
        dt[c2] = fma_x2(v[c2], kv[c2], dt[c2]);
      }
    }
    float a = __fadd_rn(sq[0].x, sq[0].y);
    float b = __fadd_rn(dt[0].x, dt[0].y);
#pragma unroll
    for (int c2 = 1; c2 < 4; ++c2) {
      a = __fadd_rn(a, __fadd_rn(sq[c2].x, sq[c2].y));
      b = __fadd_rn(b, __fadd_rn(dt[c2].x, dt[c2].y));
    }
    a = lane_tree_sum(a);
    b = lane_tree_sum(b);
    if (lane == 0) {
      s_rms[warp] = a;
      s_dot[warp] = b;
    }
  }
  __syncthreads();  // barrier #2: row sums visible to all threads

  // ---- softmax: identical redundant computation in every thread ---------
  float w[R];
  float lg[R];
  float mx = -INFINITY;
#pragma unroll
  for (int j = 0; j < R; ++j) {
    lg[j] = __fmul_rn(s_dot[j], rsqrtf(__fadd_rn(__fmul_rn(s_rms[j], INVH), eps)));
    mx = fmaxf(mx, lg[j]);
  }
  float wsum = 0.f;
#pragma unroll
  for (int j = 0; j < R; ++j) {
    w[j] = __expf(__fadd_rn(lg[j], -mx));
    wsum = __fadd_rn(wsum, w[j]);
  }
  const float invs = __frcp_rn(wsum);
  const float2 inv2 = make_float2(invs, invs);

  // ---- phase 2: column-parallel weighted mixture (rows from L2) ---------
  // thread tx owns chunks tx + i*NT (i = 0..2 always, i = 3 when tx < 32);
  // lanes are consecutive chunks -> coalesced 512B/warp per row load.
  const uint4* rowp[R];
#pragma unroll
  for (int j = 0; j < R; ++j)
    rowp[j] = reinterpret_cast<const uint4*>(
        (j < 8) ? bank + (long long)t * stride_bm + (long long)j * H : prefix + (long long)t * H);
  float2 mix[4][4];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int c2 = 0; c2 < 4; ++c2) mix[i][c2] = make_float2(0.f, 0.f);
  const float2 w2[R] = {make_float2(w[0], w[0]), make_float2(w[1], w[1]), make_float2(w[2], w[2]),
                        make_float2(w[3], w[3]), make_float2(w[4], w[4]), make_float2(w[5], w[5]),
                        make_float2(w[6], w[6]), make_float2(w[7], w[7]), make_float2(w[8], w[8])};
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 32) {
#pragma unroll
      for (int j = 0; j < R; ++j) {
        uint4 q = __ldg(rowp[j] + c);
        float2 v[4];
        cvt4_f2(make_uint2(q.x, q.y), v[0], v[1]);
        cvt4_f2(make_uint2(q.z, q.w), v[2], v[3]);
#pragma unroll
        for (int c2 = 0; c2 < 4; ++c2) mix[i][c2] = fma_x2(w2[j], v[c2], mix[i][c2]);
      }
    }
  }

  // ---- out-norm: deferred 1/sum, FP32 rowwise sq fold, 1 barrier --------
  float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    if (i < 3 || tx < 32) {
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        mix[i][c2] = mul_x2(mix[i][c2], inv2);
        sq2 = fma_x2(mix[i][c2], mix[i][c2], sq2);
      }
    }
  }
  float tot = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
  if (lane == 0) s_osq[warp] = tot;
  __syncthreads();  // barrier #3
  tot = 0.f;
#pragma unroll
  for (int j = 0; j < R; ++j) tot = __fadd_rn(tot, s_osq[j]);
  const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
  const float2 orr2 = make_float2(orr, orr);

  // ---- epilogue: disjoint per-thread 16B stores --------------------------
  const uint4* o4 = reinterpret_cast<const uint4*>(ow);
  uint4* dst = reinterpret_cast<uint4*>(out + (long long)t * H);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 32) {
      uint4 oq = __ldg(o4 + c);
      float2 o01, o23, o45, o67;
      cvt4_f2(make_uint2(oq.x, oq.y), o01, o23);
      cvt4_f2(make_uint2(oq.z, oq.w), o45, o67);
      uint4 ores;
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        const float2 os = (c2 == 0) ? o01 : (c2 == 1) ? o23 : (c2 == 2) ? o45 : o67;
        __nv_bfloat162 bb = __float22bfloat162_rn(mul_x2(mul_x2(mix[i][c2], orr2), os));
        reinterpret_cast<unsigned*>(&ores)[c2] = *reinterpret_cast<unsigned*>(&bb);
      }
      dst[c] = ores;
    }
  }
  pdl_launch_dependents();
}

// ------------------------------------------------------------------ wpr8s ---
// impl 110 (development candidate, opt-in via K3_IMPL=110, NVB==8 only): bit-
// identical clone of wpr8 (impl108) with an XOR-swizzled s_cw layout. NCU
// (R70, T=64 full set) measured 6.6-way shared-load bank conflicts on the
// score phase's 32B-pair cw reads (64,512 conflicts = 47.06% excess
// wavefronts on 20,736 shared-load requests): lane l reads chunks 64k+2l
// and 64k+2l+1, so slot mod 8 cycles every 4 lanes. Storing chunk c at slot
//   swz(c) = c ^ ((c >> 1) & 7)
// makes both 16B reads hit all 8 bank-groups per 8-lane phase (bijection on
// slot mod 8 for c = 64k+2l over l = 0..7 and for c+1), and the consecutive-
// chunk stage stores stay conflict-free as well. Everything else — threads,
// phase structure, barriers, arithmetic order — is byte-identical to impl108.
__device__ __forceinline__ int cw_swz(int c) { return c ^ ((c >> 1) & 7); }

// ------------------------------------------------------------------ wpr8w ---
// impl 109 (development, opt-in via K3_IMPL=109, NVB==8 only): widened wpr8 —
// 576 threads = 18 warps; warp w owns HALF of row (w >> 1), hf = w & 1, so
// the DRAM/L2 latency phases have 2x the warps per scheduler vs wpr8 at the
// 43%-SM sub-wave band. No smem exchange, no producer, disjoint stores; both
// global row loads AND smem cw reads use the stride-1 uint4 chunk mapping
// (c = 32*j + lane) which is bank-conflict-free for smem (the wpr8 32B-pair
// mapping measured 6.6-way shared-load conflicts, 47% excess wavefronts).

// ------------------------------------------------------------------ s100r ---
// impl 103 (development tuning, opt-in via K3_IMPL=103, NVB==8
// only): one clean fused kernel modeled conceptually on the production SM100
// schedule (bounded template/config surface): 288 threads = 8 consumer warps
// in 2 groups (interleaved 1024-elem tiles, each thread owns one 16B slice
// per owned tile) + 1 producer warp; NS=2 double-buffered cp.async.bulk bulk
// row staging behind an explicit mbarrier full/free pair per chunk; chunk
// stays register-resident from the score pass into the online-softmax fold
// (packed fma.f32x2 accumulator, exp2f softmax); cw/out_weight staged in
// TMEM (tcgen05), drained per chunk / per token; the out-norm scale folds
// 1/run_sum so the epilogue is 2 muls + 1 bf16 pack + one 16B store per
// element. Chunking = development best CH=3 (NCH=3) with K3_S100R_CH=4/5 as
// bounded A/B arms. NOT dispatched; dispatcher placement requires the
// ordering-reversed cold-L2 A/B rule (beats impl87 at T=128 and T=512, no
// T=4096 regression).

// ------------------------------------------------------------------ pdlr ----
// impl 112 (development tuning, opt-in via K3_IMPL=112, NVB in
// {4,8}): lean CTA-per-token variant for the failing T=16..128 band,
// templated on NSRC = NVB+1 (R in {5,9}) so per-chunk source counts and
// prefix tests are compile-time. Geometry is the impl108 wpr8 dataflow
// (row-per-warp score phase, smem-staged cw, L2-resident mixture re-read,
// register epilogue, 3 block barriers, FP32 accumulation everywhere) with
// the PDL trigger moved from kernel END to immediately after the CTA's last
// global READS are issued (mixture remainder chunks + the ow chunk): with
// ProgrammaticStreamSerialization the next forward invocation's grid
// launches while this one is still in its consume/out-RMS/store tail,
// overlapping iteration i+1's launch+load phase with iteration i's tail.
// Soundness: pdl_wait() still heads the kernel, so a dependent CTA never
// observes this CTA's stores before its own griddepcontrol.wait releases;
// the pre-trigger implicit flush covers only prior WRITES (this CTA has
// none before the trigger), and the bench chain's only cross-invocation
// alias (WAW on the reused out buffer) is value-identical. Arithmetic is
// bit-identical to wpr8 at NVB==8 (identical FFMA order per thread); the
// early trigger is a pure scheduling hint.
// The early trigger carries a "memory" clobber so nvcc keeps every issued
// global load program-ordered before it (the existing clobber-free helper
// stays for the end-of-kernel call sites).
__device__ __forceinline__ void pdl_launch_dependents_after_reads() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
  asm volatile("griddepcontrol.launch_dependents;" ::: "memory");
#endif
}

template <int NVB>
__global__ __launch_bounds__(288, 1) void pdlr_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;  // bank rows + appended prefix row
  constexpr int NT = 288;
  __shared__ alignas(16) bf16 s_cw[H];
  __shared__ float s_rms[R];
  __shared__ float s_dot[R];
  __shared__ float s_osq[NT / 32];

  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  const int t = blockIdx.x;

  pdl_wait();

  // ---- stage cw once per CTA (identical to wpr8) ---------------------
  {
    const uint4* c4 = reinterpret_cast<const uint4*>(cw);
    uint4* s4 = reinterpret_cast<uint4*>(s_cw);
#pragma unroll
    for (int i = 0; i < 4; ++i) {
      const int c = tx + i * NT;
      if (i < 3 || tx < 32) s4[c] = __ldg(c4 + c);
    }
  }
  __syncthreads();  // barrier #1: cw visible to all warps

  // ---- phase 1: warp w owns row w (warps >= R idle); per-row FP32
  // sq + dot against smem cw. Rows are read exactly once from global
  // here (DRAM-fill or L2), once more from L2 in the mixture. ---------
  if (warp < R) {
    const bf16* row = (warp < NVB) ? bank + (long long)t * stride_bm + (long long)warp * H
                                   : prefix + (long long)t * H;
    const uint4* r4 = reinterpret_cast<const uint4*>(row);
    const uint4* c4 = reinterpret_cast<const uint4*>(s_cw);
    float2 sq[4], dt[4];
#pragma unroll
    for (int c = 0; c < 4; ++c) {
      sq[c] = make_float2(0.f, 0.f);
      dt[c] = make_float2(0.f, 0.f);
    }
#pragma unroll
    for (int k = 0; k < 14; ++k) {
      const int c = 64 * k + 2 * lane;
      uint4 qa, qb;
      ldg256(r4 + c, qa, qb);
      uint4 ca = c4[c];
      uint4 cb = c4[c + 1];
      float2 v[4], kv[4];
      cvt4_f2(make_uint2(qa.x, qa.y), v[0], v[1]);
      cvt4_f2(make_uint2(qa.z, qa.w), v[2], v[3]);
      cvt4_f2(make_uint2(ca.x, ca.y), kv[0], kv[1]);
      cvt4_f2(make_uint2(ca.z, ca.w), kv[2], kv[3]);
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        sq[c2] = fma_x2(v[c2], v[c2], sq[c2]);
        dt[c2] = fma_x2(v[c2], kv[c2], dt[c2]);
      }
      cvt4_f2(make_uint2(qb.x, qb.y), v[0], v[1]);
      cvt4_f2(make_uint2(qb.z, qb.w), v[2], v[3]);
      cvt4_f2(make_uint2(cb.x, cb.y), kv[0], kv[1]);
      cvt4_f2(make_uint2(cb.z, cb.w), kv[2], kv[3]);
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        sq[c2] = fma_x2(v[c2], v[c2], sq[c2]);
        dt[c2] = fma_x2(v[c2], kv[c2], dt[c2]);
      }
    }
    float a = __fadd_rn(sq[0].x, sq[0].y);
    float b = __fadd_rn(dt[0].x, dt[0].y);
#pragma unroll
    for (int c2 = 1; c2 < 4; ++c2) {
      a = __fadd_rn(a, __fadd_rn(sq[c2].x, sq[c2].y));
      b = __fadd_rn(b, __fadd_rn(dt[c2].x, dt[c2].y));
    }
    a = lane_tree_sum(a);
    b = lane_tree_sum(b);
    if (lane == 0) {
      s_rms[warp] = a;
      s_dot[warp] = b;
    }
  }
  __syncthreads();  // barrier #2: row sums visible to all threads

  // ---- softmax: identical redundant computation in every thread ------
  float w[R];
  float lg[R];
  float mx = -INFINITY;
#pragma unroll
  for (int j = 0; j < R; ++j) {
    lg[j] = __fmul_rn(s_dot[j], rsqrtf(__fadd_rn(__fmul_rn(s_rms[j], INVH), eps)));
    mx = fmaxf(mx, lg[j]);
  }
  float wsum = 0.f;
#pragma unroll
  for (int j = 0; j < R; ++j) {
    w[j] = __expf(__fadd_rn(lg[j], -mx));
    wsum = __fadd_rn(wsum, w[j]);
  }
  const float invs = __frcp_rn(wsum);
  const float2 inv2 = make_float2(invs, invs);

  // ---- phase 2: column-parallel weighted mixture (rows from L2) ------
  // thread tx owns chunks tx + i*NT (i = 0..2 always, i = 3 when
  // tx < 32); lanes are consecutive chunks -> coalesced 512B/warp per
  // row load. The ow chunk is loaded alongside the row chunks so the
  // epilogue issues no further global reads. The PDL trigger fires in
  // the final iteration IMMEDIATELY after the last loads are issued.
  const uint4* rowp[R];
#pragma unroll
  for (int j = 0; j < R; ++j)
    rowp[j] = reinterpret_cast<const uint4*>(
        (j < NVB) ? bank + (long long)t * stride_bm + (long long)j * H : prefix + (long long)t * H);
  const uint4* o4 = reinterpret_cast<const uint4*>(ow);
  float2 mix[4][4];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int c2 = 0; c2 < 4; ++c2) mix[i][c2] = make_float2(0.f, 0.f);
  float2 w2[R];
#pragma unroll
  for (int j = 0; j < R; ++j) w2[j] = make_float2(w[j], w[j]);
  uint4 oq[4];
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 32) {
      uint4 q[R];
#pragma unroll
      for (int j = 0; j < R; ++j) q[j] = __ldg(rowp[j] + c);
      oq[i] = __ldg(o4 + c);
      if (i == 3) {
        // every global read this CTA needs has now been issued
        // (memory clobber keeps the loads ordered before the
        // trigger) — release the next forward invocation's grid
        // while this CTA still consumes/reduces/stores.
        pdl_launch_dependents_after_reads();
      }
#pragma unroll
      for (int j = 0; j < R; ++j) {
        float2 v[4];
        cvt4_f2(make_uint2(q[j].x, q[j].y), v[0], v[1]);
        cvt4_f2(make_uint2(q[j].z, q[j].w), v[2], v[3]);
#pragma unroll
        for (int c2 = 0; c2 < 4; ++c2) mix[i][c2] = fma_x2(w2[j], v[c2], mix[i][c2]);
      }
    } else if (i == 3) {
      // compile-time-resolved companion branch (tx >= 32 threads
      // have issued their last loads in iteration 2): uniform
      // per-CTA trigger with no intra-warp divergence.
      pdl_launch_dependents_after_reads();
    }
  }

  // ---- out-norm: deferred 1/sum, FP32 rowwise sq fold, 1 barrier ------
  float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    if (i < 3 || tx < 32) {
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        mix[i][c2] = mul_x2(mix[i][c2], inv2);
        sq2 = fma_x2(mix[i][c2], mix[i][c2], sq2);
      }
    }
  }
  float tot = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
  if (lane == 0) s_osq[warp] = tot;
  __syncthreads();  // barrier #3
  tot = 0.f;
#pragma unroll
  for (int j = 0; j < NT / 32; ++j) tot = __fadd_rn(tot, s_osq[j]);
  const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
  const float2 orr2 = make_float2(orr, orr);

  // ---- epilogue: disjoint per-thread 16B stores (ow already in regs) --
  uint4* dst = reinterpret_cast<uint4*>(out + (long long)t * H);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 32) {
      float2 o01, o23, o45, o67;
      cvt4_f2(make_uint2(oq[i].x, oq[i].y), o01, o23);
      cvt4_f2(make_uint2(oq[i].z, oq[i].w), o45, o67);
      uint4 ores;
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        const float2 os = (c2 == 0) ? o01 : (c2 == 1) ? o23 : (c2 == 2) ? o45 : o67;
        __nv_bfloat162 bb = __float22bfloat162_rn(mul_x2(mul_x2(mix[i][c2], orr2), os));
        reinterpret_cast<unsigned*>(&ores)[c2] = *reinterpret_cast<unsigned*>(&bb);
      }
      dst[c] = ores;
    }
  }
}

// ------------------------------------------------------------------ epdl ----
// impl 138 (development tuning, opt-in via forward_preres
// impl=138, NVB in {2,4}): lean one-CTA-per-token static variant (grid = T,
// token = blockIdx.x) with the PDL trigger moved to IMMEDIATELY AFTER ALL
// global reads are issued. The CTA's entire working set (R = NVB+1 row
// vectors + cw + ow) is staged into shared memory by (R+2) cp.async.bulk TMA
// copies; griddepcontrol.launch_dependents then fires BEFORE the mbarrier
// wait and before any reduction/softmax/mixture/epilogue work, so under
// ProgrammaticStreamSerialization the next forward invocation's grid
// launches while this CTA is still waiting on its TMA data and running the
// whole FP32 tail — maximum launch+load overlap for the launch-dominated
// small-T rows (failing T=4/NVB=2 and T=32/NVB=4 gate rows). The complete
// fused math is retained in ONE kernel launch: per-row FP32 sumsq + dot(cw),
// FP32 softmax with max subtraction, FP32 weighted mixture, FP32 out-RMS
// normalization, single BF16 store; no score/prob/mixed intermediates in
// global memory and every needed byte is read exactly once (single DRAM/L2
// pass per row). NSRC = NVB+1 is a template parameter so row loop bounds
// and the prefix-row test are compile-time.
// Soundness is identical to pdlr: pdl_wait() heads the kernel, the trigger
// carries a "memory" clobber (the cp.async.bulk issues stay program-ordered
// before it), and the pre-trigger implicit flush covers only prior WRITES —
// this CTA has none before the trigger, so the early release is a pure
// scheduling hint for the value-identical bench chain (each forward writes
// every output lane). Column mapping in both compute phases: thread tx owns
// 16B chunks c = tx + i*NT (i<3 all threads, i=3 when tx<128; 896 = 3.5*NT
// chunks over H), FP32 accumulation via the bit-reasonable fma_x2 folds,
// warp butterfly + fixed-order 8-warp smem fold per row (deterministic).
template <int NVB>
__global__ __launch_bounds__(256, 1) void epdl_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int NT = 256;
  extern __shared__ char dyn[];
  bf16* s_row = reinterpret_cast<bf16*>(dyn);  // [R][H]
  bf16* s_cw = s_row + R * H;                  // [H]
  bf16* s_ow = s_cw + H;                       // [H]
  unsigned long long* s_bar = reinterpret_cast<unsigned long long*>(s_ow + H);
  float* s_sq = reinterpret_cast<float*>(s_bar + 1);  // [8][R]
  float* s_dt = s_sq + 8 * R;                         // [8][R]
  float* s_osq = s_dt + 8 * R;                        // [8]

  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int t = blockIdx.x;

  pdl_wait();

  // ---- stage ALL reads via TMA bulk copies, then release the next grid --
  if (tx == 0) mbar_init(s_bar, 1);
  fence_mbar_init();
  __syncthreads();  // mbarrier init visible to the whole CTA
  if (tx == 0) {
    mbar_arrive_expect_tx(s_bar, (unsigned)((R + 2) * ROWB));
    const bf16* bp = bank + (long long)t * stride_bm;
#pragma unroll
    for (int j = 0; j < R; ++j) {
      const bf16* src = (j < NVB) ? bp + (long long)j * H : prefix + (long long)t * H;
      cp_bulk_g2s(s_row + (size_t)j * H, src, ROWB, s_bar);
    }
    cp_bulk_g2s(s_cw, cw, ROWB, s_bar);
    cp_bulk_g2s(s_ow, ow, ROWB, s_bar);
  }
  // Every global read this CTA needs has been issued — release the next
  // forward invocation's grid while this CTA waits on the mbarrier and
  // runs the reductions/mixture/epilogue tail.
  pdl_launch_dependents_after_reads();
  mbar_wait(s_bar, 0);

  // ---- phase 1: column-parallel per-row FP32 sumsq + dot(cw) ----------
  float2 sq2[R], dt2[R];
#pragma unroll
  for (int j = 0; j < R; ++j) {
    sq2[j] = make_float2(0.f, 0.f);
    dt2[j] = make_float2(0.f, 0.f);
  }
  const uint4* cw4 = reinterpret_cast<const uint4*>(s_cw);
  const uint4* ow4 = reinterpret_cast<const uint4*>(s_ow);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 128) {
      uint4 qc = cw4[c];
      float2 k[4];
      cvt4_f2(make_uint2(qc.x, qc.y), k[0], k[1]);
      cvt4_f2(make_uint2(qc.z, qc.w), k[2], k[3]);
#pragma unroll
      for (int j = 0; j < R; ++j) {
        uint4 q = reinterpret_cast<const uint4*>(s_row + (size_t)j * H)[c];
        float2 v[4];
        cvt4_f2(make_uint2(q.x, q.y), v[0], v[1]);
        cvt4_f2(make_uint2(q.z, q.w), v[2], v[3]);
#pragma unroll
        for (int c2 = 0; c2 < 4; ++c2) {
          sq2[j] = fma_x2(v[c2], v[c2], sq2[j]);
          dt2[j] = fma_x2(v[c2], k[c2], dt2[j]);
        }
      }
    }
  }
#pragma unroll
  for (int j = 0; j < R; ++j) {
    const float a = lane_tree_sum(__fadd_rn(sq2[j].x, sq2[j].y));
    const float b = lane_tree_sum(__fadd_rn(dt2[j].x, dt2[j].y));
    if ((tx & 31) == 0) {
      s_sq[warp * R + j] = a;
      s_dt[warp * R + j] = b;
    }
  }
  __syncthreads();  // barrier #1: per-warp partials visible

  // ---- softmax: identical redundant computation in every thread -------
  float w[R];
  float mx = -INFINITY;
  float wsum = 0.f;
  {
    float lg[R];
#pragma unroll
    for (int j = 0; j < R; ++j) {
      float a = 0.f, b = 0.f;
#pragma unroll
      for (int w8 = 0; w8 < NT / 32; ++w8) {
        a = __fadd_rn(a, s_sq[w8 * R + j]);
        b = __fadd_rn(b, s_dt[w8 * R + j]);
      }
      lg[j] = __fmul_rn(b, rsqrtf(__fadd_rn(__fmul_rn(a, INVH), eps)));
      mx = fmaxf(mx, lg[j]);
    }
#pragma unroll
    for (int j = 0; j < R; ++j) {
      w[j] = __expf(__fadd_rn(lg[j], -mx));
      wsum = __fadd_rn(wsum, w[j]);
    }
  }
  const float invs = __frcp_rn(wsum);
  const float2 inv2 = make_float2(invs, invs);
  float2 w2[R];
#pragma unroll
  for (int j = 0; j < R; ++j) w2[j] = make_float2(w[j], w[j]);

  // ---- phase 2: column-parallel weighted mixture (rows from smem) -----
  float2 mix[4][4];
#pragma unroll
  for (int i = 0; i < 4; ++i)
#pragma unroll
    for (int c2 = 0; c2 < 4; ++c2) mix[i][c2] = make_float2(0.f, 0.f);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 128) {
#pragma unroll
      for (int j = 0; j < R; ++j) {
        uint4 q = reinterpret_cast<const uint4*>(s_row + (size_t)j * H)[c];
        float2 v[4];
        cvt4_f2(make_uint2(q.x, q.y), v[0], v[1]);
        cvt4_f2(make_uint2(q.z, q.w), v[2], v[3]);
#pragma unroll
        for (int c2 = 0; c2 < 4; ++c2) mix[i][c2] = fma_x2(w2[j], v[c2], mix[i][c2]);
      }
    }
  }

  // ---- out-norm: deferred 1/sum, FP32 rowwise sq fold, 1 barrier ------
  float2 osq2 = make_float2(0.f, 0.f);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    if (i < 3 || tx < 128) {
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        mix[i][c2] = mul_x2(mix[i][c2], inv2);
        osq2 = fma_x2(mix[i][c2], mix[i][c2], osq2);
      }
    }
  }
  float tot = lane_tree_sum(__fadd_rn(osq2.x, osq2.y));
  if ((tx & 31) == 0) s_osq[warp] = tot;
  __syncthreads();  // barrier #2
  tot = 0.f;
#pragma unroll
  for (int w8 = 0; w8 < NT / 32; ++w8) tot = __fadd_rn(tot, s_osq[w8]);
  const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
  const float2 orr2 = make_float2(orr, orr);

  // ---- epilogue: disjoint per-thread 16B stores (ow from smem) --------
  uint4* dst = reinterpret_cast<uint4*>(out + (long long)t * H);
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const int c = tx + i * NT;
    if (i < 3 || tx < 128) {
      uint4 oq = ow4[c];
      float2 o01, o23, o45, o67;
      cvt4_f2(make_uint2(oq.x, oq.y), o01, o23);
      cvt4_f2(make_uint2(oq.z, oq.w), o45, o67);
      uint4 ores;
#pragma unroll
      for (int c2 = 0; c2 < 4; ++c2) {
        const float2 os = (c2 == 0) ? o01 : (c2 == 1) ? o23 : (c2 == 2) ? o45 : o67;
        __nv_bfloat162 bb = __float22bfloat162_rn(mul_x2(mul_x2(mix[i][c2], orr2), os));
        reinterpret_cast<unsigned*>(&ores)[c2] = *reinterpret_cast<unsigned*>(&bb);
      }
      dst[c] = ores;
    }
  }
}

// ------------------------------------------------------------------ chtm ---
// impl 87 (development experiment, opt-in): chp_kernel's exact
// chunked TMA producer/consumer pipeline, with the consumer-resident fp32
// cw/out_weight slices moved out of registers and into tensor memory. Each
// CTA reads both 7168-elem vectors from gmem once, converts to fp32, and
// stages its per-group slices with tcgen05.st (group 0: cols 0-31 cw /
// 32-63 ow; group 1: cols 64-95 / 96-127); per chunk the score pass drains
// the four slice lds up-front (single wait::ld), reusing each 8-elem slice
// across the chunk's rows exactly like the register-resident version; per
// token the epilogue drains the ow slices the same way. Frees 64 fp32
// registers/thread of consumer pressure (cw2[4][4] + ow2[4][4]) that the
// ASYM CREGS=200 budget otherwise carries across the whole pipeline. All
// arithmetic, fold order, ring structure, and the per-NVB config table are
// identical to impl85.
// TSUM (default 0 = production): 1 switches the score-phase intra-warp
// reductions to lane_tree_sum2 (impl93, opt-in only).
// PFL (default 0 = production): producer-side L2 lookahead distance in
// chunks (impl119, opt-in only). After issuing chunk gc's TMA loads the
// producer also issues cp.async.bulk.prefetch.L2 for chunk gc+PFL — the
// next ring slot's data — so the global-load pipeline runs ahead of the
// consumers' reduction/TMEM work for the in-flight chunks. Consumers,
// ring, arithmetic, and fold order are untouched (bit-identical output).
// DEAL (default 0 = production): impl134 (development tuning,
// opt-in via forward_preres impl=134, NVB==8 only) — the named-barrier-9
// TMEM DEALLOC-EARLY handoff proven on chtgd (impl131, R100) and chp3
// (impl133, R101) transplanted onto this PERSISTENT chtm dataflow. The
// post-loop `__syncthreads() + warp-0 tm05_dealloc` serial tail is removed;
// instead each consumer thread signals (bar.arrive 9, 288 — non-blocking)
// immediately after the LAST token's final TMEM read retires (the epilogue
// ow-slice drain + tm05_wait_ld), and the sole owner warp (warp 8, the
// tcgen05.alloc owner) blocks on bar.sync 9, 288 after issuing its TMA
// chunks, then deallocates the 128-column TMEM slot while the consumers
// execute the trailing FP32 epilogue + BF16 global stores. The last-token
// predicate (t + gridDim.x >= T) is CTA-uniform, so every consumer thread
// arrives exactly once on the final loop iteration; a zero-token CTA
// fallback keeps the 288 count exact if a grid ever exceeds T. Outputs are
// bit-identical to DEAL=0 by construction (no arithmetic path touched).
template <int NVB, int NVBC, int NOCC, int NCREGS, int NS_ = 2, int TSUM = 0, int PFL = 0,
          int DEAL = 0, int MCW = 0>
__global__ __launch_bounds__((NCREGS > 0) ? 384 : 288, NOCC) void chtm_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int CH = NVBC;
  constexpr int NCH = (R + CH - 1) / CH;
  constexpr int NS = NS_;
  constexpr bool ASYM = (NCREGS > 0);
  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  extern __shared__ char dyn[];
  bf16* buf = reinterpret_cast<bf16*>(dyn);  // [NS][CH][H]
  unsigned long long* bar_f = reinterpret_cast<unsigned long long*>(dyn + (size_t)NS * CH * ROWB);
  unsigned long long* bar_e = bar_f + NS;
  float* warp_rms = reinterpret_cast<float*>(bar_e + NS);  // [2][8][CH]
  float* warp_dot = warp_rms + 2 * 8 * CH;                 // [2][8][CH]
  float* warp_ssq = warp_dot + 2 * 8 * CH;                 // [2][8]
  unsigned* tm_slot = reinterpret_cast<unsigned*>(warp_ssq + 16);
  // development (MCW=1, opt-in impl140 chtcw): 2-CTA-cluster cw/ow staging.
  // Rank 0 issues ONE TMA multicast of the shared cw/out_weight vectors
  // (2*ROWB bytes) into BOTH cluster peers' smem staging buffers, armed on
  // each peer's own bar_v (per-copy expect_tx = 2*ROWB); the consumers then
  // read cw/ow from smem instead of a redundant per-CTA gmem read. Each CTA
  // keeps processing distinct tokens on the unchanged CH=5/NS=2 ring.
  bf16* s_cw = reinterpret_cast<bf16*>(tm_slot + 4);
  bf16* s_ow = s_cw + H;
  unsigned long long* bar_v = reinterpret_cast<unsigned long long*>(s_ow + H);

  pdl_wait();
  if (tx == 0) {
#pragma unroll
    for (int s = 0; s < NS; ++s) {
      mbar_init(&bar_f[s], 1);
      mbar_init(&bar_e[s], 256);
    }
    if (MCW) mbar_init(bar_v, 1);
  }
  if (warp == 8) {
    tm05_alloc(smem_u32(tm_slot), 128);
    tm05_relinq();
  }
  fence_mbar_init();
  __syncthreads();
  if constexpr (MCW) {
    cluster_sync();  // peer bar_v initialized before the multicast issue
    if (warp == 8 && lane == 0) {
      mbar_arrive_expect_tx(bar_v, 2 * (unsigned)ROWB);
      if (cluster_ctarank() == 0) {
        cp_bulk_g2s_mcast(s_cw, cw, (unsigned)ROWB, bar_v, 0x3);
        cp_bulk_g2s_mcast(s_ow, ow, (unsigned)ROWB, bar_v, 0x3);
      }
    }
  }

  if (warp >= 8) {
    // ---- producer: identical to chp_kernel ----------------------------
    if (ASYM) setmaxnreg_dec_w<40>();
    if (warp == 8 && lane == 0) {
      unsigned gc = 0;  // monotonic across tokens (ring state)
      for (int t = blockIdx.x; t < T; t += gridDim.x) {
#pragma unroll
        for (int ci = 0; ci < NCH; ++ci) {
          const int base = ci * CH;
          const int an = ((R - base) < CH) ? (R - base) : CH;
          const unsigned slot = gc % NS;
          const unsigned phase = (gc / NS) & 1;
          if (gc >= (unsigned)NS) mbar_wait(&bar_e[slot], phase ^ 1);
          mbar_arrive_expect_tx(&bar_f[slot], (unsigned)(an * ROWB));
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            if (r < an) {
              const int row = base + r;
              const bf16* src = (row < NVB) ? bank + (long long)t * stride_bm + (long long)row * H
                                            : prefix + (long long)t * H;
              cp_bulk_g2s(buf + ((size_t)slot * CH + r) * H, src, (unsigned)ROWB, &bar_f[slot]);
            }
          }
          if (PFL > 0) {
            // L2 lookahead (impl119): warm chunk gc+PFL's gmem
            // rows into L2 now — before the consumers finish
            // reducing the chunks already in the ring — so the
            // future TMA load drains from L2, not DRAM.
            const unsigned aha = gc + (unsigned)PFL;
            const int tok_d = (int)(aha / NCH) - (int)(gc / NCH);
            const long long t_l = (long long)t + (long long)tok_d * gridDim.x;
            if (t_l < T) {
              const int ci_l = (int)(aha % NCH);
              const int base_l = ci_l * CH;
              const int an_l = ((R - base_l) < CH) ? (R - base_l) : CH;
#pragma unroll
              for (int r = 0; r < CH; ++r) {
                if (r < an_l) {
                  const int row = base_l + r;
                  const bf16* src =
                      (row < NVB) ? bank + t_l * stride_bm + (long long)row * H : prefix + t_l * H;
                  cp_bulk_prefetch_l2(src, (unsigned)ROWB);
                }
              }
            }
          }
          ++gc;
        }
      }
    }
  } else {
    // ---- consumers: chunk-local online softmax/mixture -----------------
    if constexpr (ASYM) setmaxnreg_inc_w<NCREGS>();
    const int group = warp >> 2;  // 0/1: interleaved 1024-elem tiles
    const int tig = tx & 127;
    const float LOG2E = 1.4426950408889634f;
    const unsigned tmb = *tm_slot;
    const unsigned gcw = tmb + group * 64;  // 4 slices x 8 cols cw
    const unsigned gow = gcw + 32;          // 4 slices x 8 cols ow
    // Stage this thread's cw/ow slices into TMEM (one gmem read per CTA;
    // MCW=1: one TMA multicast read per 2-CTA cluster, smem-resident).
    if constexpr (MCW) mbar_wait(bar_v, 0);
    const bf16* const cws = MCW ? s_cw : cw;
    const bf16* const ows = MCW ? s_ow : ow;
#pragma unroll
    for (int si = 0; si < 4; ++si) {
      const int tile = si * 2 + group;
      if (tile < 7) {
        unsigned rv[8];
        uint4 q = reinterpret_cast<const uint4*>(cws + (tile * 128 + tig) * 8)[0];
        float2 f0, f1, f2, f3;
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gcw + si * 8, rv);
        q = reinterpret_cast<const uint4*>(ows + (tile * 128 + tig) * 8)[0];
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gow + si * 8, rv);
      }
    }
    tm05_wait_st();
    unsigned gc = 0;  // mirrors the producer's monotonic ring counter
    for (int t = blockIdx.x; t < T; t += gridDim.x) {
      float2 acc2[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si)
#pragma unroll
        for (int c = 0; c < 4; ++c) acc2[si][c] = make_float2(0.f, 0.f);
      float run_max = -INFINITY;
      float run_sum = 0.f;
      int cpar = 0;
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci, cpar ^= 1) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = gc % NS;
        const unsigned phase = (gc / NS) & 1;
        ++gc;
        mbar_wait(&bar_f[slot], phase);
        // drain this chunk's cw slices up-front (single wait::ld);
        // reused across all CH rows below.
        float2 cwq[4][4];
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) tm05_ld8(gcw + si * 8, cwq[si]);
        }
        uint4 qv[4][CH];
        float2 rms2[CH], dot2[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          rms2[r] = make_float2(0.f, 0.f);
          dot2[r] = make_float2(0.f, 0.f);
        }
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
            const int cidx = tile * 128 + tig;
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an)
                qv[si][r] = reinterpret_cast<const uint4*>(buf + ((size_t)slot * CH + r) * H)[cidx];
            }
            tm05_wait_ld();
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  rms2[r] = fma_x2(v[c], v[c], rms2[r]);
                  dot2[r] = fma_x2(v[c], cwq[si][c], dot2[r]);
                }
              }
            }
          }
        }
        mbar_arrive(&bar_e[slot]);
        // cross-warp score reduction (ascending-warp fold order)
        {
          float wr[CH], wd[CH];
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            float a = __fadd_rn(rms2[r].x, rms2[r].y);
            float b = __fadd_rn(dot2[r].x, dot2[r].y);
            if (TSUM) {
              a = lane_tree_sum2(a);
              b = lane_tree_sum2(b);
            } else {
              a = lane_tree_sum(a);
              b = lane_tree_sum(b);
            }
            if (lane == 0) {
              warp_rms[(cpar * 8 + warp) * CH + r] = a;
              warp_dot[(cpar * 8 + warp) * CH + r] = b;
            }
          }
          bar_cons_sync(1);
        }
        float logit_lane = 0.f;
        if (lane < an) {
          float tr = 0.f, td = 0.f;
#pragma unroll
          for (int w = 0; w < 8; ++w) {
            tr = __fadd_rn(tr, warp_rms[(cpar * 8 + w) * CH + lane]);
            td = __fadd_rn(td, warp_dot[(cpar * 8 + w) * CH + lane]);
          }
          logit_lane = __fmul_rn(td, rsqrtf(__fadd_rn(__fmul_rn(tr, INVH), eps)));
        }
        float lg[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) lg[r] = __shfl_sync(0xffffffffu, logit_lane, r);
        float chunk_max = -INFINITY;
#pragma unroll
        for (int r = 0; r < CH; ++r)
          if (r < an) chunk_max = fmaxf(chunk_max, lg[r]);
        const float new_max = fmaxf(run_max, chunk_max);
        const float corr = __expf(__fadd_rn(run_max, -new_max));
        float wgt[CH];
        float wsum = 0.f;
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          wgt[r] = (r < an) ? __expf(__fadd_rn(lg[r], -new_max)) : 0.f;
          wsum = __fadd_rn(wsum, wgt[r]);
        }
        run_sum = __fadd_rn(__fmul_rn(run_sum, corr), wsum);
        run_max = new_max;
        const float2 corr2 = make_float2(corr, corr);
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
                const float2 w2 = make_float2(wgt[r], wgt[r]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  acc2[si][c] = (r == 0) ? fma_x2(w2, v[c], mul_x2(acc2[si][c], corr2))
                                         : fma_x2(w2, v[c], acc2[si][c]);
                }
              }
            }
          }
        }
      }
      // ---- out-norm + epilogue --------------------------------------
      const float invs = __frcp_rn(run_sum);
      const float2 inv2 = make_float2(invs, invs);
      float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            acc2[si][c] = mul_x2(acc2[si][c], inv2);
            sq2 = fma_x2(acc2[si][c], acc2[si][c], sq2);
          }
        }
      }
      float sq = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
      const int tpar = ((t - blockIdx.x) / gridDim.x) & 1;
      if (lane == 0) warp_ssq[tpar * 8 + warp] = sq;
      bar_cons_sync(2);
      float tot = 0.f;
#pragma unroll
      for (int w = 0; w < 8; ++w) tot = __fadd_rn(tot, warp_ssq[tpar * 8 + w]);
      const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
      const float2 orr2 = make_float2(orr, orr);
      float2 owq[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) tm05_ld8(gow + si * 8, owq[si]);
      }
      tm05_wait_ld();
      // DEAL (impl134): the last TMEM read of this token has retired;
      // on the LAST token this CTA owns (CTA-uniform predicate) release
      // the owner warp's dealloc before the FP32 epilogue + stores.
      if constexpr (DEAL) {
        if (t + (int)gridDim.x >= T) bar_dealloc_arrive();
      }
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
          uint4 o4;
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            __nv_bfloat162 b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), owq[si][c]));
            reinterpret_cast<unsigned*>(&o4)[c] = *reinterpret_cast<unsigned*>(&b);
          }
          reinterpret_cast<uint4*>(out + (long long)t * H)[tile * 128 + tig] = o4;
        }
      }
    }
    if constexpr (DEAL) {
      // zero-token CTA safety (grid never exceeds T for this route,
      // but keep the named-barrier count exact if that ever changes).
      if (blockIdx.x >= (unsigned)T) bar_dealloc_arrive();
    }
  }
  if constexpr (DEAL) {
    // impl134 dealloc-early tail: no block-wide barrier; the consumer
    // warps (0-7) and producer warps 9-11 exit directly while the owner
    // warp (8, tcgen05.alloc owner) waits for the 256 consumer arrivals
    // — which guarantee every TMEM ld/st already completed — then frees
    // the 128-column slot overlapped with the consumers' trailing work.
    if (warp == 8) {
      bar_dealloc_wait();
      tm05_dealloc(*tm_slot, 128);
    }
  } else {
    __syncthreads();
    if (warp == 0) tm05_dealloc(*tm_slot, 128);
  }
  pdl_launch_dependents();
}

// ----------------------------------------------------------------- chtclc ---
// development retained (nsm=152): band-restricted (T > 2048, NVB==8)
// capped-grid CLC tail-stealing variant of the CH=5 persistent pipeline.
// Byte-identical to the development champion kernel_sm100_r106.py route 139
// (order-reversed ABBA vs the pre-131 control: every row >= 1.0x,
// geomean +0.56%; the full-band variant was FALSIFIED, -3.7/-4.6% @256/512).
template <int NVB, int NVBC, int NOCC, int NCREGS, int NS_ = 2, int TSUM = 0, int PFL = 0,
          int DEAL = 0>
__global__ __launch_bounds__((NCREGS > 0) ? 384 : 288, NOCC) void chtclc_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int CH = NVBC;
  constexpr int NCH = (R + CH - 1) / CH;
  constexpr int NS = NS_;
  constexpr bool ASYM = (NCREGS > 0);
  // Capped-grid CLC schedule (development; derivation duplicated
  // host-side in forward_preres impl==139; route guarded to nsm==152,
  // T > nsm so per >= 2 and every persistent CTA owns >= 1 static token).
  constexpr int NSMK = 152;
  const int per = (T + NSMK - 1) / NSMK;  // tokens/wave bound
  const int Gs = (T + per - 1) / per;     // persistent CTAs (== BGR grid)
  const int last_base = (per - 1) * Gs;   // first tail token
  const bool is_tail = ((int)blockIdx.x >= Gs);
  const int n_static = is_tail ? 0 : (per - 1);
  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  extern __shared__ char dyn[];
  bf16* buf = reinterpret_cast<bf16*>(dyn);  // [NS][CH][H]
  unsigned long long* bar_f = reinterpret_cast<unsigned long long*>(dyn + (size_t)NS * CH * ROWB);
  unsigned long long* bar_e = bar_f + NS;
  float* warp_rms = reinterpret_cast<float*>(bar_e + NS);  // [2][8][CH]
  float* warp_dot = warp_rms + 2 * 8 * CH;                 // [2][8][CH]
  float* warp_ssq = warp_dot + 2 * 8 * CH;                 // [2][8]
  unsigned* tm_slot = reinterpret_cast<unsigned*>(warp_ssq + 16);
  uint4* clc_res = reinterpret_cast<uint4*>(tm_slot + 4);  // 2x16B ring
  unsigned long long* clc_tok_bar = reinterpret_cast<unsigned long long*>(clc_res + 2);
  unsigned long long* clc_done_bar = clc_tok_bar + 2;

  pdl_wait();
  if (tx == 0) {
#pragma unroll
    for (int s = 0; s < NS; ++s) {
      mbar_init(&bar_f[s], 1);
      mbar_init(&bar_e[s], 256);
    }
    mbar_init(&clc_tok_bar[0], 1);  // owner arrive + 16B tx
    mbar_init(&clc_tok_bar[1], 1);
    mbar_init(&clc_done_bar[0], 256);  // consumer read-done
    mbar_init(&clc_done_bar[1], 256);
  }
  if (warp == 8) {
    tm05_alloc(smem_u32(tm_slot), 128);
    tm05_relinq();
  }
  fence_mbar_init();
  __syncthreads();

  if (warp >= 8) {
    // ---- producer: identical to chp_kernel ----------------------------
    if (ASYM) setmaxnreg_dec_w<40>();
    if (warp == 8 && lane == 0) {
      unsigned gc = 0;  // monotonic across tokens (ring state)
      for (int wi = 0;; ++wi) {
        int t;
        if (is_tail) {
          if (wi > 0) break;
          t = last_base + ((int)blockIdx.x - Gs);
        } else if (wi < n_static) {
          t = (int)blockIdx.x + wi * Gs;
        } else {
          // CLC tail steal: cancel a pending tail CTA and take
          // its token; the 2-slot ring mirrors the consumer
          // decode below so producer/consumers agree on the
          // exact token sequence per work item.
          const int sc = wi - n_static;
          const int cbuf = sc & 1;
          const unsigned cph = ((unsigned)sc >> 1) & 1u;
          if (sc >= 2) mbar_wait(&clc_done_bar[cbuf], cph ^ 1u);
          fence_proxy_async_cta();
          clc_try_cancel(clc_res + cbuf, &clc_tok_bar[cbuf]);
          mbar_arrive_expect_tx(&clc_tok_bar[cbuf], 16);
          mbar_wait(&clc_tok_bar[cbuf], cph);
          int cx = -1;
          const ulonglong2 resp = *reinterpret_cast<const ulonglong2*>(clc_res + cbuf);
          if (!clc_decode_x(resp, cx) || cx < Gs) break;
          t = last_base + (cx - Gs);
        }
#pragma unroll
        for (int ci = 0; ci < NCH; ++ci) {
          const int base = ci * CH;
          const int an = ((R - base) < CH) ? (R - base) : CH;
          const unsigned slot = gc % NS;
          const unsigned phase = (gc / NS) & 1;
          if (gc >= (unsigned)NS) mbar_wait(&bar_e[slot], phase ^ 1);
          mbar_arrive_expect_tx(&bar_f[slot], (unsigned)(an * ROWB));
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            if (r < an) {
              const int row = base + r;
              const bf16* src = (row < NVB) ? bank + (long long)t * stride_bm + (long long)row * H
                                            : prefix + (long long)t * H;
              cp_bulk_g2s(buf + ((size_t)slot * CH + r) * H, src, (unsigned)ROWB, &bar_f[slot]);
            }
          }
          if (PFL > 0) {
            // L2 lookahead (impl119): warm chunk gc+PFL's gmem
            // rows into L2 now — before the consumers finish
            // reducing the chunks already in the ring — so the
            // future TMA load drains from L2, not DRAM.
            const unsigned aha = gc + (unsigned)PFL;
            const int tok_d = (int)(aha / NCH) - (int)(gc / NCH);
            const long long t_l = (long long)t + (long long)tok_d * gridDim.x;
            if (t_l < T) {
              const int ci_l = (int)(aha % NCH);
              const int base_l = ci_l * CH;
              const int an_l = ((R - base_l) < CH) ? (R - base_l) : CH;
#pragma unroll
              for (int r = 0; r < CH; ++r) {
                if (r < an_l) {
                  const int row = base_l + r;
                  const bf16* src =
                      (row < NVB) ? bank + t_l * stride_bm + (long long)row * H : prefix + t_l * H;
                  cp_bulk_prefetch_l2(src, (unsigned)ROWB);
                }
              }
            }
          }
          ++gc;
        }
      }
    }
  } else {
    // ---- consumers: chunk-local online softmax/mixture -----------------
    if constexpr (ASYM) setmaxnreg_inc_w<NCREGS>();
    const int group = warp >> 2;  // 0/1: interleaved 1024-elem tiles
    const int tig = tx & 127;
    const float LOG2E = 1.4426950408889634f;
    const unsigned tmb = *tm_slot;
    const unsigned gcw = tmb + group * 64;  // 4 slices x 8 cols cw
    const unsigned gow = gcw + 32;          // 4 slices x 8 cols ow
    // Stage this thread's cw/ow slices into TMEM (one gmem read per CTA).
#pragma unroll
    for (int si = 0; si < 4; ++si) {
      const int tile = si * 2 + group;
      if (tile < 7) {
        unsigned rv[8];
        uint4 q = reinterpret_cast<const uint4*>(cw + (tile * 128 + tig) * 8)[0];
        float2 f0, f1, f2, f3;
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gcw + si * 8, rv);
        q = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gow + si * 8, rv);
      }
    }
    tm05_wait_st();
    unsigned gc = 0;  // mirrors the producer's monotonic ring counter
    for (int wi = 0;; ++wi) {
      int t;
      if (is_tail) {
        if (wi > 0) break;
        t = last_base + ((int)blockIdx.x - Gs);
      } else if (wi < n_static) {
        t = (int)blockIdx.x + wi * Gs;
      } else {
        const int sc = wi - n_static;
        const int cbuf = sc & 1;
        const unsigned cph = ((unsigned)sc >> 1) & 1u;
        mbar_wait(&clc_tok_bar[cbuf], cph);
        int cx = -1;
        if (lane == 0) {
          const ulonglong2 resp = *reinterpret_cast<const ulonglong2*>(clc_res + cbuf);
          if (clc_decode_x(resp, cx) && cx >= Gs)
            cx = last_base + (cx - Gs);
          else
            cx = -1;
        }
        cx = __shfl_sync(0xffffffffu, cx, 0);
        mbar_arrive(&clc_done_bar[cbuf]);
        if (cx < 0) break;
        t = cx;
      }
      float2 acc2[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si)
#pragma unroll
        for (int c = 0; c < 4; ++c) acc2[si][c] = make_float2(0.f, 0.f);
      float run_max = -INFINITY;
      float run_sum = 0.f;
      int cpar = 0;
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci, cpar ^= 1) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = gc % NS;
        const unsigned phase = (gc / NS) & 1;
        ++gc;
        mbar_wait(&bar_f[slot], phase);
        // drain this chunk's cw slices up-front (single wait::ld);
        // reused across all CH rows below.
        float2 cwq[4][4];
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) tm05_ld8(gcw + si * 8, cwq[si]);
        }
        uint4 qv[4][CH];
        float2 rms2[CH], dot2[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          rms2[r] = make_float2(0.f, 0.f);
          dot2[r] = make_float2(0.f, 0.f);
        }
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
            const int cidx = tile * 128 + tig;
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an)
                qv[si][r] = reinterpret_cast<const uint4*>(buf + ((size_t)slot * CH + r) * H)[cidx];
            }
            tm05_wait_ld();
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  rms2[r] = fma_x2(v[c], v[c], rms2[r]);
                  dot2[r] = fma_x2(v[c], cwq[si][c], dot2[r]);
                }
              }
            }
          }
        }
        mbar_arrive(&bar_e[slot]);
        // cross-warp score reduction (ascending-warp fold order)
        {
          float wr[CH], wd[CH];
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            float a = __fadd_rn(rms2[r].x, rms2[r].y);
            float b = __fadd_rn(dot2[r].x, dot2[r].y);
            if (TSUM) {
              a = lane_tree_sum2(a);
              b = lane_tree_sum2(b);
            } else {
              a = lane_tree_sum(a);
              b = lane_tree_sum(b);
            }
            if (lane == 0) {
              warp_rms[(cpar * 8 + warp) * CH + r] = a;
              warp_dot[(cpar * 8 + warp) * CH + r] = b;
            }
          }
          bar_cons_sync(1);
        }
        float logit_lane = 0.f;
        if (lane < an) {
          float tr = 0.f, td = 0.f;
#pragma unroll
          for (int w = 0; w < 8; ++w) {
            tr = __fadd_rn(tr, warp_rms[(cpar * 8 + w) * CH + lane]);
            td = __fadd_rn(td, warp_dot[(cpar * 8 + w) * CH + lane]);
          }
          logit_lane = __fmul_rn(td, rsqrtf(__fadd_rn(__fmul_rn(tr, INVH), eps)));
        }
        float lg[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) lg[r] = __shfl_sync(0xffffffffu, logit_lane, r);
        float chunk_max = -INFINITY;
#pragma unroll
        for (int r = 0; r < CH; ++r)
          if (r < an) chunk_max = fmaxf(chunk_max, lg[r]);
        const float new_max = fmaxf(run_max, chunk_max);
        const float corr = __expf(__fadd_rn(run_max, -new_max));
        float wgt[CH];
        float wsum = 0.f;
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          wgt[r] = (r < an) ? __expf(__fadd_rn(lg[r], -new_max)) : 0.f;
          wsum = __fadd_rn(wsum, wgt[r]);
        }
        run_sum = __fadd_rn(__fmul_rn(run_sum, corr), wsum);
        run_max = new_max;
        const float2 corr2 = make_float2(corr, corr);
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
                const float2 w2 = make_float2(wgt[r], wgt[r]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  acc2[si][c] = (r == 0) ? fma_x2(w2, v[c], mul_x2(acc2[si][c], corr2))
                                         : fma_x2(w2, v[c], acc2[si][c]);
                }
              }
            }
          }
        }
      }
      // ---- out-norm + epilogue --------------------------------------
      const float invs = __frcp_rn(run_sum);
      const float2 inv2 = make_float2(invs, invs);
      float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            acc2[si][c] = mul_x2(acc2[si][c], inv2);
            sq2 = fma_x2(acc2[si][c], acc2[si][c], sq2);
          }
        }
      }
      float sq = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
      const int tpar = wi & 1;  // per-work-item ping-pong parity
      if (lane == 0) warp_ssq[tpar * 8 + warp] = sq;
      bar_cons_sync(2);
      float tot = 0.f;
#pragma unroll
      for (int w = 0; w < 8; ++w) tot = __fadd_rn(tot, warp_ssq[tpar * 8 + w]);
      const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
      const float2 orr2 = make_float2(orr, orr);
      float2 owq[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) tm05_ld8(gow + si * 8, owq[si]);
      }
      tm05_wait_ld();
      // DEAL (impl134): the last TMEM read of this token has retired;
      // on the LAST token this CTA owns (CTA-uniform predicate) release
      // the owner warp's dealloc before the FP32 epilogue + stores.
      // DEAL: the in-loop last-token arrive is moved to loop exit
      // (the last token is dynamic under CLC stealing).
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
          uint4 o4;
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            __nv_bfloat162 b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), owq[si][c]));
            reinterpret_cast<unsigned*>(&o4)[c] = *reinterpret_cast<unsigned*>(&b);
          }
          reinterpret_cast<uint4*>(out + (long long)t * H)[tile * 128 + tig] = o4;
        }
      }
    }
    if constexpr (DEAL) {
      // chtclc: exactly one arrive per consumer thread at loop exit;
      // the owner warp still acks (bar.sync 9, 288) + deallocs below.
      bar_dealloc_arrive();
    }
  }
  if constexpr (DEAL) {
    // impl134 dealloc-early tail: no block-wide barrier; the consumer
    // warps (0-7) and producer warps 9-11 exit directly while the owner
    // warp (8, tcgen05.alloc owner) waits for the 256 consumer arrivals
    // — which guarantee every TMEM ld/st already completed — then frees
    // the 128-column slot overlapped with the consumers' trailing work.
    if (warp == 8) {
      bar_dealloc_wait();
      tm05_dealloc(*tm_slot, 128);
    }
  } else {
    __syncthreads();
    if (warp == 0) tm05_dealloc(*tm_slot, 128);
  }
  pdl_launch_dependents();
}

