// ------------------------------------------------------------------- chtg ---
// impl126 (development tuning, opt-in via K3_CHTG_T, NVB==4 /
// NSRC==5 production candidate): STATIC CTA-per-token variant of the
// production chtm_kernel — identical 384-thread (8 consumer + 1 producer
// warp-group) structure, identical TMEM cw/ow staging, identical NS=2/CH=5
// TMA ring, identical arithmetic and fold order — but the persistent
// grid-stride token loop is replaced by a compile-time token assignment
// token = blockIdx.x with grid = T. This isolates static scheduling from
// the failed slim 8-warp lean5 (impl125) design: every thread does exactly
// the same work as impl87 does at T <= nsm (where its grid already equals
// T and every CTA processes exactly one token), minus the loop induction,
// the ring-state carry across iterations, and the t-parity smem banking.
// The template is general over NVB; only the NSRC=5 instantiation
// (chtg_kernel<4,5,1,200>) is routed. RETAINED (directive criterion met):
// ABBAx2 order-reversed cold-L2 NCU A/B (gpu__time_duration,
// --cache-control all --clock-control none, 128 launches/point):
//   phase 1 — wins at every sub-wave point: -1.77% @T=8, -3.02% @16,
//     -2.59% @32, -2.98% @48, -2.50% @64, -3.44% @128;
//   wave cliff — -2.64% @144, -2.27% @148, -2.99% @152, then +14.03%
//     @153, +14.01% @160, +13.48% @176; +9.12% @192, +24.9% @384,
//     +34.9% @512, +57.4% @1024 (grid=T > nsm=152 -> multiple CTA waves;
//     persistent impl87 keeps one wave and amortizes TMEM staging across
//     its looped tokens).
// Production cutover is dimension-only at the runtime SM count:
// nvb==4 && T <= nsm -> impl126, T > nsm -> impl87 (chtg_bound()).
// Outputs bit-identical to impl87 at all 8 probed T (r95_bitid probe);
// boundary straddle 151..154 + off-suite nvb 1..8 clean (r95_check).
template <int NVB, int NVBC, int NOCC, int NCREGS, int NS_ = 2>
__global__ __launch_bounds__((NCREGS > 0) ? 384 : 288, NOCC) void chtg_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int CH = NVBC;
  constexpr int NCH = (R + CH - 1) / CH;
  constexpr int NS = NS_;
  constexpr bool ASYM = (NCREGS > 0);
  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  const int t = blockIdx.x;  // static: one token per CTA, grid = T
  (void)T;
  extern __shared__ char dyn[];
  bf16* buf = reinterpret_cast<bf16*>(dyn);  // [NS][CH][H]
  unsigned long long* bar_f = reinterpret_cast<unsigned long long*>(dyn + (size_t)NS * CH * ROWB);
  unsigned long long* bar_e = bar_f + NS;
  float* warp_rms = reinterpret_cast<float*>(bar_e + NS);  // [2][8][CH]
  float* warp_dot = warp_rms + 2 * 8 * CH;                 // [2][8][CH]
  float* warp_ssq = warp_dot + 2 * 8 * CH;                 // [2][8]
  unsigned* tm_slot = reinterpret_cast<unsigned*>(warp_ssq + 16);

  pdl_wait();
  if (tx == 0) {
#pragma unroll
    for (int s = 0; s < NS; ++s) {
      mbar_init(&bar_f[s], 1);
      mbar_init(&bar_e[s], 256);
    }
  }
  if (warp == 8) {
    tm05_alloc(smem_u32(tm_slot), 128);
    tm05_relinq();
  }
  fence_mbar_init();
  __syncthreads();

  if (warp >= 8) {
    // ---- producer: one token's chunks, identical ring discipline ------
    if (ASYM) setmaxnreg_dec_w<40>();
    if (warp == 8 && lane == 0) {
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = (unsigned)ci % NS;
        const unsigned phase = ((unsigned)ci / NS) & 1;
        if (ci >= NS) mbar_wait(&bar_e[slot], phase ^ 1);
        mbar_arrive_expect_tx(&bar_f[slot], (unsigned)(an * ROWB));
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          if (r < an) {
            const int row = base + r;
            const bf16* src = (row < NVB) ? bank + (long long)t * stride_bm + (long long)row * H
                                          : prefix + (long long)t * H;
            cp_bulk_g2s(buf + ((size_t)slot * CH + r) * H, src, (unsigned)ROWB, &bar_f[slot]);
          }
        }
      }
    }
  } else {
    // ---- consumers: single-token chunk-local online softmax/mixture ---
    if constexpr (ASYM) setmaxnreg_inc_w<NCREGS>();
    const int group = warp >> 2;  // 0/1: interleaved 1024-elem tiles
    const int tig = tx & 127;
    const unsigned tmb = *tm_slot;
    const unsigned gcw = tmb + group * 64;  // 4 slices x 8 cols cw
    const unsigned gow = gcw + 32;          // 4 slices x 8 cols ow
    // Stage this thread's cw/ow slices into TMEM (one gmem read per CTA).
#pragma unroll
    for (int si = 0; si < 4; ++si) {
      const int tile = si * 2 + group;
      if (tile < 7) {
        unsigned rv[8];
        uint4 q = reinterpret_cast<const uint4*>(cw + (tile * 128 + tig) * 8)[0];
        float2 f0, f1, f2, f3;
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gcw + si * 8, rv);
        q = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gow + si * 8, rv);
      }
    }
    tm05_wait_st();
    {
      float2 acc2[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si)
#pragma unroll
        for (int c = 0; c < 4; ++c) acc2[si][c] = make_float2(0.f, 0.f);
      float run_max = -INFINITY;
      float run_sum = 0.f;
      int cpar = 0;
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci, cpar ^= 1) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = (unsigned)ci % NS;
        const unsigned phase = ((unsigned)ci / NS) & 1;
        mbar_wait(&bar_f[slot], phase);
        // drain this chunk's cw slices up-front (single wait::ld);
        // reused across all CH rows below.
        float2 cwq[4][4];
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) tm05_ld8(gcw + si * 8, cwq[si]);
        }
        uint4 qv[4][CH];
        float2 rms2[CH], dot2[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          rms2[r] = make_float2(0.f, 0.f);
          dot2[r] = make_float2(0.f, 0.f);
        }
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
            const int cidx = tile * 128 + tig;
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an)
                qv[si][r] = reinterpret_cast<const uint4*>(buf + ((size_t)slot * CH + r) * H)[cidx];
            }
            tm05_wait_ld();
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  rms2[r] = fma_x2(v[c], v[c], rms2[r]);
                  dot2[r] = fma_x2(v[c], cwq[si][c], dot2[r]);
                }
              }
            }
          }
        }
        mbar_arrive(&bar_e[slot]);
        // cross-warp score reduction (ascending-warp fold order)
        {
          float wr[CH], wd[CH];
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            float a = __fadd_rn(rms2[r].x, rms2[r].y);
            float b = __fadd_rn(dot2[r].x, dot2[r].y);
            a = lane_tree_sum(a);
            b = lane_tree_sum(b);
            if (lane == 0) {
              warp_rms[(cpar * 8 + warp) * CH + r] = a;
              warp_dot[(cpar * 8 + warp) * CH + r] = b;
            }
          }
          bar_cons_sync(1);
        }
        float logit_lane = 0.f;
        if (lane < an) {
          float tr = 0.f, td = 0.f;
#pragma unroll
          for (int w = 0; w < 8; ++w) {
            tr = __fadd_rn(tr, warp_rms[(cpar * 8 + w) * CH + lane]);
            td = __fadd_rn(td, warp_dot[(cpar * 8 + w) * CH + lane]);
          }
          logit_lane = __fmul_rn(td, rsqrtf(__fadd_rn(__fmul_rn(tr, INVH), eps)));
        }
        float lg[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) lg[r] = __shfl_sync(0xffffffffu, logit_lane, r);
        float chunk_max = -INFINITY;
#pragma unroll
        for (int r = 0; r < CH; ++r)
          if (r < an) chunk_max = fmaxf(chunk_max, lg[r]);
        const float new_max = fmaxf(run_max, chunk_max);
        const float corr = __expf(__fadd_rn(run_max, -new_max));
        float wgt[CH];
        float wsum = 0.f;
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          wgt[r] = (r < an) ? __expf(__fadd_rn(lg[r], -new_max)) : 0.f;
          wsum = __fadd_rn(wsum, wgt[r]);
        }
        run_sum = __fadd_rn(__fmul_rn(run_sum, corr), wsum);
        run_max = new_max;
        const float2 corr2 = make_float2(corr, corr);
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
                const float2 w2 = make_float2(wgt[r], wgt[r]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  acc2[si][c] = (r == 0) ? fma_x2(w2, v[c], mul_x2(acc2[si][c], corr2))
                                         : fma_x2(w2, v[c], acc2[si][c]);
                }
              }
            }
          }
        }
      }
      // ---- out-norm + epilogue (tpar == 0: one token per CTA) -------
      const float invs = __frcp_rn(run_sum);
      const float2 inv2 = make_float2(invs, invs);
      float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            acc2[si][c] = mul_x2(acc2[si][c], inv2);
            sq2 = fma_x2(acc2[si][c], acc2[si][c], sq2);
          }
        }
      }
      float sq = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
      if (lane == 0) warp_ssq[warp] = sq;
      bar_cons_sync(2);
      float tot = 0.f;
#pragma unroll
      for (int w = 0; w < 8; ++w) tot = __fadd_rn(tot, warp_ssq[w]);
      const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
      const float2 orr2 = make_float2(orr, orr);
      float2 owq[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) tm05_ld8(gow + si * 8, owq[si]);
      }
      tm05_wait_ld();
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
          uint4 o4;
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            __nv_bfloat162 b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), owq[si][c]));
            reinterpret_cast<unsigned*>(&o4)[c] = *reinterpret_cast<unsigned*>(&b);
          }
          reinterpret_cast<uint4*>(out + (long long)t * H)[tile * 128 + tig] = o4;
        }
      }
    }
  }
  __syncthreads();
  if (warp == 0) tm05_dealloc(*tm_slot, 128);
  pdl_launch_dependents();
}

// ------------------------------------------------------------------ chtgp ---
// impl130 (development tuning, opt-in via K3_IMPL=130 / direct
// forward_preres impl=130, NVB==4 only): compile-time-unrolled predication
// of chtg_kernel's remaining runtime source/prefix conditional chain, per the
// development full-set cold-L2 profile (r98_chtg_t16.ncu-rep, T=16, NVB=4).
// Measured branch facts for chtg_kernel<4,5,1,200> @ T=16 (7.14us):
//   warp-state per-issue: barrier 3.49, long_scoreboard 2.14, wait 1.60,
//   no_instruction 1.43, short_scoreboard 0.82, branch_resolving 0.19;
//   5872 branch instructions, 93.06% uniform, 0.29 divergent/warp; the
//   SINGLE divergent SASS site (+0x2f80: ISETP.GT.U32 P0, lane, 0x4; @P0 BRA,
//   dv=128 on 128 warp-executions) is exactly `if (lane < an)`, the runtime
//   row-ownership guard of the per-chunk score fold — the consumer face of
//   the source/prefix chain (an counts rows incl. the appended prefix row).
//   For the routed <4,5,1,200> specialization NCH == 1 (one 5-row chunk:
//   rows 0..3 bank + row 4 prefix), so an == R == CH is a template constant;
//   the chain is converted to compile-time-unrolled predication as follows:
//   (a) the single chunk instance is emitted statically: slot/phase/cpar are
//       constexpr 0, all chunk-bound induction disappears;
//   (b) every `r < an` guard (qv smem loads, score FMAs, chunk_max, wgt) is
//       re-expressed against constexpr AN so the predicates are compile-time;
//   (c) the `if (lane < an)` divergent branch around the cross-warp logit
//       fold (rsqrt + 8xLDS) is removed: the fold is computed on ALL lanes
//       (lanes >= R read in-bounds but unused warp_rms/warp_dot entries —
//       index max 7*CH+31 < 2*8*CH for CH >= 4 — discarded afterwards);
//       lg[r] still gathers via shfl from source lanes r < R, which hold
//       bit-identical valid logits, so every consumed value is unchanged.
//   Producer, TMEM staging, score arithmetic, fold STS pattern, online
//   softmax order, mixture, out-norm, epilogue, dealloc and PDL hooks are
//   UNCHANGED (same 384-thread static CTA-per-token geometry, grid = T);
//   outputs are bit-identical to impl126 by construction (score/fold values
//   and fold order untouched; only dead-guard/predicate structure differs).

// ------------------------------------------------------------------ chtgd ---
// impl131 (development tuning, opt-in via forward_preres
// impl=131, NVB==4 only): DEALLOC-EARLY variant of chtg_kernel (impl126) —
// bit-identical arithmetic/fold order and identical 384-thread (8 consumer +
// 1 producer warp-group) geometry, TMEM cw/ow staging, NS=2/CH=5 TMA ring —
// but the TMEM dealloc is moved OFF the post-__syncthreads serial tail.
//
// Motivation (r98 full-set profile of chtg_kernel<4,5,1,200> @ T=16): the
// hottest single SASS location was the drain branch to PREEXIT (13/92 warp
// samples) — warps 1-11 parked at CTA exit while warp 0 executed the
// tm05_dealloc UTCATOMSWS/ATOMS.AND cluster-atomic sequence after the final
// __syncthreads. That tail is pure serialization: the last TMEM *read*
// (the consumers' `ow` slice loads + tm05_wait_ld) retires into registers
// well before the FP32 epilogue math + BF16 global stores finish, so the
// dealloc can legally overlap them.
//
// Handoff (bar_dealloc_arrive/wait, named barrier ID 9, count 288):
//   consumers (warps 0-7): tm05_wait_ld() for the ow slices retires the
//     final TMEM reads -> bar.arrive (non-blocking) -> FP32 epilogue +
//     stores -> pdl_launch_dependents -> exit; no __syncthreads, no dealloc.
//   owner warp (warp 8, producer warpgroup, tcgen05.alloc owner): after its
//     TMA issue loop it blocks on bar.sync; on completion (all 256 consumer
//     arrivals, hence every wait::ld done) it issues tm05_dealloc while the
//     epilogue is still running. Warps 9-11 exit directly.
// Safety: the per-warp wait::ld + the barrier's cross-warp ordering impose
// the mandatory TMEM lifecycle order (all ld/st complete before dealloc);
// relinquish stays at alloc time as in chtg. Outputs are bit-identical to
// impl126 by construction (no arithmetic path touched).
template <int NVB, int NVBC, int NOCC, int NCREGS, int NS_ = 2>
__global__ __launch_bounds__((NCREGS > 0) ? 384 : 288, NOCC) void chtgd_kernel(
    const bf16* __restrict__ prefix, const bf16* __restrict__ bank, const bf16* __restrict__ cw,
    const bf16* __restrict__ ow, bf16* __restrict__ out, int T, long long stride_bm, float eps) {
  constexpr int R = NVB + 1;
  constexpr int CH = NVBC;
  constexpr int NCH = (R + CH - 1) / CH;
  constexpr int NS = NS_;
  constexpr bool ASYM = (NCREGS > 0);
  const int tx = threadIdx.x;
  const int warp = tx >> 5;
  const int lane = tx & 31;
  const int t = blockIdx.x;  // static: one token per CTA, grid = T
  (void)T;
  extern __shared__ char dyn[];
  bf16* buf = reinterpret_cast<bf16*>(dyn);  // [NS][CH][H]
  unsigned long long* bar_f = reinterpret_cast<unsigned long long*>(dyn + (size_t)NS * CH * ROWB);
  unsigned long long* bar_e = bar_f + NS;
  float* warp_rms = reinterpret_cast<float*>(bar_e + NS);  // [2][8][CH]
  float* warp_dot = warp_rms + 2 * 8 * CH;                 // [2][8][CH]
  float* warp_ssq = warp_dot + 2 * 8 * CH;                 // [2][8]
  unsigned* tm_slot = reinterpret_cast<unsigned*>(warp_ssq + 16);

  pdl_wait();
  if (tx == 0) {
#pragma unroll
    for (int s = 0; s < NS; ++s) {
      mbar_init(&bar_f[s], 1);
      mbar_init(&bar_e[s], 256);
    }
  }
  if (warp == 8) {
    tm05_alloc(smem_u32(tm_slot), 128);
    tm05_relinq();
  }
  fence_mbar_init();
  __syncthreads();

  if (warp >= 8) {
    // ---- producer: one token's chunks, identical ring discipline ------
    if (ASYM) setmaxnreg_dec_w<40>();
    if (warp == 8 && lane == 0) {
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = (unsigned)ci % NS;
        const unsigned phase = ((unsigned)ci / NS) & 1;
        if (ci >= NS) mbar_wait(&bar_e[slot], phase ^ 1);
        mbar_arrive_expect_tx(&bar_f[slot], (unsigned)(an * ROWB));
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          if (r < an) {
            const int row = base + r;
            const bf16* src = (row < NVB) ? bank + (long long)t * stride_bm + (long long)row * H
                                          : prefix + (long long)t * H;
            cp_bulk_g2s(buf + ((size_t)slot * CH + r) * H, src, (unsigned)ROWB, &bar_f[slot]);
          }
        }
      }
    }
    if (warp == 8) {
      // Owner-warp early dealloc: block until every consumer warp's
      // final TMEM load has completed, then free the 128-column slot
      // while the consumers run the FP32 epilogue + global stores.
      bar_dealloc_wait();
      tm05_dealloc(*tm_slot, 128);
    }
  } else {
    // ---- consumers: single-token chunk-local online softmax/mixture ---
    if constexpr (ASYM) setmaxnreg_inc_w<NCREGS>();
    const int group = warp >> 2;  // 0/1: interleaved 1024-elem tiles
    const int tig = tx & 127;
    const unsigned tmb = *tm_slot;
    const unsigned gcw = tmb + group * 64;  // 4 slices x 8 cols cw
    const unsigned gow = gcw + 32;          // 4 slices x 8 cols ow
    // Stage this thread's cw/ow slices into TMEM (one gmem read per CTA).
#pragma unroll
    for (int si = 0; si < 4; ++si) {
      const int tile = si * 2 + group;
      if (tile < 7) {
        unsigned rv[8];
        uint4 q = reinterpret_cast<const uint4*>(cw + (tile * 128 + tig) * 8)[0];
        float2 f0, f1, f2, f3;
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gcw + si * 8, rv);
        q = reinterpret_cast<const uint4*>(ow + (tile * 128 + tig) * 8)[0];
        cvt4_f2(make_uint2(q.x, q.y), f0, f1);
        cvt4_f2(make_uint2(q.z, q.w), f2, f3);
        rv[0] = __float_as_uint(f0.x);
        rv[1] = __float_as_uint(f0.y);
        rv[2] = __float_as_uint(f1.x);
        rv[3] = __float_as_uint(f1.y);
        rv[4] = __float_as_uint(f2.x);
        rv[5] = __float_as_uint(f2.y);
        rv[6] = __float_as_uint(f3.x);
        rv[7] = __float_as_uint(f3.y);
        tm05_st8(gow + si * 8, rv);
      }
    }
    tm05_wait_st();
    {
      float2 acc2[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si)
#pragma unroll
        for (int c = 0; c < 4; ++c) acc2[si][c] = make_float2(0.f, 0.f);
      float run_max = -INFINITY;
      float run_sum = 0.f;
      int cpar = 0;
#pragma unroll
      for (int ci = 0; ci < NCH; ++ci, cpar ^= 1) {
        const int base = ci * CH;
        const int an = ((R - base) < CH) ? (R - base) : CH;
        const unsigned slot = (unsigned)ci % NS;
        const unsigned phase = ((unsigned)ci / NS) & 1;
        mbar_wait(&bar_f[slot], phase);
        // drain this chunk's cw slices up-front (single wait::ld);
        // reused across all CH rows below.
        float2 cwq[4][4];
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) tm05_ld8(gcw + si * 8, cwq[si]);
        }
        uint4 qv[4][CH];
        float2 rms2[CH], dot2[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          rms2[r] = make_float2(0.f, 0.f);
          dot2[r] = make_float2(0.f, 0.f);
        }
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
            const int cidx = tile * 128 + tig;
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an)
                qv[si][r] = reinterpret_cast<const uint4*>(buf + ((size_t)slot * CH + r) * H)[cidx];
            }
            tm05_wait_ld();
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  rms2[r] = fma_x2(v[c], v[c], rms2[r]);
                  dot2[r] = fma_x2(v[c], cwq[si][c], dot2[r]);
                }
              }
            }
          }
        }
        mbar_arrive(&bar_e[slot]);
        // cross-warp score reduction (ascending-warp fold order)
        {
          float wr[CH], wd[CH];
#pragma unroll
          for (int r = 0; r < CH; ++r) {
            float a = __fadd_rn(rms2[r].x, rms2[r].y);
            float b = __fadd_rn(dot2[r].x, dot2[r].y);
            a = lane_tree_sum(a);
            b = lane_tree_sum(b);
            if (lane == 0) {
              warp_rms[(cpar * 8 + warp) * CH + r] = a;
              warp_dot[(cpar * 8 + warp) * CH + r] = b;
            }
          }
          bar_cons_sync(1);
        }
        float logit_lane = 0.f;
        if (lane < an) {
          float tr = 0.f, td = 0.f;
#pragma unroll
          for (int w = 0; w < 8; ++w) {
            tr = __fadd_rn(tr, warp_rms[(cpar * 8 + w) * CH + lane]);
            td = __fadd_rn(td, warp_dot[(cpar * 8 + w) * CH + lane]);
          }
          logit_lane = __fmul_rn(td, rsqrtf(__fadd_rn(__fmul_rn(tr, INVH), eps)));
        }
        float lg[CH];
#pragma unroll
        for (int r = 0; r < CH; ++r) lg[r] = __shfl_sync(0xffffffffu, logit_lane, r);
        float chunk_max = -INFINITY;
#pragma unroll
        for (int r = 0; r < CH; ++r)
          if (r < an) chunk_max = fmaxf(chunk_max, lg[r]);
        const float new_max = fmaxf(run_max, chunk_max);
        const float corr = __expf(__fadd_rn(run_max, -new_max));
        float wgt[CH];
        float wsum = 0.f;
#pragma unroll
        for (int r = 0; r < CH; ++r) {
          wgt[r] = (r < an) ? __expf(__fadd_rn(lg[r], -new_max)) : 0.f;
          wsum = __fadd_rn(wsum, wgt[r]);
        }
        run_sum = __fadd_rn(__fmul_rn(run_sum, corr), wsum);
        run_max = new_max;
        const float2 corr2 = make_float2(corr, corr);
#pragma unroll
        for (int si = 0; si < 4; ++si) {
          const int tile = si * 2 + group;
          if (tile < 7) {
#pragma unroll
            for (int r = 0; r < CH; ++r) {
              if (r < an) {
                float2 v[4];
                cvt4_f2(make_uint2(qv[si][r].x, qv[si][r].y), v[0], v[1]);
                cvt4_f2(make_uint2(qv[si][r].z, qv[si][r].w), v[2], v[3]);
                const float2 w2 = make_float2(wgt[r], wgt[r]);
#pragma unroll
                for (int c = 0; c < 4; ++c) {
                  acc2[si][c] = (r == 0) ? fma_x2(w2, v[c], mul_x2(acc2[si][c], corr2))
                                         : fma_x2(w2, v[c], acc2[si][c]);
                }
              }
            }
          }
        }
      }
      // ---- out-norm + epilogue (tpar == 0: one token per CTA) -------
      const float invs = __frcp_rn(run_sum);
      const float2 inv2 = make_float2(invs, invs);
      float2 sq2 = make_float2(0.f, 0.f);
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            acc2[si][c] = mul_x2(acc2[si][c], inv2);
            sq2 = fma_x2(acc2[si][c], acc2[si][c], sq2);
          }
        }
      }
      float sq = lane_tree_sum(__fadd_rn(sq2.x, sq2.y));
      if (lane == 0) warp_ssq[warp] = sq;
      bar_cons_sync(2);
      float tot = 0.f;
#pragma unroll
      for (int w = 0; w < 8; ++w) tot = __fadd_rn(tot, warp_ssq[w]);
      const float orr = rsqrtf(__fadd_rn(__fmul_rn(tot, INVH), eps));
      const float2 orr2 = make_float2(orr, orr);
      float2 owq[4][4];
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) tm05_ld8(gow + si * 8, owq[si]);
      }
      tm05_wait_ld();
      // FINAL TMEM read complete: release the owner warp's dealloc and
      // continue the FP32 epilogue without the block-wide barrier.
      bar_dealloc_arrive();
#pragma unroll
      for (int si = 0; si < 4; ++si) {
        const int tile = si * 2 + group;
        if (tile < 7) {
          uint4 o4;
#pragma unroll
          for (int c = 0; c < 4; ++c) {
            __nv_bfloat162 b = __float22bfloat162_rn(mul_x2(mul_x2(acc2[si][c], orr2), owq[si][c]));
            reinterpret_cast<unsigned*>(&o4)[c] = *reinterpret_cast<unsigned*>(&b);
          }
          reinterpret_cast<uint4*>(out + (long long)t * H)[tile * 128 + tig] = o4;
        }
      }
    }
  }
  pdl_launch_dependents();
}
// R105 (tuning): bounded instantiation — force device-side
// emission of the NSRC=9 static dealloc-early specialization
// (chtgd_kernel<8,5,1,200>, the static grid=T clone of impl134 chtmd —
// same 384-thread TMA-ring/TMEM pipeline, same named-barrier-9 dealloc
// handoff, static token = blockIdx.x with grid = T replacing chtmd's
// persistent grid-stride loop) so a host function pointer can be formed
// for the preres route table (R62 lazy-instantiation lesson).
template __global__ void chtgd_kernel<8, 5, 1, 200>(const bf16*, const bf16*, const bf16*,
                                                    const bf16*, bf16*, int, long long, float);

// ------------------------------------------------------------------ chts1 ---
// impl120 (development tuning, opt-in via K3_IMPL=120, NVB==8
// only): chtm's dataflow collapsed to ONE chunk per token — CH=9 (the whole
// token's 8 bank rows + the prefix row), NS=1 (single 126KB smem slot). R87
// NCU re-confirmed mid-T chtm is consumer-rendezvous-limited, not roofline
// (barrier stall 2.18-2.20 warps/issue-active, wait 1.07, DRAM 59-61%): this
// variant halves the per-token fold rendezvous count (two chunk score-fold
// barriers -> one) while keeping producer overlap.
// Structure deltas vs chtm_kernel<8,5,1,200>:
//   (a) one TMA chunk per token: one expect_tx (+9 rows), one bar_f wait,
//       one bar_e release per token; NS=1 ring keeps the smem budget at
//       9*ROWB = 126KB (+ reductions/TMEM slot), occupancy 1.
//   (b) pass A (score) streams rows r-major: ONE uint4 in flight per (r,si)
//       pair, convert + 2x2 packed FMA, discard. No qv[4][CH] array (that
//       would be 144 regs at CH=9 and spill at the 200 cap); rms2/dot2 are
//       the only persistent pass-A state (36 regs). The per-row arithmetic
//       chain (si asc, c asc, fma_x2) is bit-identical to impl87, so every
//       logit value is bit-identical to impl87's; only the softmax rescale
//       path changes (single-pass max instead of per-chunk online corr ->
//       same FP32 tolerance class, not bit-identical output).
//   (c) bar_e arrives right after pass A (the single slot's LAST smem read),
//       so the producer's token-t+1 TMA rides the fold + mixture + epilogue.
//       The mixture therefore CANNOT re-read smem: pass B re-reads the rows
//       from GLOBAL memory, which is L2-hot because the TMA g2s just filled
//       L2 with exactly these lines (18.9MB of live row data across 152
//       CTAs vs >100MB L2). Pass-B accumulation order per (si,c) is still
//       ascending r — same order as impl87's in-chunk mixture.
//   (d) register-resident per-token state: cwq (drained once per token,
//       tcgen05.ld issued BEFORE mbar_wait so the TMEM latency rides the
//       TMA rendezvous), wgt[9] across the fold barrier — combined peak
//       stays far under the 200-reg ASYM budget (zero stack spills
//       required by the retention rule; cuobjdump-verified).
//   (e) fold buffers need no chunk parity (one fold per token; token t+1's
//       fold write is ordered after token t's fold reads by the out-norm
//       barrier, and after its ssq reads by the next fold barrier).

// ----------------------------------------------------------------- chts1h ---
// impl121 (development tuning, opt-in via K3_IMPL=121, NVB==8
// only): chts1 (CH=9/NS=1 single-fold) HYBRID — retains ONE source row in
// registers for the mixture while re-reading only the remaining rows,
// targeting the measured impl120 long-scoreboard regression (0.74 -> 2.48
// warps/issue-active at unchanged DRAM bytes) WITHOUT restoring the second
// score-fold barrier.
// Structure deltas vs chts1_kernel (math-order deltas: NONE — the per-(si,c)
// pass-B accumulation order stays r ascending, so outputs are bit-identical
// to chts1_kernel given identical inputs; verified level2/r89_smoke.py):
//   (a) pass A retains the prefix row's (r=8) per-thread uint4 slices in
//       registers (ret[4], 16 regs group0 / 12 group1), captured at their
//       last natural use so the cwq[4][4] (32 regs) lifetime ends exactly as
//       ret begins; pass B computes that row's mixture contribution with
//       zero gmem traffic.
//   (b) pre-fold prefetch: right after the bar_e release, issue L2 loads
//       for rows r=0..1 of the current token into pf[2][4] (32 regs). They
//       have no dependency on the scores; the fold rendezvous + softmax
//       dependency chain rides over the ~270 ns L2 latency, so pass B's
//       first two rows are register hits and only rows 2..7 stream gmem.
//   (c) register budget: consumers are launch-bound to floor(65536/384)=
//       168 regs; ret (16) overlaps cwq's death and pf (32) is dead by r=2
//       of pass B, so the peak stays at the chts1 level — cuobjdump
//       STACK:0 required by the retention rule.

// ------------------------------------------------------------------ onlx ---
// impl122 (development tuning, opt-in via K3_IMPL=122, NVB==8
// only): the reference production online-softmax topology, qualitatively
// different from every prior 288-thread candidate (cv2/cv3 were NC=2/NC=3
// occupancy-2 with setmaxnreg and two-pass softmax; this is occupancy 1,
// NC=4 depth-2, single-read online softmax):
//   * 288 threads = 1 TMA producer warp + 8 consumer warps; the consumers
//     form two 128-thread warpgroups; group g owns K tiles g, g+2, g+4 and
//     half of tile 6 (per-thread VEC=8 bf16 slots per tile, 4 for the tile-6
//     half; 28 fp32 accumulator elements per thread).
//   * depth-2 ring of NC=4-row chunks staged by cp.async.bulk (8 rows in
//     flight = a token's whole bank; the 9th row, the appended prefix, rides
//     the last chunk alone); per-slot ready/consumed mbarrier pairs with
//     phase parity from a continuous global chunk counter gci.
//   * pass A converts each chunk row to fp32 ONCE and stores it into TMEM
//     (256 columns, 128 per warpgroup, thread<->TMEM-row 1:1), taking the
//     row's sumsq and cw-dot partials from the same registers; pass B
//     reloads the rows from TMEM into the mixture accumulator.
//   * the softmax is ONLINE: each chunk's <=4 logits update a running max
//     with an exp2f rescale of the accumulator, so every row is read
//     exactly once and there is no separate mixture pass over smem/gmem.
//   * epilogue exploits (mixed = acc / s): out = acc * rsqrt(mean(acc^2) +
//     eps*s^2) * ow — one extra 256-thread reduce + one store pass.
//   * cw and out_weight live in per-thread registers across the whole
//     persistent token loop (56 regs total); grid = min(T, nsm); one fused
//     launch; same PDL discipline as every other route.
// Numeric class: NC=4 chunk-folded FP32 partials + online rescale differ
// from impl87's exact reference lowering (cv2/cv3 did the same kind of
// regroup) but sit in the same tolerance class as the fp64 reference.
// Retention rule (directive): beats impl87 on order-reversed cold-L2 A/B at
// T=512/1024/2048/4096/8192 or stays opt-in only.
struct OnlxPlan {
  alignas(16) unsigned long long bar_ready[2];     // per ring slot (1 producer arrival)
  alignas(16) unsigned long long bar_consumed[2];  // 8 consumer-warp arrivals
  alignas(16) float2 ws_stats[2][8][4];            // chunk-fold partials (gci parity)
  alignas(16) float2 ws_out[8];                    // out-norm partials
  unsigned tmem_base;
  unsigned _pad;
};

// ------------------------------------------------------------------- rx5 ---
// impl129 (development tuning, opt-in via K3_IMPL=129, NVB==8
// only): the upstream tuning-table configuration (CHUNK_ROWS=5, OCCUPANCY=1,
// CONSUMER_REGS=200) with producer/consumer setmaxnreg specialization — the
// one topology-config not covered by the failed NC=2 (R96), NC=3 (R83) and
// NC=4 (R81/R90) experiments. 384 threads: warpgroups 0/1 consume (8 warps,
// setmaxnreg.inc -> 200), warpgroup 2 produces — FOUR producer warps padded
// so setmaxnreg.dec -> 40 is issued by a whole aligned warpgroup (a single
// producer warp cannot legally issue setmaxnreg; that was the R81 deadlock
// root cause); only warp 8 lane 0 issues TMA. Depth-2 ring of 5-row chunks
// (rows 0..4 / 5..8, the prefix riding the tail chunk as the last row),
// TMEM 128 columns for the fp32 cw/ow stage, single-read chunk-resident
// rows (qv registers carry each chunk from scoring into the mixture),
// online softmax, fused out-norm epilogue. Deltas vs production
// chtm_kernel<8,5,1,200,2> (which shares the same ring/setmaxnreg skeleton
// — impl87 already IS this config in (chunk,occ,regs) terms):
//   * register rebudgeting happens INSIDE the PDL window: the setmaxnreg
//     dec/inc runs before cudaGridDependencySynchronize(), so a chained
//     launch's pool rebalance overlaps the predecessor's tail.
//   * softmax weights/correction in exp2f(x * LOG2E) form (the reference's
//     MUFU.EX2 idiom; same tolerance class as impl122/onlx).
//   * scalar-scale epilogue: out = acc * rsqrt(mean(acc^2) + eps * s^2) * ow
//     with NO per-element inv_sum pre-normalization of the accumulator —
//     algebraically identical to the reference semantics (the softmax
//     denominator cancels), saving the normalize pass; same formula class
//     as the verified impl122 epilogue.
// Reduction bookkeeping keeps chtm's proven parity double-buffered partial
// arrays: the reference's single-buffered warp partials rely on TMA latency
// to separate a fast warp's next-chunk writes from a slow warp's previous
// totals reads; double buffering removes that hazard at zero measured cost.
// Retention rule (directive): promote only on repeated order-reversed
// cold-L2 A/B wins vs impl87 at EVERY adjacent NVB=8 row T=512..9364.
struct Rx5Plan {
  alignas(16) unsigned long long bar_f[2];  // chunk-ready (producer tx)
  alignas(16) unsigned long long bar_e[2];  // consumed (256 arrivals)
  alignas(16) float warp_rms[2][8][5];      // score partials (parity)
  alignas(16) float warp_dot[2][8][5];
  alignas(16) float warp_ssq[2][8];  // out-norm partials (token parity)
  unsigned tmem_base;
  unsigned _pad;
};

// impl127/128 (development tuning, opt-in via K3_IMPL=127 grid=nsm
// / K3_IMPL=128 grid=2*nsm, NVB==8 only): the BOUNDED producer/consumer TMA
// pipeline — onlx's exact 288-thread topology (1 TMA producer warp + 8
// consumer warps, two 128-thread warpgroups, per-slot ready/consumed
// mbarrier pairs, grid-stride persistence, online softmax, fused out-norm)
// with the chunk width narrowed NC=4 -> NC=2, which bounds the in-flight
// smem to a depth-2 ring of two rows each (NUM_BUFS=4 rows, ~57.6KB vs
// onlx's ~114.7KB) and halves the TMEM V cache to 128 columns (64 per
// warpgroup). That is the reference production kernel's RELEASE_TMEM
// configuration: bounded smem+TMEM per CTA so two CTAs can co-reside; the
// R96 experiment measures the nsm vs 2*nsm grid cutover with controlled
// cold-L2 A/B. Arithmetic is the same chunk-folded FP32 partial + online
// exp2f-rescale reduction order family as onlx (identical formula, smaller
// chunk width -> same tolerance class vs the fp64 reference; NOT bit-
// identical to impl87, same as impl122). Retention rule (directive):
// retained only if controlled A/B improves every adjacent large-T fixed row.
struct BndpPlan {
  alignas(16) unsigned long long bar_ready[2];     // per ring slot (1 producer arrival)
  alignas(16) unsigned long long bar_consumed[2];  // 8 consumer-warp arrivals
  alignas(16) float2 ws_stats[2][8][2];            // chunk-fold partials (slot, warp, row)
  alignas(16) float2 ws_out[8];                    // out-norm partials
  unsigned tmem_base;
  unsigned _pad;
};

// ------------------------------------------------------------------ hyb ----
// impl123 (development tuning, opt-in via K3_IMPL=123, NVB==8
// only): the R90 onlx deltas (exp2f online softmax + fused out-norm
// cancellation) transplanted onto impl87's PRODUCTION dataflow, keeping
// everything R90 proved load-bearing:
//   * 384 threads = 8 consumer warps + 4 ASYM producer warps (setmaxnreg
//     40/200) = 12 resident warps/SM (the parity that beat every
//     288-thread/9-warp geometry in R81/R83/R90);
//   * impl87's register-resident V mixture: each chunk row is read from the
//     smem ring ONCE into qv uint4 registers, the score FMA runs from those
//     registers, and the SAME registers feed the mixture (no TMEM-V stash,
//     no smem re-read — the R79/R88/R89/R90 retention);
//   * TMEM-staged cw/out_weight slices (impl87's R43 retention) and the
//     NS=2/CH=5 depth ring with impl87's exact producer mbarrier
//     discipline;
//   * the same per-chunk bar_cons_sync(1) fold rendezvous — barrier-count
//     reduction at this dataflow was falsified by impl106 (R66) and the
//     barrier-axis is closed (R75); only the ARITHMETIC changes.
// Deltas vs chtm_kernel<8,5,1,200> (the onlx transfers):
//   * softmax weights/correction use exp2f(x*LOG2E) (onlx form; the SM103
//     2x MUFU exp2 path) instead of __expf(x); logit values are unchanged,
//     weights sit in impl122's proven tolerance class (worst 3.125e-2 at
//     the 6.25e-2 gate);
//   * the epilogue drops __frcp_rn(run_sum) AND the acc*invs normalize
//     pass: out = acc * rsqrt(mean(acc^2) + eps*s^2) * ow with s =
//     run_sum — the softmax denominator cancels exactly (mixed = acc/s ⇒
//     mixed*rsqrt(mean(mixed^2)+eps) = acc*rsqrt(mean(acc^2)+eps*s^2));
//     the sq2 fold accumulates over the raw accumulator.
// Retention rule (directive): strictly opt-in until it beats impl87 on
// order-reversed cold-L2 A/B at T=512/1024/2048/4096/8192.

// ------------------------------------------------------------------ chtmt ---
// impl113 (development tuning, opt-in via K3_IMPL=113, NVB==8
// prototype): chtm_kernel dataflow with the per-chunk V rows converted to
// FP32 ONCE in the score phase and cached in TMEM; the mixture phase reads
// them back from TMEM instead of re-running cvt4_f2 on the live qv[4][CH]
// register array (impl87). This is the one untried structural distinction in
// the public vLLM fused forward kernel from the curated reference list:
// its fwd_prod_v2 stores each chunk's converted
// FP32 rows into TMEM (tcgen05.st) and pass B reloads them (tcgen05.ld);
// impl87's TMEM use until now cached only cw/out_weight.
// FP semantics: the stored FP32 bits are exactly cvt4_f2's output, reloaded
// unchanged; score partials, fold order, online softmax, and the (si,r,c)
// mixture FMA order are unchanged -> expected bit-identical to
// chtm_kernel<8,5,1,200>.
// Structure deltas vs chtm_kernel:
//   (a) pass A streams each (si slice, r row) uint4 straight into cvt +
//       tcgen05.st + the rms/dot FMAs and discards it; the live qv[4][CH]
//       register array (~80 regs held across the fold barrier) disappears.
//   (b) pass B reloads each (si,r) FP32 quad-pair from TMEM in per-si
//       batches (CH tcgen05.ld.x8 + one wait::ld) instead of converting.
//   (c) TMEM layout: existing cw/ow staging keeps cols 0..127 (two groups x
//       64); the V cache takes cols 128..447 (group * GVC, GVC = 4*CH*8 =
//       160 for CH=5). Alloc grows 128 -> 512 cols (power-of-2; NOCC=1 so
//       no other CTA competes for TMEM on the SM).
//   (d) producer, barriers, ring, score fold, softmax, epilogue: unchanged.
// R79 RESULT — FALSIFIED, not dispatched anywhere (opt-in only):
//  correctness: bit-identical to chtm_kernel<8,5,1,200> on all 12 probed
//   (T,NVB=8) cases incl. T=9364 and straddles 255/257 (t113_check.py);
//  interleaved chained-stream L2-flushed A/B (ab113.py, 15 alternating
//   draws, medians): +4.02% T=256, +3.79% T=1024, +2.72% T=2048,
//   +1.45% T=4096, +0.93% T=8192 (never better);
//  NCU isolated cold-L2 (--cache-control all --clock-control none, 3-probe
//   medians): +2.7% T=256 (12,096 vs 11,776ns), +4.2% T=1024 (28,064 vs
//   26,944), +3.7% T=2048 (49,696 vs 47,904), +5.2% T=4096 (91,328 vs
//   86,816), +3.2% T=8192 (170,912 vs 165,632);
//  launch__registers_per_thread 168 both (the qv[4][CH] freeing does not
//   lower the static allocation, and at NOCC=1 occupancy is unchanged
//   anyway) — the tcgen05.st/ld round-trip + wait::st per chunk is a pure
//   added cost against an already register-resident mixture. The vllm
//   fwd_prod_v2 design wins in ITS setting because pass B there would
//   otherwise re-read smem; here pass B already reads registers, so the
//   TMEM cache has no traffic to eliminate. Do not re-propose per-chunk
//   TMEM V caching for the chtm/chp dataflow.

// ------------------------------------------------------------------- cv2 ----
// impl114 (development tuning, opt-in via K3_IMPL=114, NVB==8
// only) — FALSIFIED development in the exact directed retention protocol.
// Idle-GPU order-reversed chained wall A/B vs impl87 (medians of 11):
// T=4096 +10.6%, T=8192 +11.8%, T=9364 +12.4% (loses all three). NCU
// isolated cold-L2 detailed set @ T=8192: 195.0us vs 167.8us (+16.2%);
// 2 CTAs/SM achieved (occupancy limits 2/2 regs+smem, 18 warps/SM vs 12)
// but smsp__inst_executed 123.2M vs 93.7M (+31%) — CH=5->2 multiplies
// per-chunk fixed costs (5x bar_cons_sync(1), 5x fold, 5x acc2 rescale,
// 5x TMEM V st/ld rounds) by 2.5x, which the extra 6 warps/SM cannot
// refund in a ~7.4TB/s DRAM-nearly-saturated regime. Consumer
// setmaxnreg.inc is architecturally deadlocked in this shape: the single
// producer warp releases registers only on SMSP0 while SMSPs 1-3 host
// consumers only — per-SMSP release/demand balance fails and
// cv2_kernel<104> hung the GPU (observed development; the 384-thr ASYM chtm
// survives its inc because four producer warps cover all four SMSPs).
// vllm-topology (NC=2 / 288-thr / occ2) large-T NVB=8 axis closed;
// dispatch reverted to impl87 for all nvb=8 T>=152 — impl114 runs
// nowhere by default. Kept below for reference (dec-only CREGS=0; the
// <104> instantiation must not be launched).
//
// Directive build-out notes: 288 threads (ONE TMA producer warp + eight
// consumer warps in two 128-thread groups), NC=2 rows per chunk on an
// NS=2 smem ring (four row buffers ≈ 57.7KB), producer setmaxnreg dec 24,
// persistent grid capped at 2 co-resident CTAs/SM for the T>=4096 NVB=8
// band. Distinct from every prior falsified axis: impl105 only widened
// the GRID CAP of the 384-thr/CH=5 chtm (143.5KB smem could never
// co-reside 2 CTAs); impl88/88r were CH=3 occ-2 probes tested only at
// T<=2048; impl113 kept qv AND added TMEM (double work) — here TMEM-V
// *replaces* qv (single work) as the register-budget enabler; impl109
// widened the unrelated wpr8 family. Revision history within development:
// (A) dec-only + qv[4][CH] register mixture spilled 54 slots (REG:96
// STACK:216), +82..89% wall vs impl87; (B, current) pass A converts
// rows to fp32 once, stores them to TMEM cols 128..255 (4 slices x 2
// rows x 8 fp32 per group), pass B reads them back — STACK:40, +10..16%
// loss recorded above. TMEM total: 128 cols cw/ow + 128 cols V per CTA
// = 512/512 with 2 resident CTAs. CH=3 (exactly tiling R=9) is TMEM-
// infeasible (needs 320 cols/CTA at occ2). Production arithmetic notes:
// per-row rms/dot fold order and per-thread mixture fma order match
// impl87; the 5-chunk online-softmax regroups rescales, so outputs sit
// in the same FP32 tolerance class but are not bit-identical to impl87.

// ------------------------------------------------------------------- cv3 ----
// impl116 (development tuning, opt-in via K3_IMPL=116, NVB==8
// only): retuned cv2/iml114 for the NVB=8 mid-T band (T=128/256/512 A/B
// against the pdlr/chtm routes). The development cv2 loss was instruction
// count (+31% vs chtm): CH=5->2 multiplied per-chunk fixed costs (fold,
// bar_cons_sync, acc2 rescale, TMEM rounds) by 2.5x in a DRAM-nearly-
// saturated regime. Mid-T is latency-bound, not DRAM-bound, so this
// variant keeps the two-resident-CTA topology and retunes costs/budgets:
//   (a) CH=3 rows/chunk -> NCH=3 exact 3x3 tiling of R=9: fixed costs 5x
//       -> 3x per token; smem ring NS=2 x 3 rows = 86KB/CTA (occ-2 safe).
//   (b) consumer register-budget retune: TMEM holds ONLY cw (64 cols/CTA,
//       staged once per kernel) + V (192 cols/CTA, 2 groups x 4 slices x
//       3 rows x 8); 256 cols/CTA x 2 CTAs = 512/512 TMEM. ow leaves TMEM
//       entirely — read from gmem/L2 once per token in the epilogue (4
//       fewer TMEM ld8 + their waits per token, no ow staging pass).
//   (c) no setmaxnreg.inc (R81: consumer inc deadlocks with the single
//       SMSP0 producer warp); producer keeps dec-24; consumers run inside
//       the launch_bounds(288,2) ~112-reg pool with acc2[4][4] resident.
// Fold order, per-thread mixture fma order and epilogue math mirror cv2,
// so outputs sit in the same FP32 tolerance class as impl87/cv2 (the
// 3-chunk online softmax regroups rescales — not bit-identical).

// ------------------------------------------------------------------- xep ----
// impl115 (development tuning, opt-in via K3_IMPL=115, NVB==8
// prototype): cross-token role split on top of chtm's exact single-read
// TMA row staging. The persistent impl87 inner loop serializes each token's
// out-norm epilogue (invs scale, sq fold, orr, ow multiply, bf16 store)
// AFTER that token's last chunk fold; the next token's chunk data is
// already staged in the smem ring by then, but the SAME 8 consumer warps
// must finish the epilogue before touching it. This kernel splits the 8
// consumer warps into two 4-warp teams that pipeline ACROSS tokens:
//   team S (warps 0-3): per token, every chunk's rms/dot partials and the
//     cross-warp fold (identical element->thread mapping per tile as
//     impl87's two groups merged: tig covers tiles 0..6), then the full-
//     row softmax weights wgt[r] = exp(lg[r]-max) and invs = rcp(sum).
//     S holds NO mixture accumulator: it publishes (wgt[R], invs) into a
//     small smem box per token parity and arrives on bar_ready[tpar]
//     (128 arrivals).
//   team E (warps 4-7): per token, waits bar_ready[tpar], reads the box,
//     computes the single-pass mixture acc = sum_r wgt[r]*row[r] by
//     RE-READING the token's rows from the smem ring (address bank and
//     prefix directly via the producer ring; nothing new materialized in
//     gmem), then the out-norm (team-local 4-warp sq fold on named
//     barrier id 2) and the bf16 store. E is the ONLY bar_e arriver
//     (count 128): a chunk slot is released once E has consumed it.
// Ring NS=3 (was 2) so S can run one token ahead of E. Overrun safety by
// ring induction: producer cannot fill chunk j until E released chunk
// j-NS, and E reads the parity box BEFORE arriving on bar_e for its first
// chunk, so S's next write to the same parity box (two grid-stride tokens
// later) is ordered strictly behind E's read of the previous one.
// FP semantics vs impl87: per-thread partials cover 56 elems (both old
// groups' tiles merged), cross-warp fold sums 4 (not 8) warp partials,
// and the mixture is single-pass (acc = sum_r exp(lg[r]-max)*row[r],
// final *invs) instead of online corr-rescaled -- same math, same FP32
// tolerance class as impl114, not bit-identical.
// No TMEM and no tcgen05 anywhere: cw/ow live in per-thread registers
// (7 tiles x 4 float2 = 56 regs each side); S peak ~130 regs, E peak
// ~155 regs under the same dec-40/inc-200 setmaxnreg split as impl87
// (producer warps 8-11 keep 4-warpgroup SMSP coverage, so inc is legal).
// Retention rule (directive): controlled A/B wins vs impl87 at
// T=512/1024/2048/4096/8192 before any dispatch promotion.
// R82 RESULT — FALSIFIED: correct at every probed shape (incl. off-suite
// straddles T=1/144/296/511/513/9364, maxabs <= 3.125e-02 = half-gate),
// but the idle-GPU rotating-order L2-flushed chained A/B loses at ALL five
// directed shapes: +22.5/+24.2/+25.4/+28.6/+30.0% (medians of 11) vs
// impl87 at T=512/1024/2048/4096/8192. NCU detailed @T=8192: 216.6us vs
// 165.7us (+31%); DRAM read 61.6% vs 80.5% of peak (5.39 vs 7.04 TB/s,
// producer starved: bar_e slots are now gated on E finishing the whole
// mixture of a token, collapsing the producer lead the NS=3 ring was
// meant to buy); stall mix shifts from impl87's barrier 31.2%/wait 18.0%
// to long_scoreboard 27.5%/no_instructions 12.0%. The role split needs a
// double smem row pass (S score + E mixture) and its handoff depth 1
// token cannot hide a full chunk fill. Opt-in only; dispatch unchanged.

// ------------------------------------------------------------------ chtm1f ---
// impl106 (development, opt-in via K3_IMPL=106, NVB==8 only): deferred single
// fold. development NCU on impl87's chtm_kernel<8,5,1,200,2> at T=512 NVB=8
// (gpu__time_duration 19.9us, DRAM 42-44%, occupancy 19% at 1 CTA/SM)
// attributes 31.1% of warp issue-stall cycles to CTA barrier waits — the two
// per-chunk fold barriers (bar_cons_sync(1)) plus the per-token out-norm
// barrier (bar_cons_sync(2)) leave serial bubbles that the single resident
// CTA cannot hide. This variant removes ONE of the two fold barriers per
// token: chunk partials for BOTH chunks are stored to the warp_rms/warp_dot
// parity slots first, then a single bar_cons_sync(1) publishes them, then
// the online softmax + mixture runs chunk-by-chunk in the ORIGINAL order
// (identical per-element FP chain: same warp partials, same fold reads,
// same run_max/corr/wgt sequence, same acc2 fma order per si/r/c lane) so
// the output is bit-identical to impl87. Structure deltas vs chtm_kernel:
//   (a) chunk slots are reclaimed with impl87's exact per-thread arrive at
//       count 256, but only AFTER the fold barrier publishes the partials
//       (the deferred mixture re-reads chunk0 from smem, so its slot must
//       survive the fold). Release at the fold barrier, count 256, keeps
//       one phase completion per ring reuse: with NCH=2/NS=3 there is
//       exactly one ring reuse between two releases of the same slot, so
//       no 256-arrival phase can straddle a reuse.
//   (b) chunk1 (last chunk) keeps its qv registers into the mixture exactly
//       like impl87 (no smem re-read needed for it).
//   (c) NS=3 ring (3 x 5 x ROWB = 215040B + bookkeeping, still 1 CTA/SM;
//       NS=4's 286KB exceeds the 227KB opt-in limit).
// Opt-in only; dispatched nowhere by default. Requires NCH <= 2 (parity
// slots [2][8][CH]); NVB=8/CH=5 gives NCH=2.
// R66 RESULT — FALSIFIED: bit-identical to impl87 at every probed T
// (1/2/153/512/513/1024) but SLOWER on the tuning's interleaved
// cold-L2 A/B: T=512 34.82us vs 31.97us (-8.9%), T=1024 48.70us vs
// 43.01us (-13.2%). The deferred chunk0 release (post out-norm barrier)
// stalls the producer's refill of that slot at (t+1).c1 — with NS=3 the
// ring has only one chunk of slack and the deferred release hands it
// back one token late, so the producer TMA becomes the critical path
// and the fold-barrier saving is swamped. Do not re-attempt deferred
// ring-release / fewer-per-token-fold variants on this dataflow without
// a deeper ring that fits smem (NS=4 at CH=5 exceeds 227KB).

// impl92 (K3_IMPL=92, NVB==8 opt-in): chtm_kernel with a tree-shaped
// cross-warp score reduction. Same ring/TMEM/dispatch config as impl87;
// only the post-barrier rms/dot fold changes (8-deep serial fadd chain on
// lanes<an -> width-8 shuffle tree over CH*8 lanes).

// ----------------------------------------------------------------- chtm2 ----
// development tuning (opt-in via K3_IMPL=88, NVB==8 only): the
// occupancy-2 redesign of chtm. The R50 impl88 attempt (chtm_kernel<8,3,2,104>)
// achieved 2 resident CTAs but lost because the qv[4][CH] live array (12 uint4
// = 48 regs/thread held across the whole chunk) forced 1KB/thread stack
// spills. chtm2 STREAMS row slices through the score phase: only one row's
// four uint4 slices are live at a time; the mixture phase then RE-READS the
// rows from the smem ring slot (which is still pinned until after mixture),
// so no per-row register array is kept. Ring-slot release (bar_e arrive)
// moves to after the mixture consumes the slot. 288 threads (8 consumer
// warps + 1 producer warp), launch_bounds(288, NOCC=2) -> <=112 regs/thread,
// NO setmaxnreg (R50 root-caused the per-CTA pool hazard and 288 threads do
// not need it). Smem: 2*3*14336B ring + barriers/reductions < 88KB, so two
// CTAs fit the ~227KB SM smem budget.

// ------------------------------------------------------------------ cpx ----
// impl 86 (development opt-in): chp's production-style TMA ring backbone
// (producer warp + 2-stage mbarrier ring + setmaxnreg split) with impl43's
// BIT-EXACT consumer arithmetic: one warp scores each full row with
// row_score_packed's exact chains (4*lane+128*m element pattern, rq[28]
// staging); the softmax butterflies run redundantly per warp (identical
// deterministic order); the mixture uses impl43's j&3-banked fp32x2 chains
// with the exact (0+1)+2)+3 fold and true probs (no online rescaling); the
// out-norm ssq fold, rsqrt scale, and mul(mul(mv, orr), ow) epilogue copy
// impl43's op order. The only deviation from impl43's bitwise tape is the
// out-ssq warp-partition fold (8 warps ascending vs impl43's 10), a ~1ulp
// scalar. Rows are TMA-staged once; the mixture re-reads them from smem
// after probs are known (ring slots recycle only after mixture consumption).

// --------------------------------------------------------------- ct2 ----
// impl 124 (development tuning, opt-in via K3_IMPL=124, NVB==8
// only): persistent TWO-tokens-per-CTA kernel with independent consumer
// warp subsets. Warps 0-3 (team A) own token 2p and warps 4-7 (team B)
// own token 2p+1 of each grid-stride token pair p; each team runs the
// COMPLETE fused path for its token independently — per-row FP32 ssq+dot
// score (warp-per-row inside the team), in-team softmax with max
// subtraction, FP32 weighted mixture, final FP32 RMS out-norm, and a
// single BF16 store. The teams share ONLY the CTA-resident fp32
// cw/out_weight smem stage (staged once per CTA, reused for every pair).
// Distinct from the falsified R39 cross-token score/epilogue splits
// (impl82/83): no stage is shared or interleaved across tokens; the only
// cross-token coupling is the block-wide __syncthreads rendezvous.
//   Data movement: each row is read once from gmem in the score phase and
// re-read once in the mixture phase (the token-pair window re-read is
// L2-resident — same re-read pattern measured by the R88/R89 probes).
// grid = min(ceil(T/2), nsm); pairs are strided by gridDim.x (persistent).
// For the odd-T tail, team B duplicates token T-1 (identical math and
// identical BF16 stores, so the re-store is benign). PDL-wrapped.

