static void preres_fill_std(PreresRoute* tbl, bool tmem) {
  for (int nvb = 1; nvb <= 8; ++nvb) {
    PreresRoute& r = tbl[nvb];
    switch (nvb) {
      case 1:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<1, 2, 2, 0>
                          : (decltype(r.std_kern))chp_kernel<1, 2, 2, 0>;
        break;
      case 2:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<2, 4, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<2, 4, 1, 200>;
        break;
      case 3:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<3, 4, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<3, 4, 1, 200>;
        break;
      case 4:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<4, 5, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<4, 5, 1, 200>;
        break;
      case 5:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<5, 3, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<5, 3, 1, 200>;
        break;
      case 6:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<6, 4, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<6, 4, 1, 200>;
        break;
      case 7:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<7, 4, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<7, 4, 1, 200>;
        break;
      default:
        r.std_kern = tmem ? (decltype(r.std_kern))chtm_kernel<8, 5, 1, 200>
                          : (decltype(r.std_kern))chp_kernel<8, 5, 1, 200>;
        break;
    }
    const int ch = (nvb == 1) ? 2 : (nvb == 4 || nvb == 8) ? 5 : (nvb == 5) ? 3 : 4;
    r.nthreads = (nvb == 1) ? 288 : 384;
    r.grid_occ = (nvb == 1) ? 2 : 1;
    r.smem = (size_t)2 * ch * ROWB + 32 + (size_t)(32 * ch + 16) * 4 + (tmem ? 16 : 0);
    cudaFuncSetAttribute((const void*)r.std_kern, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)r.smem);
  }
}

static void preres_init() {
  int dev = 0;
  cudaGetDevice(&dev);
  cudaDeviceGetAttribute(&g_preres_nsm, cudaDevAttrMultiProcessorCount, dev);
  preres_fill_std(g_route85, false);
  preres_fill_std(g_route87, true);
  const int TFSMB = MAXR * H * (int)sizeof(bf16) + H * (int)sizeof(bf16) +
                    (MAXR + 32) * (int)sizeof(float) + 9 * 224 * (int)sizeof(float2);
  for (int R = 1; R <= 9; ++R) {
    PreresRoute& r = g_routeF[R];
    r.nthreads = 7 * 32;
    r.grid_occ = 4;
    r.smem = (size_t)TFSMB;
    switch (R) {
      case 1:
        r.lean_kern = leanF_kernel<1>;
        break;
      case 2:
        r.lean_kern = leanF_kernel<2>;
        break;
      case 3:
        r.lean_kern = leanF_kernel<3>;
        break;
      case 4:
        r.lean_kern = leanF_kernel<4>;
        break;
      case 5:
        r.lean_kern = leanF_kernel<5>;
        break;
      case 6:
        r.lean_kern = leanF_kernel<6>;
        break;
      case 7:
        r.lean_kern = leanF_kernel<7>;
        break;
      case 8:
        r.lean_kern = leanF_kernel<8>;
        break;
      default:
        r.lean_kern = leanF_kernel<9>;
        break;
    }
    cudaFuncSetAttribute((const void*)r.lean_kern, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         TFSMB);
  }
  g_route108.std_kern = wpr8_kernel;
  g_route108.nthreads = 288;
  g_route108.grid_occ = 0;
  g_route108.smem = 0;
  // development: pdlr (impl112) PDL-early lean routes (opt-in / candidate).
  g_route112[0].std_kern = pdlr_kernel<4>;
  g_route112[1].std_kern = pdlr_kernel<8>;
  for (auto& rr : g_route112) {
    rr.nthreads = 288;
    rr.grid_occ = 0;
    rr.smem = 0;
  }
  // development: cv2 (impl114) large-T NVB=8 candidate route (opt-in). 288
  // threads, NC=2/NS=2 ring (~57.7KB smem), grid capped at 2*nsm so two
  // CTAs co-reside per SM.
  // development: impl119 producer-side L2-lookahead route (opt-in), NVB==8.
  // development: impl120 single-chunk (CH=9/NS=1) chts1 route (opt-in),
  // NVB==8. One fold barrier per token; pass-B rows re-read from L2-hot
  // gmem so the single slot releases after pass A.
  // development: impl121 chts1h hybrid route (opt-in), NVB==8. chts1 with
  // the prefix row retained in registers for the mixture plus a pre-fold
  // prefetch of rows 0..1; bit-identical outputs to chts1 (level2/
  // r89_smoke.py).
  // development: impl122 onlx route (opt-in), NVB==8. 288 threads (1 TMA
  // producer + 8 consumers), depth-2 NC=4 chunk ring (8 rows in smem),
  // 256 TMEM columns, online softmax, occupancy 1, grid = min(T, nsm).
  // development: impl123 hyb route (opt-in), NVB==8. 384 threads, impl87's
  // register-V dataflow + onlx's exp2f online softmax and fused out-norm
  // epilogue. Same smem geometry as the nvb=8 chtm route.
  // development (tuning): impl125 lean NSRC=5 CTA-per-token
  // route, NVB==4 small-T band. lean5_kernel<256,true> (see the kernel
  // definition comment): flat 256-thread block, grid = T (one CTA per
  // token), no TMA producer / mbarrier ring / setmaxnreg, exactly two
  // __syncthreads per token, PDL hooks retained, identical FP32 math and
  // fold order to the R84 candidate it is routed through now. The R84
  // retention test A/B'd against chp(impl85) — whose whole family was
  // later overturned at nvb==4 by impl87 — so the R84 result does not
  // bound this route against the current production kernel; this round's
  // A/B is the directed evidence.
  (size_t)5 * ROWB + (size_t)(2 * 8 * 5 + 8) * 4 + 16;
  // development (tuning): impl126 static CTA-per-token NSRC=5
  // route, NVB==4 small-T band. chtg_kernel<4,5,1,200> — impl87's exact
  // nvb=4 kernel structure and smem geometry with the persistent token
  // loop replaced by token = blockIdx.x; grid = T (grid_occ 0).
  g_route126.std_kern = chtg_kernel<4, 5, 1, 200>;
  g_route126.nthreads = 384;
  g_route126.grid_occ = 0;
  g_route126.smem = (size_t)2 * 5 * ROWB + 32 + (size_t)(32 * 5 + 16) * 4 + 16;
  cudaFuncSetAttribute((const void*)g_route126.std_kern,
                       cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g_route126.smem);
  // development (tuning): impl130 chtgp route (opt-in), NVB==4.
  // chtg_kernel<4,5,1,200>'s exact geometry/smem with the single static
  // chunk instance emitted via compile-time-unrolled predication (see the
  // kernel definition comment): no runtime an tests, no divergent logit
  // ownership branch. Bit-identical outputs to impl126 by construction.
  // development (tuning): impl131 chtgd route (opt-in), NVB==4.
  // chtg_kernel<4,5,1,200>'s exact geometry/smem with the TMEM dealloc
  // moved off the post-__syncthreads serial tail via the named-barrier-9
  // handoff (see the kernel definition comment). Bit-identical outputs to
  // impl126 by construction.
  g_route131.std_kern = chtgd_kernel<4, 5, 1, 200>;
  g_route131.nthreads = 384;
  g_route131.grid_occ = 0;
  g_route131.smem = (size_t)2 * 5 * ROWB + 32 + (size_t)(32 * 5 + 16) * 4 + 16;
  cudaFuncSetAttribute((const void*)g_route131.std_kern,
                       cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g_route131.smem);
  // development (tuning): impl132 chtgd3 route, NVB==2 band.
  // chtgd_kernel<2,3,1,200>: the development dealloc-early handoff on an
  // NSRC=3 static CTA-per-token dataflow (one CH=3 chunk per token;
  // smem = 2*3-row ring + mbars + CH-scaled partial arrays + tm_slot).
  // development (probe, same directive): impl133 chp3 — the PRODUCTION
  // family's NSRC=3-native chunk geometry (chp_kernel<2,3,1,200>:
  // identical chp dataflow/TMEM-free staging/persistent grid-stride,
  // CH=3 native chunk instead of the production CH=4>R=3 over-wide
  // chunk). Rationale: for NVB==2 (R=3) every per-chunk unrolled loop
  // in the consumer (qv register arrays, per-row rms/dot partials,
  // cross-warp fold width, logit lane span) is CH-wide; CH=3 removes
  // 1/4 of that instruction volume at the same math/fold order.
  g_route133.std_kern = chp_kernel<2, 3, 1, 200>;
  g_route133.nthreads = 384;
  g_route133.grid_occ = 1;
  g_route133.smem = (size_t)2 * 3 * ROWB + 32 + (size_t)(32 * 3 + 16) * 4;
  cudaFuncSetAttribute((const void*)g_route133.std_kern,
                       cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g_route133.smem);
  // development (tuning): impl134 chtmd route (opt-in),
  // NVB==8. chtm_kernel<8,5,1,200,2,DEAL=1> — impl87's exact persistent
  // NSRC=9 dataflow and smem geometry with the named-barrier-9 TMEM
  // dealloc-early handoff (see the chtm_kernel DEAL comment). Bit-
  // identical outputs to impl87 by construction.
  g_route134.std_kern = chtm_kernel<8, 5, 1, 200, 2, 0, 0, 1>;
  g_route134.nthreads = 384;
  g_route134.grid_occ = 1;
  g_route134.smem = (size_t)2 * 5 * ROWB + 32 + (size_t)(32 * 5 + 16) * 4 + 16;
  cudaFuncSetAttribute((const void*)g_route134.std_kern,
                       cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g_route134.smem);
  g_route139.std_kern = chtclc_kernel<8, 5, 1, 200, 2, 0, 0, 1>;
  g_route139.nthreads = 384;
  g_route139.grid_occ = 1;
  g_route139.smem = (size_t)2 * 5 * ROWB + 32 + (size_t)(32 * 5 + 16) * 4 + 16 + 64;
  cudaFuncSetAttribute((const void*)g_route139.std_kern,
                       cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g_route139.smem);
  // development (tuning): impl140 chtcw route (OPT-IN via
  // K3_CMCW=1, NVB==8 persistent band T > 151). chtm deal=1 with MCW=1:
  // cluster dim 2; rank 0 issues ONE TMA multicast of cw/out_weight into
  // both cluster peers' smem staging (bar_v, per-copy expect_tx 2*ROWB);
  // each CTA processes distinct tokens on the unchanged CH=5/NS=2 ring;
  // consumers read cw/ow slices from smem for the TMEM staging pass.
  // smem: production chtm + 2*ROWB staging + bar_v (16B-rounded).
  g_route140.std_kern = chtm_kernel<8, 5, 1, 200, 2, 0, 0, 1, 1>;
  g_route140.nthreads = 384;
  g_route140.grid_occ = 1;
  g_route140.cluster = 2;
  g_route140.smem = (size_t)2 * 5 * ROWB + 32 + (size_t)(32 * 5 + 16) * 4 + 16 + 2 * ROWB + 16;
  cudaFuncSetAttribute((const void*)g_route140.std_kern,
                       cudaFuncAttributeMaxDynamicSharedMemorySize, (int)g_route140.smem);
  // development (tuning): impl135 leanS3 route, NVB==2 band.
  // leanS3_kernel<3>: grid = T static one-CTA-per-token (grid_occ 0),
  // 224 threads, direct vectorized global loads with rows register-
  // resident, no TMA/TMEM/mbarrier/token-loop machinery (see the kernel
  // comment). Dynamic smem = s_part[3][224] f32x2 + s_score + s_qp.
  // development (tuning): impl136 chpg — static CTA-per-token
  // clones of the persistent chp production route for the formerly
  // unspecialized NVB values 3/5/6/7 (PRODUCTION per-NVB bands at
  // chpg_band(); K3_IMPL=136 opt-in / A/B). Same kernel template params,
  // thread count and smem geometry as the persistent g_route85 entry for
  // the same NVB; grid = T (grid_occ 0).
  for (int nvb = 0; nvb <= 8; ++nvb) {
    PreresRoute& r = g_route136[nvb];
    switch (nvb) {
      case 3:
        r.std_kern = (decltype(r.std_kern))chpg_kernel<3, 4, 1, 200>;
        break;
      case 5:
        r.std_kern = (decltype(r.std_kern))chpg_kernel<5, 3, 1, 200>;
        break;
      case 6:
        r.std_kern = (decltype(r.std_kern))chpg_kernel<6, 4, 1, 200>;
        break;
      case 7:
        r.std_kern = (decltype(r.std_kern))chpg_kernel<7, 4, 1, 200>;
        break;
      default:
        r.std_kern = nullptr;
        break;
    }
    if (!r.std_kern) continue;
    const int ch = (nvb == 1) ? 2 : (nvb == 4 || nvb == 8) ? 5 : (nvb == 5) ? 3 : 4;
    r.nthreads = 384;
    r.grid_occ = 0;
    r.smem = (size_t)2 * ch * ROWB + 32 + (size_t)(32 * ch + 16) * 4;
    cudaFuncSetAttribute((const void*)r.std_kern, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)r.smem);
  }
  // development (tuning): impl137 chtmdg — the STATIC grid=T
  // clone of impl134 chtmd (chtgd_kernel<8,5,1,200>): chtmd's exact
  // 384-thread dataflow, NS=2/CH=5 TMA ring, TMEM cw/ow staging and
  // named-barrier-9 dealloc-early handoff, with the persistent
  // grid-stride token loop replaced by token = blockIdx.x, grid = T —
  // isolating static scheduling from the persistent loop while keeping
  // the same TMA pipeline and full fused math. Same geometry/smem as
  // g_route134; grid_occ 0 (grid = T). Candidate route: opt-in via
  // K3_IMPL=137 / forward_preres; production band pending this round's
  // order-reversed cold-L2 A/B at the (T=nvb8: 128, 256, 512) rows.
  //
  // R105 A/B RESULT (r105_ab.py, ABBA order-reversed, cold-L2
  // --cache-control all --clock-control none, n=32 launches/arm,
  // medians stable across both orders): FALSIFIED at the target row.
  //   T=256 nvb=8: impl137 14.128 us vs impl134 11.632 us = +21.46%
  //   (A arms 11.600/11.648, B arms 14.112/14.160, consistent).
  // The static grid=T clone is decisively slower than the persistent
  // grid-stride chtmd at T=256 (1.68 waves of nsm=152), unlike the
  // nvb 3..7 chpg and nvb=4 chtgd static clones which only win strictly
  // sub-wave (R100/R104). The T=256-NVB=8 gate row (0.844x) is NOT
  // scheduling-overhead-bound; static scheduling at/over one full wave
  // is the wrong direction for NSRC=9. Retention rule (win T=256 AND
  // T=128 AND T=512) unmet at the first conjunct -> opt-in only,
  // dispatch mirror rows untouched. Bit-identical to impl134 at 35/35
  // probed T (r105_check.py), so zero correctness risk either way.
  // development (tuning): impl138 epdl — lean one-CTA-per-token
  // static variant (grid = T) with the PDL trigger immediately after ALL
  // reads are issued (stage-all cp.async.bulk TMA: R rows + cw + ow into
  // smem, trigger, then mbar-wait + full fused FP32 tail). Targets the
  // failing T=4/NVB=2 and T=32/NVB=4 gate rows; the epdl_kernel comment
  // carries the mechanism/soundness argument. RETAINED this round —
  // measured evidence at epdl2_bound()/epdl4_bound() below (ABBA order-
  // reversed cold-L2 NCU wins at every band point, losses past the
  // static-wave edge; bit-identical outputs to both replaced routes at
  // 42/42 cases). Opt-in route: K3_IMPL=138 / forward_preres; production
  // cutover T <= 288 per nvb via K3_EPDL2_T / K3_EPDL4_T (0 restores the
  // R101/R100 routes).
  g_route138[0].std_kern = epdl_kernel<2>;
  g_route138[1].std_kern = epdl_kernel<4>;
  for (int i = 0; i < 2; ++i) {
    const int rr = i == 0 ? 3 : 5;  // NSRC
    PreresRoute& r = g_route138[i];
    r.nthreads = 256;
    r.grid_occ = 0;
    r.smem = (size_t)(rr + 2) * ROWB + 8 + (size_t)(16 * rr + 8) * 4;
    cudaFuncSetAttribute((const void*)r.std_kern, cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)r.smem);
  }
}

// development: epdl band cutovers (dimension-only) — RETAINED after the
// measured ABBA order-reversed cold-L2 NCU A/B (r106_ab.py,
// --cache-control all --clock-control none, n=32 launches/arm, medians
// stable across both orders; structural deltas below; the fixed-runner
// A/B evidence is at the python _EPDL2/_EPDL4 mirror comment):
//   nvb=2 vs impl133 chp3: wins EVERY point T=1..288
//     (-0.72/-6.21/-4.86/-2.42/-2.05/-1.03/-2.34/-0.64/-2.06/-4.75/-4.48/
//      -5.29% @1/4/8/16/32/48/64/96/152/256/272/288) and loses past the
//     3-CTA/SM static-wave edge +1.16/+1.49/+6.16/+10.58/+10.28% @320/
//     384/448/512/1024 -> band T <= 288.
//   nvb=4 vs impl131 chtgd (T<=152) / impl87 chtm (T>152): wins EVERY
//     point T=1..288 (-8.28/-7.65/-10.47/-8.01/-9.28/-8.29/-9.19/-8.03/
//     -7.07/-5.15/-4.40/-3.55/-10.63/-8.56/-7.91/-6.66% @1/2/3/4/8/16/
//     32/48/64/96/128/152/153/256/272/288) and loses +7.77/+15.79/+9.98%
//     @320/448/512 -> band T <= 288, displacing 131 in [1,152] and 87 in
//     [153,288]. K3_EPDL2_T / K3_EPDL4_T override for reproduction
//     (0 restores the R101/R100 production routes).
static int epdl2_bound() {
  static int b = -2;
  if (b == -2) {
    const char* s = getenv("K3_EPDL2_T");
    b = (s && s[0]) ? atoi(s) : 288;
  }
  return b;
}
static int epdl4_bound() {
  static int b = -2;
  if (b == -2) {
    const char* s = getenv("K3_EPDL4_T");
    b = (s && s[0]) ? atoi(s) : 288;
  }
  return b;
}

// =====================================================================
// FlashInfer VibeCUDA port — frozen production dispatch.
//
// Verbatim port of the seed C++ K3Plan dispatch ladder + launch geometry
// (development sm100 / development sm103, PLANC production path) with the
// K3_* experiment knobs kept at their seed defaults:
//   K3_PDL default ON (launch attr below additionally honors the
//     FlashInfer API's enable_pdl argument),
//   K3_PLAIN default off, K3_CMCW default off, K3_PDLR default on (impl112
//     band active), K3_CHTMD/K3_CHP3/K3_CHTGD default on, K3_CHTG_T
//     default = runtime SM count, K3_CHPG_T default per-NVB band
//     {3:32, 5:96, 6:4, 7:1}..nsm, K3_EPDL2_T/K3_EPDL4_T default 288,
//   K3_LEAN5_T / K3_LEANS3_T / K3_CHTGD3_T default 0 (off).
// Every launch issues the SAME kernel function pointer, argument values,
// grid, block, dynamic smem, stream and PDL attribute as the seed ladder
// it replaces; arithmetic is bit-identical by construction.
// =====================================================================
namespace vibecuda_k3 {

static int select_impl(int nvb, int T) {
  if (nvb == 0) return 97;
  if (nvb == 1)
    return (T <= 56) ? 97 : 87;
  else if (nvb == 8)
    return (56 < T && T <= 151)
               ? 112                    // pdlr band (K3_PDLR default on)
               : (cmcw_enabled() ? 140  // K3_CMCW opt-in chtcw cluster mcw
                                 : ((T > 2048 && g_preres_nsm == 152)
                                        ? 139
                                        : (T <= 2048 && chtmd_enabled() ? 134 : 87)));
  else if (nvb == 4)
    return (T <= epdl4_bound()) ? 138 : (T <= chtg_bound()) ? (chtgd_enabled() ? 131 : 126) : 87;
  else if (nvb == 7) {
    int lo, hi;
    chpg_band(nvb, lo, hi);
    if (T >= lo && T <= hi) return 136;
    if (T <= 287) return 85;
    return 87;
  } else if (nvb == 2)
    return (T <= epdl2_bound()) ? 138 : (chp3_enabled() ? 133 : 85);
  else {
    int lo, hi;
    chpg_band(nvb, lo, hi);
    if (T >= lo && T <= hi) return 136;  // nvb in (3, 5, 6)
    // Measured crossover (GB200, CUPTI median, 2026-10-25): the TMEM
    // persistent route 87 trails 85 by up to ~3% below T=1024, ties at
    // 1024..1536, and wins ~1.3%/2.0%/2.6% at T=2048/3072/4096 for nvb=6
    // (81.6..82.3us vs 83.7..84.4us at T=4096 across repeated A/B pairs);
    // nvb=3 and nvb=5 tie 85 within noise everywhere, so only nvb=6 adopts
    // 87 and only for the large-T tail. Tiny T (below the chpg band) keeps
    // 85: route 87 measured 11-15% slower at T<=3.
    if (nvb == 6 && T >= 2048) return 87;
    return 85;
  }
}

static const PreresRoute* route_for(int impl, int nvb) {
  if (impl == 85 && nvb >= 1 && nvb <= 8) return &g_route85[nvb];
  if (impl == 87 && nvb >= 1 && nvb <= 8) return &g_route87[nvb];
  if (impl == 97 && nvb >= 0 && nvb <= 8) return &g_routeF[nvb + 1];
  if (impl == 108 && nvb == 8) return &g_route108;
  if (impl == 112 && (nvb == 4 || nvb == 8)) return &g_route112[nvb == 4 ? 0 : 1];
  if (impl == 126 && nvb == 4) return &g_route126;
  if (impl == 131 && nvb == 4) return &g_route131;
  if (impl == 133 && nvb == 2) return &g_route133;
  if (impl == 134 && nvb == 8) return &g_route134;
  if (impl == 139 && nvb == 8) return &g_route139;
  if (impl == 140 && nvb == 8) return &g_route140;
  if (impl == 136 && nvb >= 3 && nvb <= 7 && g_route136[nvb].std_kern != nullptr)
    return &g_route136[nvb];
  if (impl == 138 && (nvb == 2 || nvb == 4)) return &g_route138[nvb == 2 ? 0 : 1];
  return nullptr;
}

}  // namespace vibecuda_k3

// C-linkage entry points consumed by vibecuda_kimi_k3_attn_res_binding.cu
// (same JIT module, one translation unit per side).

// One-time route-table + cudaFuncSetAttribute initialization (must run
// before CUDA graph capture). Returns 0 on success.
int vibecuda_k3_init_host() {
  if (!g_preres_nsm) preres_init();
  return g_preres_nsm > 0 ? 0 : -1;
}

int vibecuda_k3_num_sms() {
  if (!g_preres_nsm) preres_init();
  return g_preres_nsm;
}

// Diagnostic: packed-bank route (impl id) the frozen ladder selects for
// (nvb, T), or -1 when the route table cannot serve it.
int vibecuda_k3_route_id(long long nvb, long long T) {
  if (!g_preres_nsm) preres_init();
  if (nvb < 0 || nvb > 8) return -1;
  const int impl = vibecuda_k3::select_impl((int)nvb, (int)T);
  const PreresRoute* r = vibecuda_k3::route_for(impl, (int)nvb);
  if (r == nullptr || (r->std_kern == nullptr && r->lean_kern == nullptr)) return -1;
  return impl;
}

// Launch one production call. Returns 0 (cudaSuccess) or the cudaError_t
// value; -1001 flags an uncovered route (cannot happen through the public
// prepare path, which validates the route first).
int vibecuda_k3_run(const void* prefix, const void* bank, const void* cw, const void* ow, void* out,
                    long long T_, long long nvb_, long long stride_bm, double eps_,
                    long long enable_pdl, void* stream_) {
  if (!g_preres_nsm) preres_init();
  const int T = (int)T_;
  const int nvb = (int)nvb_;
  const float eps = (float)eps_;
  cudaStream_t stream = (cudaStream_t)stream_;
  // leanF reads packed bank rows; the existing strided route handles
  // a bank capacity or leading-row pitch larger than the active K=1.
  const int impl = (nvb == 1 && stride_bm != H) ? 87 : vibecuda_k3::select_impl(nvb, T);
  const PreresRoute* r = vibecuda_k3::route_for(impl, nvb);
  if (r == nullptr || (r->std_kern == nullptr && r->lean_kern == nullptr)) return -1001;
  int ngrid = r->grid_occ ? (T < g_preres_nsm * r->grid_occ ? T : g_preres_nsm * r->grid_occ) : T;
  // Balanced persistent grid in the nvb==8 impl134 mid band (seed R128).
  if (nvb == 8 && impl == 134 && r->grid_occ == 1 && T > g_preres_nsm) {
    const int kb = (T + g_preres_nsm - 1) / g_preres_nsm;
    const int gb = (T + kb - 1) / kb;
    if (gb < ngrid) ngrid = gb;
  }
  if (impl == 139 && nvb == 8 && T > g_preres_nsm) {
    const int per = (T + g_preres_nsm - 1) / g_preres_nsm;
    const int gb2 = (T + per - 1) / per;
    ngrid = gb2 + (T - (per - 1) * gb2);
  }
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3((unsigned)ngrid, 1, 1);
  cfg.blockDim = dim3((unsigned)r->nthreads, 1, 1);
  cfg.dynamicSmemBytes = r->smem;
  cfg.stream = stream;
  cudaLaunchAttribute attrs[2];
  attrs[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;
  attrs[0].val.programmaticStreamSerializationAllowed = (enable_pdl && pdl_enabled()) ? 1 : 0;
  cfg.numAttrs = 1;
  if (r->cluster > 1) {  // cluster launch, even grid (K3_CMCW opt-in)
    if (ngrid & 1) ++ngrid;
    cfg.gridDim = dim3((unsigned)ngrid, 1, 1);
    attrs[1].id = cudaLaunchAttributeClusterDimension;
    attrs[1].val.clusterDim.x = (unsigned)r->cluster;
    attrs[1].val.clusterDim.y = 1;
    attrs[1].val.clusterDim.z = 1;
    cfg.numAttrs = 2;
  }
  cfg.attrs = attrs;
  const bf16* p = reinterpret_cast<const bf16*>(prefix);
  const bf16* b = reinterpret_cast<const bf16*>(bank);
  const bf16* cwp = reinterpret_cast<const bf16*>(cw);
  const bf16* owp = reinterpret_cast<const bf16*>(ow);
  bf16* op = reinterpret_cast<bf16*>(out);
  cudaError_t rc;
  if (plain_launch_enabled() && r->cluster <= 1) {  // K3_PLAIN opt-in
    if (r->lean_kern != nullptr) {
      plain_launch_lean(r->lean_kern, (unsigned)ngrid, (unsigned)r->nthreads, r->smem, stream, p, b,
                        cwp, owp, op, T, nvb, eps);
    } else {
      plain_launch_std(r->std_kern, (unsigned)ngrid, (unsigned)r->nthreads, r->smem, stream, p, b,
                       cwp, owp, op, T, stride_bm, eps);
    }
    rc = cudaGetLastError();
  } else if (r->lean_kern != nullptr) {
    rc = cudaLaunchKernelEx(&cfg, r->lean_kern, p, b, cwp, owp, op, T, nvb, eps);
  } else {
    rc = cudaLaunchKernelEx(&cfg, r->std_kern, p, b, cwp, owp, op, T, stride_bm, eps);
  }
  return (rc == cudaSuccess) ? 0 : (int)rc;
}
